			version2:    "v1.10.0",
			stdResult:   true,
			expectError: false,
		},
		{
			name:        "version1 equal to version2",
			version1:    "v1.10.0",
			version2:    "v1.10.0",
			stdResult:   false,
			expectError: false,
		},
		{
			name:        "version1 greater than version2",
			version1:    "v1.11.0",
			version2:    "v1.10.0",
			stdResult:   false,
			expectError: false,
		},
		{
			name:        "version1 is less and has major version difference",
			version1:    "v1.9.0",
			version2:    "v2.0.0",
			stdResult:   true,
			expectError: false,
		},
		{
			name:        "version1 is less and has patch version difference",
			version1:    "v1.10.0",
			version2:    "v1.10.1",
			stdResult:   true,
			expectError: false,
		},
		{
			name:        "Invalid version1",
			version1:    "invalid",
			version2:    "v1.10.0",
			stdResult:   false,
			expectError: true,
		},
		{
			name:        "Invalid version2",
			version1:    "v1.10.0",
			version2:    "invalid",
			stdResult:   false,
			expectError: true,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			result, err := VersionLess(test.version1, test.version2)

			if test.expectError {
				assert.Error(err)
			} else {
				assert.NoError(err)
			}

			assert.Equal(test.stdResult, result)
