func GenerateTestCertificate(path string, certFileName string, keyFileName string) error {
	template := &x509.Certificate{
		IsCA:                  true,
		BasicConstraintsValid: true,
		SubjectKeyId:          []byte{1, 2, 3},
		SerialNumber:          big.NewInt(1234),
		Subject: pkix.Name{
			Country:      []string{"test"},
			Organization: []string{"tester"},
		},
		DNSNames:    []string{"localhost"},
		NotBefore:   time.Now(),
		NotAfter:    time.Now().AddDate(5, 5, 5),
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth, x509.ExtKeyUsageServerAuth},
		KeyUsage:    x509.KeyUsageDigitalSignature | x509.KeyUsageCertSign,
	}
	// generate private key
	privateKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return err
	}
	publicKey := &privateKey.PublicKey
	// create a self-signed certificate. template = parent
	var parent = template
	cert, err := x509.CreateCertificate(rand.Reader, template, parent, publicKey, privateKey)
	if err != nil {
		return err
	}
	err = os.MkdirAll(path, 0777)
	if err != nil {
		return err
	}
	pKey := x509.MarshalPKCS1PrivateKey(privateKey)
	certFilePEM := pem.Block{
		Type:  certutil.CertificateBlockType,
		Bytes: cert}
	err = createPEMfile(path+certFileName+".crt", certFilePEM)
	if err != nil {
		return err
	}
	keyFilePEM := pem.Block{
		Type:  "RSA PRIVATE KEY",
		Bytes: pKey,
	}

	return createPEMfile(path+keyFileName+".key", keyFilePEM)
}

func createPEMfile(path string, pemBlock pem.Block) error {
	// this will create plain text PEM file.
	file, err := os.Create(path)
	if err != nil {
		return err
	}

	defer func() {
		err := file.Close()
		if err != nil {
			klog.Errorf("failed to close file, path: %v, error: %v", path, err)
		}
	}()

	return pem.Encode(file, &pemBlock)
}

func (client *URLClient) HTTPDo(method, rawURL string, headers http.Header, body []byte) (resp *http.Response, err error) {
	client.clientHasPrefix(rawURL, "https")

	if headers == nil {
		headers = make(http.Header)
	}

	if _, ok := headers["Accept"]; !ok {
		headers["Accept"] = []string{"*/*"}
	}
	if _, ok := headers["Accept-Encoding"]; !ok && client.options.Compressed {
		headers["Accept-Encoding"] = []string{"deflate, gzip"}
	}

	req, err := http.NewRequest(method, rawURL, bytes.NewBuffer(body))
	if err != nil {
		return nil, err
	}
	client.Request = req

	req.Header = headers
	//sign a request
	if SignRequest != nil {
		if err = SignRequest(req); err != nil {
			return nil, errors.New("add auth info failed, err: " + err.Error())
		}
	}
	resp, err = client.Client.Do(req)
	if err != nil {
		return nil, err
	}

	return resp, nil
}

func (client *URLClient) clientHasPrefix(url, pro string) {
	if strings.HasPrefix(url, pro) {
		if transport, ok := client.Client.Transport.(*http.Transport); ok {
			transport.TLSClientConfig = client.TLS
		}
	}
}

func GetURLClient(option *URLClientOption) (client *URLClient, err error) {
	if option == nil {
		option = DefaultURLClientOption
	} else {
		switch {
		case option.HandshakeTimeout == 0:
			option.HandshakeTimeout = DefaultURLClientOption.HandshakeTimeout
			fallthrough
		case option.ResponseHeaderTimeout == 0:
			option.ResponseHeaderTimeout = DefaultURLClientOption.HandshakeTimeout
		}
	}

	if !option.SSLEnabled {
		client = &URLClient{
			Client: &http.Client{
				Transport: &http.Transport{
					TLSHandshakeTimeout:   option.HandshakeTimeout,
					ResponseHeaderTimeout: option.ResponseHeaderTimeout,
					DisableCompression:    !option.Compressed,
				},
			},
			options: *option,
		}

		return
	}

	client = &URLClient{
		Client: &http.Client{
			Transport: &http.Transport{
				TLSHandshakeTimeout:   option.HandshakeTimeout,
				ResponseHeaderTimeout: option.ResponseHeaderTimeout,
				DisableCompression:    !option.Compressed,
			},
		},
		TLS:     option.TLSConfig,
		options: *option,
	}
	return
}

