func (ns *NodeSession) deleteSuccessPoint(resourceNamespace, objectSyncName string, msg *beehivemodel.Message) {
	if resourceNamespace == v2.NullNamespace {
		err := ns.reliableClient.
			ReliablesyncsV1alpha1().ClusterObjectSyncs().
			Delete(context.Background(), objectSyncName, *metav1.NewDeleteOptions(0))
		if err != nil && !apierrors.IsNotFound(err) {
			klog.Errorf("Delete ClusterObjectSync %s error: %v", objectSyncName, err)
		}
	} else {
		err := ns.reliableClient.
			ReliablesyncsV1alpha1().
			ObjectSyncs(resourceNamespace).
			Delete(context.Background(), objectSyncName, *metav1.NewDeleteOptions(0))
		if err != nil && !apierrors.IsNotFound(err) {
			klog.Errorf("Delete ObjectSync %s/%s error: %v", resourceNamespace, objectSyncName, err)
		}
	}

	if err := ns.nodeMessagePool.AckMessageStore.Delete(msg); err != nil {
		klog.Errorf("failed to delete message %v, err: %v", msg, err)
	}
}

func TestNodeSessionKeepAliveCheck(t *testing.T) {
	tests := []struct {
		// Name of the test, for logging
		name                  string
		SendKeepaliveInterval time.Duration
		SimulateNormal        bool
	}{
		{
			name:                  "Send keepalive normally",
			SendKeepaliveInterval: tf.NormalSendKeepaliveInterval,
			SimulateNormal:        true,
		},
		{
			name:                  "Send keepalive exception",
			SendKeepaliveInterval: tf.AbnormalSendKeepaliveInterval,
			SimulateNormal:        false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Initialize the node session
			client := &fake.Clientset{}

			wg := sync.WaitGroup{}
			stopCh := make(chan struct{})

			session, mockController, mockConn := openNodeSession(t, &wg, stopCh, tt.SendKeepaliveInterval, client)
			defer mockController.Finish()

			mockConn.EXPECT().Close().AnyTimes()

			if tt.SimulateNormal {
				after := time.After(5 * time.Second)
				checkTicker := time.NewTicker(tt.SendKeepaliveInterval)

			TEST:
				for {
					select {
					case <-after:
						close(stopCh)
						wg.Wait()
						break TEST
					case <-checkTicker.C:
						if session.GetTerminateErr() != NoErr {
							t.Errorf("Expected %d got %d", NoErr, session.terminateErr)
						}
					}
				}
			} else {
				time.Sleep(tt.SendKeepaliveInterval)

				close(stopCh)
				wg.Wait()

				if session.GetTerminateErr() != TransportErr {
					t.Errorf("Expected %d got %d", TransportErr, session.terminateErr)
				}
			}
		})
	}
}

