func (ms *EdgedMetricsConnection) receiveFromCloudStream(stop chan struct{}) {
	for mess := range ms.ReadChan {
		if mess.MessageType == MessageTypeRemoveConnect {
			klog.Infof("receive remove client id %v", mess.ConnectID)
