func (dm *DTModule) InitWorker(recv chan interface{}, confirm chan interface{}, heartBeat chan interface{}, dtContext *dtcontext.DTContext) {
	worker := dtmanager.Worker{
		ReceiverChan:  recv,
		ConfirmChan:   confirm,
		HeartBeatChan: heartBeat,
		DTContexts:    dtContext,
	}
	switch dm.Name {
	case dtcommon.MemModule:
		dm.Worker = dtmanager.MemWorker{
			Group:  dtcommon.MemModule,
			Worker: worker,
		}
	case dtcommon.TwinModule:
		dm.Worker = dtmanager.TwinWorker{
			Group:  dtcommon.TwinModule,
			Worker: worker,
		}
	case dtcommon.DeviceModule:
		dm.Worker = dtmanager.DeviceWorker{
			Group:  dtcommon.DeviceModule,
			Worker: worker,
		}
	case dtcommon.CommModule:
		dm.Worker = dtmanager.CommWorker{
			Group:  dtcommon.CommModule,
			Worker: worker,
		}
	case dtcommon.DMIModule:
		dm.Worker = dtmanager.DMIWorker{
			Group: dtcommon.DMIModule,
			Worker: dtmanager.Worker{
				ReceiverChan:  recv,
				ConfirmChan:   confirm,
				HeartBeatChan: heartBeat,
				DTContexts:    dtContext,
			},
		}
	}
}

func (dm DTModule) Start() {
	defer func() {
		if err := recover(); err != nil {
			klog.Errorf("%s in twin panic with err: %v", dm.Name, err)
		}
	}()
	dm.Worker.Start()
}

func backupNode(commontypes.NodeTaskRequest) (event fsm.Event) {
	event = fsm.Event{
		Type:   "Backup",
		Action: api.ActionSuccess,
	}
	var err error
	defer func() {
		if err != nil {
			event.Action = api.ActionFailure
			event.Msg = err.Error()
		}
	}()
	backupPath := filepath.Join(util.KubeEdgeBackupPath, version.Get().String())
	err = backup(backupPath)
	if err != nil {
		cleanErr := os.Remove(backupPath)
		if cleanErr != nil {
			klog.Warningf("clean backup path failed: %s", err.Error())
		}
		return
	}
	return event
}

func backup(backupPath string) error {
	config := options.GetEdgeCoreConfig()
	klog.Infof("backup start, backup path: %s", backupPath)
	if err := os.MkdirAll(backupPath, 0750); err != nil {
		return fmt.Errorf("mkdirall failed: %v", err)
	}

	// backup edgecore.db: copy from origin path to backup path
	if err := filecopy(config.DataBase.DataSource, filepath.Join(backupPath, "edgecore.db")); err != nil {
		return fmt.Errorf("failed to backup db: %v", err)
	}
	// backup edgecore.yaml: copy from origin path to backup path
	if err := filecopy(constants.DefaultConfigDir+"edgecore.yaml", filepath.Join(backupPath, "edgecore.yaml")); err != nil {
		return fmt.Errorf("failed to back config: %v", err)
	}
	// backup edgecore: copy from origin path to backup path
	if err := filecopy(filepath.Join(util.KubeEdgeUsrBinPath, util.KubeEdgeBinaryName), filepath.Join(backupPath, util.KubeEdgeBinaryName)); err != nil {
		return fmt.Errorf("failed to backup edgecore: %v", err)
	}
	return nil
}

func filecopy(src, dst string) error {
	sourceFileStat, err := os.Stat(src)
	if err != nil {
		return err
	}

	if !sourceFileStat.Mode().IsRegular() {
		return fmt.Errorf("%s is not a regular file", src)
	}

	source, err := os.Open(src)
	if err != nil {
		return err
	}
	defer source.Close()

	// copy file using src file mode
	destination, err := os.OpenFile(dst, os.O_RDWR|os.O_CREATE|os.O_TRUNC, sourceFileStat.Mode())
	if err != nil {
		return err
	}
	defer destination.Close()
	_, err = io.Copy(destination, source)
	return err
}

func rollbackNode(taskReq commontypes.NodeTaskRequest) (event fsm.Event) {
	event = fsm.Event{
		Type:   "Rollback",
		Action: api.ActionSuccess,
	}
	var err error
	defer func() {
		if err != nil {
			event.Action = api.ActionFailure
			event.Msg = err.Error()
		}
	}()

	var upgradeReq *commontypes.NodeUpgradeJobRequest
	upgradeReq, err = getTaskRequest(taskReq)
	if err != nil {
		return
	}

	err = rollback(upgradeReq)
	if err != nil {
		return
	}
	return event
}

func rollback(upgradeReq *commontypes.NodeUpgradeJobRequest) error {
	klog.Infof("Begin to run rollback command")
	rollBackCmd := fmt.Sprintf("keadm rollback edge --name %s --history %s >> /tmp/keadm.log 2>&1",
		upgradeReq.UpgradeID, version.Get())

	// run upgrade cmd to upgrade edge node
	// use nohup command to start a child progress
	command := fmt.Sprintf("nohup %s &", rollBackCmd)
	cmd := exec.Command("bash", "-c", command)
	s, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("run rollback command %s failed: %v, %s", command, err, s)
	}
	klog.Infof("!!! Finish rollback ")
	return nil
}

