func NewBaseResponse(statusCode int) *BaseResponse {
	return &BaseResponse{
		APIVersion: APIVersion,
		StatusCode: statusCode,
		TimeStamp:  time.Now().Format(time.RFC3339),
	}
}

func (rs *RestServer) InitRouter() {
	// Common
	rs.Router.HandleFunc(APIPing, rs.Ping).Methods(http.MethodGet)

	// DeviceRead
	rs.Router.HandleFunc(APIDeviceReadRoute, rs.DeviceRead).Methods(http.MethodGet)

	// GetDeviceMethod
	rs.Router.HandleFunc(APIGetDeviceMethodRoute, rs.GetDeviceMethod).Methods(http.MethodGet)

	// DeviceWrite
	rs.Router.HandleFunc(APIDeviceWriteRoute, rs.DeviceWrite).Methods(http.MethodGet)

	// Meta
	rs.Router.HandleFunc(APIMetaGetModelRoute, rs.MetaGetModel).Methods(http.MethodGet)

	// DataBase
	rs.Router.HandleFunc(APIDataBaseGetDataByID, rs.DataBaseGetDataByID).Methods(http.MethodGet)
}

func NewRestServer(devPanel global.DevPanel, httpPort string, options ...Option) *RestServer {
	if httpPort == "" {
		httpPort = "7777"
	}

	rest := &RestServer{
		IP:           "0.0.0.0",
		Port:         httpPort,
		Router:       mux.NewRouter(),
		WriteTimeout: 10 * time.Second,
		ReadTimeout:  10 * time.Second,
		devPanel:     devPanel,
	}
	for _, option := range options {
		option(rest)
	}
	return rest
}

func (rs *RestServer) StartServer() {
	rs.InitRouter()
	rs.server = &http.Server{
		Addr:         rs.IP + ":" + rs.Port,
		WriteTimeout: rs.WriteTimeout,
		ReadTimeout:  rs.ReadTimeout,
		Handler:      rs.Router,
	}
	if rs.CaCertFilePath == "" && (rs.KeyFilePath == "" || rs.CertFilePath == "") {
		// insecure
		klog.V(3).Info("Insecure communication, skipping server verification")
		err := rs.server.ListenAndServe()
		if err != nil {
			klog.Errorf("insecure http server error: %v", err)
			return
		}
	} else if rs.CaCertFilePath == "" && rs.KeyFilePath != "" && rs.CertFilePath != "" {
		// tls
		klog.V(3).Info("tls communication, https server start")
		err := rs.server.ListenAndServeTLS(rs.CertFilePath, rs.KeyFilePath)
		if err != nil {
			klog.Errorf("tls http server error: %v", err)
			return
		}
	} else if rs.CaCertFilePath != "" && rs.KeyFilePath != "" && rs.CertFilePath != "" {
		// mtls
		klog.V(3).Info("mtls communication, please provide client-key and client-cert to access service")
		// Configure the server to trust TLS client cert issued by your CA.
		certPool := x509.NewCertPool()
		if caCertPEM, err := os.ReadFile(rs.CaCertFilePath); err != nil {
			klog.Errorf("Error loading ca certificate file: %v", err)
			return
		} else if ok := certPool.AppendCertsFromPEM(caCertPEM); !ok {
			klog.Error("invalid cert in CA PEM")
			return
		}
		tlsConfig := &tls.Config{
			ClientAuth: tls.RequireAndVerifyClientCert,
			ClientCAs:  certPool,
		}
		rs.server.TLSConfig = tlsConfig
		err := rs.server.ListenAndServeTLS(rs.CertFilePath, rs.KeyFilePath)
		if err != nil {
			klog.Errorf("tls http server error: %v", err)
			return
		}
	} else {
		klog.Error("the certificate file provided is incomplete or does not match")
	}
}

func (rs *RestServer) sendResponse(
	writer http.ResponseWriter,
	request *http.Request,
	response interface{},
	statusCode int) {
	correlationID := request.Header.Get(CorrelationHeader)
	if correlationID != "" {
		writer.Header().Set(CorrelationHeader, correlationID)
	}
	writer.Header().Set(ContentType, ContentTypeJSON)
	writer.WriteHeader(statusCode)
	data, err := json.Marshal(response)
	if err != nil {
		klog.Errorf("marshal %s response error: %v", request.URL.Path, err)
		http.Error(writer, err.Error(), http.StatusInternalServerError)
	}
	_, err = writer.Write(data)
	if err != nil {
		klog.Errorf("write %s response error: %v", request.URL.Path, err)
		http.Error(writer, err.Error(), http.StatusInternalServerError)
	}
}

