func getAuthorizerAttributes(router beehivemodel.MessageRoute, hubInfo cloudhubmodel.HubInfo) (authorizer.Attributes, error) {
	var (
		resAttrs    *authorization.ResourceAttributes
		nonResAttrs *authorization.NonResourceAttributes
		extra       = make(map[string]authorization.ExtraValue)
		err         error
	)
	if isKubeedgeResourceMessage(router) {
		nonResAttrs = getKubeedgeResourceAttributes(router)

		// put this key into extra to tells authorizers that this message operates kubeedge resource
		extra[kubeedgeResourceKey] = authorization.ExtraValue{}
	} else {
		resAttrs, err = getBuiltinResourceAttributes(router)
		if err != nil {
			return nil, err
		}
	}

	spec := authorization.SubjectAccessReviewSpec{
		ResourceAttributes:    resAttrs,
		NonResourceAttributes: nonResAttrs,
		User:                  constants.NodesUserPrefix + hubInfo.NodeID,
		Groups:                []string{constants.NodesGroup},
		Extra:                 extra,
	}
	attrs := util.AuthorizationAttributesFrom(spec)
	return &attrs, nil
}

func isKubeedgeResourceMessage(router beehivemodel.MessageRoute) bool {
	switch router.Operation {
	case beehivemodel.ResponseOperation, beehivemodel.ResponseErrorOperation, beehivemodel.UploadOperation,
		taskutil.TaskPrePull, taskutil.TaskUpgrade, cloudhubmodel.OpKeepalive:
		return true
	}
	switch router.Source {
	case metaserver.MetaServerSource, cloudhubmodel.ResTwin:
		return true
	}
	if router.Resource == beehivemodel.ResourceTypeK8sCA || common.IsVolumeResource(router.Resource) {
		return true
	}

	_, resourceType, resourceName := splitResource(router.Resource)
	switch resourceType {
	case beehivemodel.ResourceTypeRuleStatus:
		return true
	}
	// kubeedge allows node to update a list of pod status
	if resourceType == beehivemodel.ResourceTypePodStatus && resourceName == "" {
		return true
	}

	return false
}

func getKubeedgeResourceAttributes(router beehivemodel.MessageRoute) *authorization.NonResourceAttributes {
	return &authorization.NonResourceAttributes{
		Path: router.Resource,
		Verb: router.Operation,
	}
}

func getBuiltinResourceAttributes(router beehivemodel.MessageRoute) (*authorization.ResourceAttributes, error) {
	namespace, resourceType, resourceName := splitResource(router.Resource)
	switch router.Operation {
	// nodestatus, podstatus is not allowed to insert
	case beehivemodel.InsertOperation:
		switch resourceType {
		case beehivemodel.ResourceTypePodStatus:
			resourceType = beehivemodel.ResourceTypePod
		case beehivemodel.ResourceTypeNodeStatus:
			resourceType = beehivemodel.ResourceTypeNode
		}
	}

	kubeRes, ok := resourceTypeToKubeResources[resourceType]
	if !ok {
		return nil, fmt.Errorf("unknown resource type %q", resourceType)
	}

	var verb string
	switch router.Operation {
	case beehivemodel.InsertOperation:
		verb = "create"
	case beehivemodel.DeleteOperation:
		verb = "delete"
	case beehivemodel.UpdateOperation:
		verb = "update"
	case beehivemodel.PatchOperation:
		verb = "patch"
	case beehivemodel.QueryOperation:
		verb = "get"
		// the actual verb for serviceaccounts/token is `create`
		if resourceType == beehivemodel.ResourceTypeServiceAccountToken {
			verb = "create"
		}
	default:
		return nil, fmt.Errorf("unknown opeation %q", router.Operation)
	}

	if !kubeRes.namespaced {
		namespace = ""
	}
	return &authorization.ResourceAttributes{
		Namespace:   namespace,
		Verb:        verb,
		Group:       kubeRes.groupVersion.Group,
		Version:     kubeRes.groupVersion.Version,
		Resource:    kubeRes.resource,
		Subresource: kubeRes.subresource,
		Name:        resourceName,
	}, nil
}

func splitResource(resource string) (namespace string, resourceType string, resourceName string) {
	sli := strings.Split(resource, "/")
	for i := len(sli); i < 3; i++ {
		sli = append(sli, "")
	}
	namespace, resourceType, resourceName = sli[0], sli[1], sli[2]
	return
}

func isKubeedgeResourceAttributes(attrs authorizer.Attributes) bool {
	if attrs == nil || attrs.GetUser() == nil {
		return false
	}
	_, ok := attrs.GetUser().GetExtra()[kubeedgeResourceKey]
	return ok
}

func ReportStatus(request *restful.Request, response *restful.Response) {
	resp := types.NodeTaskResponse{}
	taskID := request.PathParameter("taskID")
	taskType := request.PathParameter("taskType")
	nodeID := request.PathParameter("nodeID")

	lr := &io.LimitedReader{
		R: request.Request.Body,
		N: millionByte + 1,
	}
	body, err := io.ReadAll(lr)
	if err != nil {
		err = response.WriteError(http.StatusBadRequest, fmt.Errorf("failed to get req body: %v", err))
		if err != nil {
			klog.Warning(err.Error())
		}
		return
	}
	if lr.N <= 0 {
		err = response.WriteError(http.StatusBadRequest, errors.NewRequestEntityTooLargeError("the request body can only be up to 1MB in size"))
		if err != nil {
			klog.Warning(err.Error())
		}
		return
	}
	if err = json.Unmarshal(body, &resp); err != nil {
		err = response.WriteError(http.StatusBadRequest, fmt.Errorf("failed to unmarshal task info: %v", err))
		if err != nil {
			klog.Warning(err.Error())
		}
		return
	}

	msg := beehiveModel.NewMessage("").SetRoute(modules.CloudHubModuleName, modules.CloudHubModuleGroup).
		SetResourceOperation(fmt.Sprintf("task/%s/node/%s", taskID, nodeID), taskType).FillBody(resp)
	beehiveContext.Send(modules.TaskManagerModuleName, *msg)

	if _, err = response.Write([]byte("ok")); err != nil {
		klog.Errorf("failed to send the task resp to edge , err: %v", err)
	}
}

func UpgradeEdge(request *restful.Request, response *restful.Response) {
	resp := commontypes.NodeUpgradeJobResponse{}

	taskID := resp.UpgradeID
	taskType := util.TaskUpgrade
	nodeID := resp.NodeName

	lr := &io.LimitedReader{
		R: request.Request.Body,
		N: millionByte + 1,
	}
	body, err := io.ReadAll(lr)
	if err != nil {
		err = response.WriteError(http.StatusBadRequest, fmt.Errorf("failed to get req body: %v", err))
		if err != nil {
			klog.Warning(err.Error())
		}
		return
	}
	if lr.N <= 0 {
		err = response.WriteError(http.StatusBadRequest, errors.NewRequestEntityTooLargeError("the request body can only be up to 1MB in size"))
		if err != nil {
			klog.Warning(err.Error())
		}
		return
	}
	if err = json.Unmarshal(body, &resp); err != nil {
		err = response.WriteError(http.StatusBadRequest, fmt.Errorf("failed to marshal task info: %v", err))
		if err != nil {
			klog.Warning(err.Error())
		}
		return
	}
	newResp := commontypes.NodeTaskResponse{
		NodeName: resp.NodeName,
		Event:    "Upgrade",
		Action:   api.ActionSuccess,
		Reason:   resp.Reason,
	}

	if resp.Status == UpgradeFailedRollbackSuccess {
		newResp.Event = "Rollback"
		newResp.Action = api.ActionFailure
	}

	if resp.Status == UpgradeFailedRollbackFailed {
		newResp.Event = "Rollback"
		newResp.Action = api.ActionSuccess
	}

	msg := beehiveModel.NewMessage("").SetRoute(modules.CloudHubModuleName, modules.CloudHubModuleGroup).
		SetResourceOperation(fmt.Sprintf("task/%s/node/%s", taskID, nodeID), taskType).FillBody(newResp)
	beehiveContext.Send(modules.TaskManagerModuleName, *msg)

	if _, err = response.Write([]byte("ok")); err != nil {
		klog.Errorf("failed to send the task resp to edge , err: %v", err)
	}
}

func (r *statusReconciler) Reconcile(ctx context.Context, request controllerruntime.Request) (controllerruntime.Result, error) {
	edgeApp := &appsv1alpha1.EdgeApplication{}
	if err := r.Client.Get(ctx, request.NamespacedName, edgeApp); err != nil {
		if apierrors.IsNotFound(err) {
			return controllerruntime.Result{}, nil
		}
		klog.Errorf("failed to get edgeApp %s/%s, %v", request.Namespace, request.Name, err)
		return controllerruntime.Result{Requeue: true}, err
	}

	if !edgeApp.GetDeletionTimestamp().IsZero() {
		return controllerruntime.Result{}, nil
	}

	return r.sync(ctx, edgeApp)
}

func (r *statusReconciler) sync(ctx context.Context, edgeApp *appsv1alpha1.EdgeApplication) (controllerruntime.Result, error) {
	tmplInfos, err := utils.GetTemplatesInfosOfEdgeApp(edgeApp, r.Serializer)
	if err != nil {
		klog.Errorf("failed to get infos of templates in edgeApp %s/%s, continue with what has been got, err: %v", edgeApp.Namespace, edgeApp.Name, err)
	}

	for _, tmplInfo := range tmplInfos {
		tmpl := tmplInfo.Template
		gvk := tmpl.GroupVersionKind()
		if gvk != r.GroupVersionKind {
			// it's not managed by this reconciler
			continue
		}
		if _, ok := constants.OverriderTargetGVK[gvk]; !ok {
			if err := r.updateStatus(ctx, edgeApp, tmplInfo, availableIfExists{}); err != nil {
				klog.Errorf("failed to update status for edgeApp %s/%s, %v", edgeApp.Namespace, edgeApp.Name, err)
				return controllerruntime.Result{Requeue: true}, err
			}
		} else {
			// Apply overriders to get the actual template that applied to
			// each nodegroup. Currently, only NameOverrider is applied.
			overrideInfos := utils.GetAllOverriders(edgeApp)
			for _, overrideInfo := range overrideInfos {
				tmplCopy := tmpl.DeepCopy()
				if err := r.Overrider.ApplyOverrides(tmplCopy, overrideInfo); err != nil {
					klog.Errorf("failed to apply overrides to template %s/%s of gvk %s when updating status of edgeapp %s/%s, %v",
						tmplCopy.GetNamespace(), tmplCopy.GetName(), gvk, edgeApp.Namespace, edgeApp.Name, err)
					continue
				}
				// TODO:
				// Currently, only deployment will be override. So, we just use the deploymentAvailable here.
				// It a temporary strategy for convenience. When we need to support more GVK, a generic strategy
				// is needed.
				newTmplInfo := &utils.TemplateInfo{Ordinal: tmplInfo.Ordinal, Template: tmplCopy}
				if err := r.updateStatus(ctx, edgeApp, newTmplInfo, deploymentAvailable{}); err != nil {
					klog.Errorf("failed to update status for edgeApp %s/%s, %v", edgeApp.Namespace, edgeApp.Name, err)
					return controllerruntime.Result{Requeue: true}, err
				}
			}
		}
	}
	// Trigger reconciliation of edgeapplication controller
	// Considering that if an object created by edgeapplication controller is deleted by others,
	// only this controller watches its event, thus if it's status in edgeapplication resource is unchanged,
	// the deleted object will not be created until the next resync.
	r.ReoncileTriggerChan <- event.GenericEvent{Object: edgeApp.DeepCopy()}
	return controllerruntime.Result{}, nil
}

func (r *statusReconciler) updateStatus(
	ctx context.Context,
	edgeApp *appsv1alpha1.EdgeApplication,
	tmplInfo *utils.TemplateInfo,
	available available) error {
	info := utils.GetResourceInfoOfTemplateInfo(tmplInfo)
	isAvailable, err := available.IsAvailable(ctx, r.Client, info)
	if err != nil {
		klog.Errorf("failed to check the availability of obj %s/%s, %s/%s, kind: %s, %v",
			info.Namespace, info.Name, info.Group, info.Version, info.Kind, err)
	}
	if isAvailable {
		return r.update(ctx, edgeApp, info, appsv1alpha1.EdgeAppAvailable)
	}
	return r.update(ctx, edgeApp, info, appsv1alpha1.EdgeAppProcessing)
}

func (r *statusReconciler) update(
	ctx context.Context,
	edgeApp *appsv1alpha1.EdgeApplication,
	info utils.ResourceInfo,
	status appsv1alpha1.ManifestCondition) error {
	newStatus := appsv1alpha1.ManifestStatus{
		Identifier: appsv1alpha1.ResourceIdentifier{
			Ordinal:   info.Ordinal,
			Group:     info.Group,
			Version:   info.Version,
			Kind:      info.Kind,
			Namespace: info.Namespace,
			Name:      info.Name,
		},
		Condition: status,
	}

	var statusInEdgeApp *appsv1alpha1.ManifestStatus
	for i, status := range edgeApp.Status.WorkloadStatus {
		// find the existing status that need update
		if status.Identifier.Ordinal == info.Ordinal {
			if utils.IsIdentifierSameAsResourceInfo(status.Identifier, info) || utils.IsInitStatus(&status) {
				statusInEdgeApp = &edgeApp.Status.WorkloadStatus[i]
				break
			}
		}
	}
	if statusInEdgeApp == nil {
		// not found, add a new entry for it
		edgeApp.Status.WorkloadStatus = append(edgeApp.Status.WorkloadStatus, newStatus)
	} else if utils.IsInitStatus(statusInEdgeApp) || statusInEdgeApp.Condition != status {
		// the existing status needs to be updated
		*statusInEdgeApp = newStatus
	} else {
		// no need to update status
		klog.V(4).Infof("obj %s/%s of gvk %s/%s, %s has same status as what in edgeapp %s/%s, skip update status",
			info.Namespace, info.Name, info.Group, info.Version, info.Kind, edgeApp.Namespace, edgeApp.Name)
		return nil
	}

	sort.Slice(edgeApp.Status.WorkloadStatus, func(i, j int) bool {
		return edgeApp.Status.WorkloadStatus[i].Identifier.Ordinal < edgeApp.Status.WorkloadStatus[j].Identifier.Ordinal
	})
	if err := r.Client.Status().Update(ctx, edgeApp); err != nil {
		return fmt.Errorf("failed to update status of EdgeApplication %s/%s, %v", edgeApp.Namespace, edgeApp.Name, err)
	}
	klog.V(4).Infof("successfully update status of edgeapp %s/%s for obj %s/%s of gvk %s/%s, Kind %s with value %s",
		edgeApp.Namespace, edgeApp.Name, info.Namespace, info.Name, info.Group, info.Version, info.Kind, status)
	return nil
}

func (e availableIfExists) IsAvailable(ctx context.Context, client client.Client, info utils.ResourceInfo) (bool, error) {
	obj, err := getObjAccordingToResourceInfo(ctx, client, info)
	if err != nil {
		return false, err
	}
	if obj == nil {
		return false, err
	}

	deploy := &appsv1.Deployment{}
	if err := client.Scheme().Convert(obj, deploy, nil); err != nil {
		return false, fmt.Errorf("failed to convert unstructured to deployment for %s/%s, %v", info.Namespace, info.Name, err)
	}

	return deploy.Status.ReadyReplicas == *deploy.Spec.Replicas, nil
}

func (d deploymentAvailable) IsAvailable(ctx context.Context, client client.Client, info utils.ResourceInfo) (bool, error) {
	obj, err := getObjAccordingToResourceInfo(ctx, client, info)
	if err != nil {
		return false, err
	}
	if obj == nil {
		return false, err
	}

	deploy := &appsv1.Deployment{}
	if err := client.Scheme().Convert(obj, deploy, nil); err != nil {
		return false, fmt.Errorf("failed to convert unstructured to deployment for %s/%s, %v", info.Namespace, info.Name, err)
	}

	return deploy.Status.ReadyReplicas == *deploy.Spec.Replicas, nil
}

func getObjAccordingToResourceInfo(ctx context.Context, client client.Client, info utils.ResourceInfo) (*unstructured.Unstructured, error) {
	gvk := schema.GroupVersionKind{Group: info.Group, Version: info.Version, Kind: info.Kind}
	curObj := &unstructured.Unstructured{}
	curObj.SetGroupVersionKind(gvk)
	if err := client.Get(ctx, types.NamespacedName{Namespace: info.Namespace, Name: info.Name}, curObj); err != nil {
		if apierrors.IsNotFound(err) {
			klog.V(4).Infof("cannot find obj %s/%s of gvk %s", info.Namespace, info.Name, gvk)
			return nil, nil
		}
		klog.Errorf("failed to get obj %s/%s, gvk: %s, %v", info.Namespace, info.Name, gvk, err)
		return nil, err
	}
	return curObj, nil
}

func NewStatusManager(ctx context.Context, mgr manager.Manager, client client.Client, serializer runtime.Serializer) StatusManager {
	return &statusManager{
		ctx:        ctx,
		mtx:        sync.Mutex{},
		mgr:        mgr,
		client:     client,
		serializer: serializer,
		watching:   make(map[schema.GroupVersionKind]context.CancelFunc),
		watchCh:    make(chan schema.GroupVersionKind, 1024),
		cancelCh:   make(chan schema.GroupVersionKind, 1024),
	}
}

func (s *statusManager) WatchStatus(info utils.ResourceInfo) error {
	if !s.started {
		return fmt.Errorf("status manager has not started")
	}

	select {
	case s.watchCh <- infoToGVK(info):
	default:
		return fmt.Errorf("the watchCh of status manager is full, drop the info %s", info.String())
	}

	return nil
}

func (s *statusManager) CancelWatch(info utils.ResourceInfo) error {
	if !s.started {
		return fmt.Errorf("status manager has not started")
	}

	select {
	case s.cancelCh <- infoToGVK(info):
	default:
		return fmt.Errorf("the cancelCh of status manager is full, drop the info %s", info.String())
	}

	return nil
}

func (s *statusManager) Start() error {
	if s.reconcileTrigger == nil {
		return fmt.Errorf("reconcileTrigger cannot be nil")
	}
	s.started = true
	go s.watchStatusWorker()
	go s.cancelWatchWorker()
	go s.waitForTerminatingWorkers()
	go wait.Until(s.watchControllersGC, 5*time.Minute, s.ctx.Done())
	return nil
}

func (s *statusManager) SetReconcileTriggerChan(ch chan event.GenericEvent) {
	s.reconcileTrigger = ch
}

func (s *statusManager) watchStatusWorker() {
	for gvk := range s.watchCh {
		if s.isWatching(gvk) {
			continue
		}
		ctx, cancel := context.WithCancel(s.ctx)
		s.markAsWatching(gvk, cancel)
		if err := s.startToWatch(ctx, gvk); err != nil {
			s.unmarkWatching(gvk)
			klog.Errorf("failed to start to watch status for gvk %s, %v", gvk, err)
			// TODO: if need retry
			continue
		}
		klog.V(4).Infof("start to watch status of gvk %s", gvk)
	}
	klog.Info("watchStatusWorker exited")
}

func (s *statusManager) cancelWatchWorker() {
	for info := range s.cancelCh {
		if !s.isWatching(info) {
			continue
		}
		// cancel the controller which is watching this kind of resource
		s.unmarkWatching(info)
	}
	// cancel all watching controllers
	s.mtx.Lock()
	defer s.mtx.Unlock()
	for _, cancel := range s.watching {
		if cancel != nil {
			cancel()
		}
	}
	klog.Info("cancelWatchWorker exited")
}

func (s *statusManager) waitForTerminatingWorkers() {
	<-s.ctx.Done()
	close(s.watchCh)
	close(s.cancelCh)
}

func (s *statusManager) isWatching(gvk schema.GroupVersionKind) bool {
	s.mtx.Lock()
	defer s.mtx.Unlock()
	_, ok := s.watching[gvk]
	return ok
}

func (s *statusManager) markAsWatching(gvk schema.GroupVersionKind, cancel context.CancelFunc) {
	s.mtx.Lock()
	defer s.mtx.Unlock()
	s.watching[gvk] = cancel
}

func (s *statusManager) unmarkWatching(gvk schema.GroupVersionKind) {
	s.mtx.Lock()
	defer s.mtx.Unlock()
	if cancel := s.watching[gvk]; cancel != nil {
		cancel()
	}
	delete(s.watching, gvk)
}

func (s *statusManager) startToWatch(ctx context.Context, gvk schema.GroupVersionKind) error {
	controllerName := fmt.Sprintf("status-controller-for-%s/%s/%s", gvk.Group, gvk.Version, gvk.Kind)
	controller, err := controller.NewUnmanaged(controllerName, s.mgr, controller.Options{
		Reconciler: &statusReconciler{
			Client:              s.client,
			GroupVersionKind:    gvk,
			Serializer:          s.serializer,
			Overrider:           &overridemanager.NameOverrider{},
			ReoncileTriggerChan: s.reconcileTrigger,
		},
	})
	if err != nil {
		klog.Errorf("failed to get new unmanaged controller for gvk %s, %v", gvk, err)
		return err
	}

	watchObj := &unstructured.Unstructured{}
	watchObj.SetGroupVersionKind(gvk)
	hdler := handler.TypedEnqueueRequestForOwner[client.Object](s.mgr.GetScheme(), s.mgr.GetRESTMapper(), &appsv1alpha1.EdgeApplication{}, handler.OnlyControllerOwner())
	if err := controller.Watch(source.Kind[client.Object](s.mgr.GetCache(), watchObj, hdler)); err != nil {
		klog.Errorf("failed to add delete event watch to controller for gvk: %s, %v", gvk, err)
		return err
	}

	go func() {
		if err := controller.Start(ctx); err != nil {
			klog.Errorf("failed to start status controller for gvk %s, %v", gvk, err)
			return
		}
		klog.Infof("status controller stopped which was watching gvk %s", gvk)
	}()

	return nil
}

func (s *statusManager) watchControllersGC() {
	edgeAppList := &appsv1alpha1.EdgeApplicationList{}
	if err := s.client.List(s.ctx, edgeAppList); err != nil {
		klog.Errorf("failed to list EdgeApplication, %v", err)
		return
	}

	infoMap := make(map[schema.GroupVersionKind]struct{})
	for _, edgeApp := range edgeAppList.Items {
		infos, err := utils.GetContainedResourceInfos(&edgeApp, s.serializer)
		if err != nil {
			klog.Errorf("failed to get resourceInfos from edgeApp %s/%s, %v", edgeApp.Namespace, edgeApp.Name, err)
			continue
		}

		for _, info := range infos {
			infoMap[infoToGVK(info)] = struct{}{}
		}
	}

	s.mtx.Lock()
	defer s.mtx.Unlock()
	for gvk := range s.watching {
		if _, ok := infoMap[gvk]; !ok {
			// no edgeapplication need to watch status of this gvk, so cancel watch of it
			if err := s.CancelWatch(utils.ResourceInfo{Group: gvk.Group, Version: gvk.Version, Kind: gvk.Kind}); err != nil {
				klog.Errorf("statusControllersGC failed to cancel watch of gvk %s, %v", gvk, err)
				continue
			}
			klog.V(4).Infof("statusControllerGC cancel watch of gvk %s", gvk)
		}
	}
}

func infoToGVK(info utils.ResourceInfo) schema.GroupVersionKind {
	return schema.GroupVersionKind{
		Group:   info.Group,
		Version: info.Version,
		Kind:    info.Kind,
	}
}

