		name          string
		ExpectedSyncs int
		ObjectSyncs   *v1alpha1.ObjectSync
	}{
		{
			name:          "test deleteObjectSyncs false",
			ObjectSyncs:   tf.NewObjectSync(tf.NewTestPodResource(tf.TestPodName, tf.TestPodUID, "2"), "Pod"),
			ExpectedSyncs: 0,
		},
	}
	for _, tt := range tests {
		t.Run("deleteObjectSyncs()", func(t *testing.T) {
			crdClient := crdfake.NewSimpleClientset()
			crdInformers := crdinformers.NewSharedInformerFactory(crdClient, 0)
			err := crdInformers.Reliablesyncs().V1alpha1().ObjectSyncs().Informer().GetIndexer().Add(tt.ObjectSyncs)
			if err != nil {
				t.Errorf("deleteObjectSyncs() failed when create ObjectSyncs indexer, error: %v", err)
			}
			_, err = crdClient.ReliablesyncsV1alpha1().ObjectSyncs(tf.TestNamespace).Create(context.Background(), tt.ObjectSyncs, metav1.CreateOptions{})
			if err != nil {
				t.Errorf("deleteObjectSyncs() failed when create ObjectSyncs, error: %v", err)
			}
			client := fake.NewSimpleClientset()
			informers := informers.NewSharedInformerFactory(client, 0)
			testController := newSyncController(true)
			testController.nodeLister = informers.Core().V1().Nodes().Lister()
			testController.crdclient = crdClient
			testController.objectSyncLister = crdInformers.Reliablesyncs().V1alpha1().ObjectSyncs().Lister()
			syncs, _ := crdClient.ReliablesyncsV1alpha1().ObjectSyncs(tf.TestNamespace).List(context.Background(), metav1.ListOptions{})
			if len(syncs.Items) != 1 {
				t.Errorf("deleteObjectSyncs() list returned unexpected result. got = %v, want = %v", len(syncs.Items), 1)
			}
			testController.deleteObjectSyncs()
			got, _ := crdClient.ReliablesyncsV1alpha1().ObjectSyncs(tf.TestNamespace).List(context.Background(), metav1.ListOptions{})
			if len(got.Items) != tt.ExpectedSyncs {
				t.Errorf("deleteObjectSyncs() list returned unexpected result. got = %v, want = %v", len(got.Items), tt.ExpectedSyncs)
			}
		})
	}
}

func (sctl *SyncController) reconcileClusterObjectSync(sync *v1alpha1.ClusterObjectSync) {
	var object metav1.Object

	gv, err := schema.ParseGroupVersion(sync.Spec.ObjectAPIVersion)
	if err != nil {
		return
	}
	resource := util.UnsafeKindToResource(sync.Spec.ObjectKind)
	gvr := gv.WithResource(resource)
	nodeName := getNodeName(sync.Name)
	resourceType := strings.ToLower(sync.Spec.ObjectKind)

	lister, err := sctl.informerManager.GetLister(gvr)
	if err != nil {
		return
	}

	ret, err := lister.Get(sync.Spec.ObjectName)
	if apierrors.IsNotFound(err) {
		sctl.gcOrphanedClusterObjectSync(sync)
		return
	}

	if err != nil || ret == nil {
		klog.Errorf("failed to get obj(gvr:%v, name:%v): %v", gvr, sync.Spec.ObjectName, err)
		return
	}

	object, err = meta.Accessor(ret)
	if err != nil {
		klog.Errorf("failed to Accessor obj(gvr:%v, name:%v): %v", gvr, sync.Spec.ObjectName, err)
		return
	}

	syncObjUID := getObjectUID(sync.Name)
	if syncObjUID != string(object.GetUID()) {
		sctl.gcOrphanedClusterObjectSync(sync)
		return
	}

	sendClusterObjectSyncEvent(nodeName, sync, resourceType, object.GetResourceVersion(), object)
}

func (sctl *SyncController) gcOrphanedClusterObjectSync(sync *v1alpha1.ClusterObjectSync) {
	resourceType := strings.ToLower(sync.Spec.ObjectKind)
	nodeName := getNodeName(sync.Name)
	klog.V(4).Infof("%s: %s has been deleted in K8s, send the delete event to edge in sync loop", resourceType, sync.Spec.ObjectName)

	object := &unstructured.Unstructured{}
	object.SetName(sync.Spec.ObjectName)
	object.SetUID(types.UID(getObjectUID(sync.Name)))
	if msg := buildEdgeControllerMessage(nodeName, v2.NullNamespace, resourceType, sync.Spec.ObjectName, model.DeleteOperation, object); msg != nil {
		beehiveContext.Send(commonconst.DefaultContextSendModuleName, *msg)
	} else {
		if err := sctl.crdclient.ReliablesyncsV1alpha1().ClusterObjectSyncs().Delete(context.Background(), sync.Name, *metav1.NewDeleteOptions(0)); err != nil {
			klog.Errorf("Failed to delete clusterObjectSync %s: %v", sync.Name, err)
		}
	}
}

func sendClusterObjectSyncEvent(nodeName string, sync *v1alpha1.ClusterObjectSync, resourceType string,
	objectResourceVersion string, obj interface{}) {
	runtimeObj := obj.(runtime.Object)
	if err := util.SetMetaType(runtimeObj); err != nil {
		klog.Warningf("failed to set metatype :%v", err)
	}

	if sync.Status.ObjectResourceVersion == "" {
		klog.Errorf("The ObjectResourceVersion is empty in status of clusterObjectSync: %s", sync.Name)
		return
	}

	if CompareResourceVersion(objectResourceVersion, sync.Status.ObjectResourceVersion) > 0 {
		// trigger the update event
		klog.V(4).Infof("The resourceVersion: %s of %s in K8s is greater than in edgenode: %s, send the update event", objectResourceVersion, resourceType, sync.Status.ObjectResourceVersion)
		msg := buildEdgeControllerMessage(nodeName, v2.NullNamespace, resourceType, sync.Spec.ObjectName, model.UpdateOperation, obj)
		beehiveContext.Send(commonconst.DefaultContextSendModuleName, *msg)
	}
}

func (sctl *SyncController) reconcileObjectSync(sync *v1alpha1.ObjectSync) {
	var object metav1.Object

	gv, err := schema.ParseGroupVersion(sync.Spec.ObjectAPIVersion)
	if err != nil {
		return
	}
	resource := util.UnsafeKindToResource(sync.Spec.ObjectKind)
	gvr := gv.WithResource(resource)
	nodeName := getNodeName(sync.Name)
	resourceType := strings.ToLower(sync.Spec.ObjectKind)

	lister, err := sctl.informerManager.GetLister(gvr)
	if err != nil {
		return
	}

	ret, err := lister.ByNamespace(sync.Namespace).Get(sync.Spec.ObjectName)

	if apierrors.IsNotFound(err) {
		sctl.gcOrphanedObjectSync(sync)
		return
	} else if err != nil || ret == nil {
		klog.Errorf("failed to get obj(gvr:%v,namespace:%v,name:%v), %v", gvr, sync.Namespace, sync.Spec.ObjectName, err)
		return
	}

	object, err = meta.Accessor(ret)
	if err != nil {
		return
	}

	syncObjUID := getObjectUID(sync.Name)
	if syncObjUID != string(object.GetUID()) {
		sctl.gcOrphanedObjectSync(sync)
		return
	}

	sendEvents(nodeName, sync, resourceType, object.GetResourceVersion(), object)
}

func (sctl *SyncController) gcOrphanedObjectSync(sync *v1alpha1.ObjectSync) {
	resourceType := strings.ToLower(sync.Spec.ObjectKind)
	nodeName := getNodeName(sync.Name)
	klog.V(4).Infof("%s: %s has been deleted in K8s, send the delete event to edge in sync loop", resourceType, sync.Spec.ObjectName)

	object := &unstructured.Unstructured{}
	object.SetNamespace(sync.Namespace)
	object.SetName(sync.Spec.ObjectName)
	object.SetUID(types.UID(getObjectUID(sync.Name)))
	if msg := buildEdgeControllerMessage(nodeName, sync.Namespace, resourceType, sync.Spec.ObjectName, model.DeleteOperation, object); msg != nil {
		beehiveContext.Send(commonconst.DefaultContextSendModuleName, *msg)
	} else {
		if err := sctl.crdclient.ReliablesyncsV1alpha1().ObjectSyncs(sync.Namespace).Delete(context.Background(), sync.Name, *metav1.NewDeleteOptions(0)); err != nil {
			klog.Errorf("Failed to delete objectsync %s: %v", sync.Name, err)
		}
	}
}

func sendEvents(nodeName string, sync *v1alpha1.ObjectSync, resourceType string,
	objectResourceVersion string, obj interface{}) {
	if sync.Status.ObjectResourceVersion == "" {
		klog.Errorf("The ObjectResourceVersion is empty in status of objectsync: %s", sync.Name)
		return
	}

	if CompareResourceVersion(objectResourceVersion, sync.Status.ObjectResourceVersion) > 0 {
		// trigger the update event
		klog.V(4).Infof("The resourceVersion: %s of %s in K8s is greater than in edgenode: %s, send the update event", objectResourceVersion, resourceType, sync.Status.ObjectResourceVersion)
		msg := buildEdgeControllerMessage(nodeName, sync.Namespace, resourceType, sync.Spec.ObjectName, model.UpdateOperation, obj)
		beehiveContext.Send(commonconst.DefaultContextSendModuleName, *msg)
	}
}

func buildEdgeControllerMessage(nodeName, namespace, resourceType, resourceName, operationType string, obj interface{}) *model.Message {
	resource, err := messagelayer.BuildResource(nodeName, namespace, resourceType, resourceName)
	if err != nil {
		klog.Warningf("build message resource failed with error: %s", err)
		return nil
	}

	resourceVersion := GetObjectResourceVersion(obj)

	msg := model.NewMessage("").
		BuildRouter(modules.EdgeControllerModuleName, edgectrconst.GroupResource, resource, operationType).
		FillBody(obj).
		SetResourceVersion(resourceVersion)

	return msg
}

func GetObjectResourceVersion(obj interface{}) string {
	if obj == nil {
		klog.Error("object is nil")
		return ""
	}

	accessor, err := meta.Accessor(obj)
	if err != nil {
		klog.Errorf("Failed to get resourceVersion of the object: %v", obj)
		return ""
	}

	return accessor.GetResourceVersion()
}

func CompareResourceVersion(rva, rvb string) int {
	a, err := strconv.ParseUint(rva, 10, 64)
	if err != nil {
		// coder error
		panic(err)
	}
	b, err := strconv.ParseUint(rvb, 10, 64)
	if err != nil {
		// coder error
		panic(err)
	}

	if a > b {
		return 1
	}
	if a == b {
		return 0
	}
	return -1
}

func NewMessageFifo() *MessageFifo {
	return &MessageFifo{
		fifo: make(chan model.Message, comm.MessageFiFoSizeMax),
	}
}

func (f *MessageFifo) Put(msg *model.Message) {
	select {
	case f.fifo <- *msg:
	default:
		// discard the old message
		<-f.fifo
		// push into fifo
		f.fifo <- *msg
		klog.Warning("too many message received, fifo overflow")
	}
}

func (f *MessageFifo) Get(msg *model.Message) error {
	var ok bool
	*msg, ok = <-f.fifo
	if !ok {
		return fmt.Errorf("the fifo is broken")
	}
	return nil
}

func (f *MessageFifo) Close() {
	f.closeOnce.Do(func() {
		close(f.fifo)
	})
}

func NewWrapper(_ string, conn interface{}, buffSize int) Conn {
	readerType := reader.ReaderTypeRaw
	writerType := writer.WriterTypeRaw

	return &ConnWrapper{
		conn:   conn,
		reader: reader.NewReader(readerType, conn, buffSize),
		writer: writer.NewWriter(writerType, conn),
	}
}

func (w *ConnWrapper) Read() ([]byte, error) {
	return w.reader.Read()
}

func (w *ConnWrapper) Write(message []byte) error {
	return w.writer.Write(message)
}

func (w *ConnWrapper) ReadJSON(obj interface{}) error {
	return w.reader.ReadJSON(obj)
}

func (w *ConnWrapper) WriteJSON(obj interface{}) error {
	return w.writer.WriteJSON(obj)
}

func (w *ConnWrapper) SetReadDeadline(t time.Time) error {
	// TODO: put int Deadline
	var err error
	switch w.conn.(type) {
	case net.Conn:
		conn := w.conn.(net.Conn)
		err = conn.SetReadDeadline(t)
	default:
		klog.Warningf("unsupported conn type: %T", w.conn)
	}
	return err
}

func (w *ConnWrapper) Close() error {
	// TODO: put into Closer
	var err error
	switch w.conn.(type) {
	case net.Conn:
		conn := w.conn.(net.Conn)
		err = conn.Close()
	default:
		klog.Warningf("unsupported conn type: %T", w.conn)
	}
	return err
}

func Convert(valueType string, value string) (result interface{}, err error) {
	switch valueType {
	case "int":
		return strconv.ParseInt(value, 10, 64)
	case "float":
		return strconv.ParseFloat(value, 32)
	case "double":
		return strconv.ParseFloat(value, 64)
	case "boolean":
		return strconv.ParseBool(value)
	case "string":
		return value, nil
	default:
		return nil, errors.New("Convert failed")
	}
}

func DecodeAnyValue(value *anypb.Any) (interface{}, error) {
	typeURL := value.GetTypeUrl()

	messageTypeName := getMessageTypeName(typeURL)
	if messageTypeName == "" {
		return nil, fmt.Errorf("cant get message type：%s", typeURL)
	}
	if strings.Contains(messageTypeName, "google.protobuf.") {
		switch messageTypeName {
		case "google.protobuf.Int32Value":
			return decodeWrapperValue(value, &wrapperspb.Int32Value{})
		case "google.protobuf.StringValue":
			return decodeWrapperValue(value, &wrapperspb.StringValue{})
		case "google.protobuf.FloatValue":
			return decodeWrapperValue(value, &wrapperspb.FloatValue{})
		case "google.protobuf.BoolValue":
			return decodeWrapperValue(value, &wrapperspb.BoolValue{})
		case "google.protobuf.Int64Value":
			return decodeWrapperValue(value, &wrapperspb.Int64Value{})
		default:
			return nil, fmt.Errorf("unknown type : %s", messageTypeName)
		}
	}
	messageType := proto.MessageType(messageTypeName)
	if messageType == nil {
		return nil, fmt.Errorf("cant get message type：%s", messageTypeName)
	}

	if !reflect.TypeOf((*proto.Message)(nil)).Elem().AssignableTo(messageType) {
		return nil, fmt.Errorf("assiganbleto proto.Message error：%s", messageTypeName)
	}
	message := reflect.New(messageType.Elem()).Interface().(proto.Message)
	if err := proto.Unmarshal(value.Value, message); err != nil {
		return nil, fmt.Errorf("unmarshal value error：%v", err)
	}
	return message, nil
}

func decodeWrapperValue(value *anypb.Any, wrapper proto.Message) (interface{}, error) {
	if err := proto.Unmarshal(value.Value, wrapper); err != nil {
		return nil, fmt.Errorf("decode wrapperValue,proto unmarshal error：%v", err)
	}
	wrapperValue := reflect.ValueOf(wrapper).Elem()
	valueField := wrapperValue.FieldByName("Value")
	if !valueField.IsValid() {
		return nil, fmt.Errorf("cant get wrapperValue")
	}
	return valueField.Interface(), nil
}

func getMessageTypeName(typeURL string) string {
	index := len(typeURL) - 1
	for index >= 0 && typeURL[index] != '/' {
		index--
	}
	if index >= 0 && index < len(typeURL)-1 {
		return typeURL[index+1:]
	}
	return ""
}

