func registerValidateWebhook(client admissionregistrationv1client.ValidatingWebhookConfigurationInterface,
	webhooks []admissionregistrationv1.ValidatingWebhookConfiguration) error {
	for _, hook := range webhooks {
		existing, err := client.Get(context.Background(), hook.Name, metav1.GetOptions{})
		if err != nil && !apierrors.IsNotFound(err) {
			return err
		}
		if err == nil && existing != nil {
			existing.Webhooks = hook.Webhooks
			klog.Infof("Updating ValidatingWebhookConfiguration: %v", hook.Name)
			if _, err := client.Update(context.Background(), existing, metav1.UpdateOptions{}); err != nil {
				return err
			}
		} else {
			klog.Infof("Creating ValidatingWebhookConfiguration: %v", hook.Name)
			if _, err := client.Create(context.Background(), &hook, metav1.CreateOptions{}); err != nil {
				return err
			}
		}
	}
	return nil
}

func registerMutatingWebhook(client admissionregistrationv1client.MutatingWebhookConfigurationInterface,
	webhooks []admissionregistrationv1.MutatingWebhookConfiguration) error {
	for _, hook := range webhooks {
		existing, err := client.Get(context.Background(), hook.Name, metav1.GetOptions{})
		if err != nil && !apierrors.IsNotFound(err) {
			return err
		}
		if err == nil && existing != nil {
			existing.Webhooks = hook.Webhooks
			klog.Infof("Updating MutatingWebhookConfiguration: %v", hook.Name)
			if _, err := client.Update(context.Background(), existing, metav1.UpdateOptions{}); err != nil {
				return err
			}
		} else {
			klog.Infof("Creating MutatingWebhookConfiguration: %v", hook.Name)
			if _, err := client.Create(context.Background(), &hook, metav1.CreateOptions{}); err != nil {
				return err
			}
		}
	}
	return nil
}

func serve(w http.ResponseWriter, r *http.Request, hook hookFunc) {
	var body []byte
	if r.Body != nil {
		r.Body = http.MaxBytesReader(w, r.Body, constants.MaxRespBodyLength)
		if data, err := io.ReadAll(r.Body); err == nil {
			body = data
		}
	}

	// verify the content type is accurate
	contentType := r.Header.Get("Content-Type")
	if contentType != "application/json" {
		klog.Errorf("contentType=%s, expect application/json", contentType)
		return
	}

	// The AdmissionReview that was sent to the webhook
	requestedAdmissionReview := admissionv1.AdmissionReview{}

	// The AdmissionReview that will be returned
	responseAdmissionReview := admissionv1.AdmissionReview{}
	responseAdmissionReview.SetGroupVersionKind(admissionv1.SchemeGroupVersion.WithKind("AdmissionReview"))

	deserializer := codecs.UniversalDeserializer()
	if _, _, err := deserializer.Decode(body, nil, &requestedAdmissionReview); err != nil {
		klog.Errorf("decode failed with error: %v", err)
		responseAdmissionReview.Response = toAdmissionResponse(err)
	} else {
		responseAdmissionReview.Response = hook(requestedAdmissionReview)
		// Return the same UID
		responseAdmissionReview.Response.UID = requestedAdmissionReview.Request.UID
	}

	klog.V(4).Infof("sending response: %+v", responseAdmissionReview.Response)

	respBytes, err := json.Marshal(responseAdmissionReview)
	if err != nil {
		klog.Errorf("cannot marshal to a valid response %v", err)
		return
	}
	if _, err := w.Write(respBytes); err != nil {
		klog.Errorf("cannot write response %v", err)
		return
	}
}

func toAdmissionResponse(err error) *admissionv1.AdmissionResponse {
	return &admissionv1.AdmissionResponse{
		Result: &metav1.Status{
			Message: err.Error(),
		},
	}
}

func mutateOfflineMigration(review admissionv1.AdmissionReview) *admissionv1.AdmissionResponse {
	reviewResponse := admissionv1.AdmissionResponse{
		Allowed: true,
	}

	var pod corev1.Pod
	if err := json.Unmarshal(review.Request.Object.Raw, &pod); err != nil {
		klog.Errorf("Could not unmarshal raw object: %v", err)
		return toAdmissionResponse(err)
	}

	payload := generatePatch(pod.Spec.Tolerations)
	if len(payload) == 0 {
		return &reviewResponse
	}

	patch, err := json.Marshal(payload)
	if err != nil {
		return toAdmissionResponse(err)
	}

	reviewResponse.Patch = patch
	pt := admissionv1.PatchTypeJSONPatch
	reviewResponse.PatchType = &pt
	return &reviewResponse
}

func generatePatch(tolerations []corev1.Toleration) []patchMapValue {
	currentTolerations := make([]interface{}, 0, len(tolerations)+1)
	for _, v := range tolerations {
		if v.Key == corev1.TaintNodeUnreachable {
			continue
		}
		currentTolerations = append(currentTolerations, v)
	}
	currentTolerations = append(currentTolerations, corev1.Toleration{
		Key:      corev1.TaintNodeUnreachable,
		Operator: corev1.TolerationOpExists,
	})
	patch := []patchMapValue{
		{
			Op:    "replace",
			Path:  "/spec/tolerations",
			Value: currentTolerations,
		},
	}
	return patch
}

func serveOfflineMigration(w http.ResponseWriter, r *http.Request) {
	serve(w, r, mutateOfflineMigration)
}

func init() {
	addToScheme(scheme)
}

func addToScheme(scheme *runtime.Scheme) {
	utilruntime.Must(corev1.AddToScheme(scheme))
	utilruntime.Must(admissionv1.AddToScheme(scheme))
	utilruntime.Must(admissionregistrationv1.AddToScheme(scheme))
	utilruntime.Must(v1beta1.AddDeviceCrds(scheme))
}

func Run(opt *options.AdmissionOptions) error {
	klog.V(4).Infof("AdmissionOptions: %+v", *opt)
	restConfig, err := clientcmd.BuildConfigFromFlags(opt.Master, opt.Kubeconfig)
	if err != nil {
		return err
	}

	cli, err := kubernetes.NewForConfig(restConfig)
	if err != nil {
		return fmt.Errorf("create kube client failed with error: %v", err)
	}
	vcli, err := versioned.NewForConfig(restConfig)
	if err != nil {
		return fmt.Errorf("create versioned client failed with error: %v", err)
	}

	controller.Client = cli
	controller.CrdClient = vcli

	caBundle, err := os.ReadFile(opt.CaCertFile)
	if err != nil {
		return fmt.Errorf("unable to read cacert file: %v", err)
	}

	//TODO: read somewhere to get what's kind of webhook is enabled, register those webhook only.
	if err = controller.registerWebhooks(opt, caBundle); err != nil {
		return fmt.Errorf("failed to register the webhook with error: %v", err)
	}

	http.HandleFunc("/devices", serveDevice)
	http.HandleFunc("/devicemodels", serveDeviceModel)
	http.HandleFunc("/rules", serveRule)
	http.HandleFunc("/ruleendpoints", serveRuleEndpoint)
	http.HandleFunc("/offlinemigration", serveOfflineMigration)
	http.HandleFunc("/nodeupgradejobs", serveNodeUpgradeJob)
	http.HandleFunc("/mutating/nodeupgradejobs", serveMutatingNodeUpgradeJob)

	tlsConfig, err := configTLS(opt, restConfig)
	if err != nil {
		return err
	}
	server := &http.Server{
		Addr:      fmt.Sprintf(":%v", opt.Port),
		TLSConfig: tlsConfig,
	}

	if err := server.ListenAndServeTLS("", ""); err != nil {
		return fmt.Errorf("start server failed with error: %v", err)
	}
	return nil
}

func configTLS(opt *options.AdmissionOptions, restConfig *restclient.Config) (*tls.Config, error) {
	if len(opt.CertFile) != 0 && len(opt.KeyFile) != 0 {
		sCert, err := tls.LoadX509KeyPair(opt.CertFile, opt.KeyFile)
		if err != nil {
			return nil, err
		}

		return &tls.Config{
			Certificates: []tls.Certificate{sCert},
		}, nil
	}

	if len(restConfig.CertData) != 0 && len(restConfig.KeyData) != 0 {
		sCert, err := tls.X509KeyPair(restConfig.CertData, restConfig.KeyData)
		if err != nil {
			return nil, err
		}

		return &tls.Config{
			Certificates: []tls.Certificate{sCert},
		}, nil
	}
	return nil, errors.New("tls: failed to find any tls config data")
}

