func (dtc *DTContext) GetDevice(deviceID string) (*dttype.Device, bool) {
	d, ok := dtc.DeviceList.Load(deviceID)
	if ok {
		if device, isDevice := d.(*dttype.Device); isDevice {
			return device, true
		}
		return nil, false
	}
	return nil, false
}

func (dtc *DTContext) Send(identity string, action string, module string, msg *model.Message) error {
	dtMsg := &dttype.DTMessage{
		Action:   action,
		Identity: identity,
		Type:     module,
		Msg:      msg}
	return dtc.CommTo(module, dtMsg)
}

func (dtc *DTContext) BuildModelMessage(group string, parentID string, resource string, operation string, content interface{}) *model.Message {
	msg := model.NewMessage(parentID)
	msg.BuildRouter(modules.TwinGroup, group, resource, operation)
	msg.Content = content
	return msg
}

func TestCommTo(t *testing.T) {
	commChan := make(map[string]chan interface{})
	testInterface := make(chan interface{}, 1)
	commChan["ModuleB"] = testInterface
	dtContext := &DTContext{
		CommChan: commChan,
	}
	var returnValue interface{}
	tests := []struct {
		name       string
		modulename string
		content    interface{}
		wantErr    error
	}{
		{
			//Failure Case
			name:       "ModuleNotPresent",
			modulename: "ModuleA",
			content:    nil,
			wantErr:    errors.New("Not found chan to communicate"),
		},
		{
			//Success Case
			name:       "ModulePresent",
			modulename: "ModuleB",
			content:    dttype.MembershipUpdate{AddDevices: []dttype.Device{{ID: "DeviceA", Name: "Router", State: "unknown"}}},
			wantErr:    nil,
		},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			err := dtContext.CommTo(test.modulename, test.content)
			if err == nil {
				returnValue = <-testInterface
			} else {
				returnValue = nil
			}
			if !reflect.DeepEqual(err, test.wantErr) {
				t.Errorf("Error in CommTo %v, Want %v", err, test.wantErr)
				return
			}
			if !reflect.DeepEqual(returnValue, test.content) {
				t.Errorf("Got %v on channel, Want %v on Channel", returnValue, test.content)
				return
			}
		})
	}
}

