func TestNeedFilter(t *testing.T) {
	assert := assert.New(t)
	filter := newEndpointsliceFilter()

	// Test case 1: UnstructuredList containing an EndpointSlice object
	endpointSliceObj := &unstructured.Unstructured{}
	endpointSliceObj.SetGroupVersionKind(schema.GroupVersionKind{Kind: resourceEpSliceName})
	unstructuredList := &unstructured.UnstructuredList{
		Items: []unstructured.Unstructured{*endpointSliceObj},
	}

	result := filter.NeedFilter(unstructuredList)
	assert.True(result)

	// Test case 2: UnstructuredList containing a non EndpointSlice object
	nonEndpointSliceObj := &unstructured.Unstructured{}
	nonEndpointSliceObj.SetGroupVersionKind(schema.GroupVersionKind{Kind: "Pod"})
	unstructuredList.Items = []unstructured.Unstructured{*nonEndpointSliceObj}

	result = filter.NeedFilter(unstructuredList)
	assert.False(result)

	// Test case 3: Unstructured object of type EndpointSlice
	result = filter.NeedFilter(endpointSliceObj)
	assert.True(result)

	// Test case 4: Unstructured object of type Endpoints
	endpointsObj := &unstructured.Unstructured{}
	endpointsObj.SetGroupVersionKind(schema.GroupVersionKind{Kind: resourceEpName})

	result = filter.NeedFilter(endpointsObj)
	assert.True(result)

	// Test case 5: Unstructured object of another type
	podObj := &unstructured.Unstructured{}
	podObj.SetGroupVersionKind(schema.GroupVersionKind{Kind: "Pod"})

	result = filter.NeedFilter(podObj)
	assert.False(result)
}

func NewNegotiatedSerializer() runtime.NegotiatedSerializer {
	return WithoutConversionCodecFactory{
		typer:   unstructuredscheme.NewUnstructuredObjectTyper(),
		creator: unstructuredscheme.NewUnstructuredCreator(),
	}
}

func (f WithoutConversionCodecFactory) SupportedMediaTypes() []runtime.SerializerInfo {
	return []runtime.SerializerInfo{
		{
			MediaType:        "application/json",
			MediaTypeType:    "application",
			MediaTypeSubType: "json",
			EncodesAsText:    true,
			Serializer:       json.NewSerializerWithOptions(json.DefaultMetaFactory, f.creator, f.typer, json.SerializerOptions{Pretty: false}),
			PrettySerializer: json.NewSerializerWithOptions(json.DefaultMetaFactory, f.creator, f.typer, json.SerializerOptions{Pretty: true}),
			StrictSerializer: json.NewSerializerWithOptions(json.DefaultMetaFactory, f.creator, f.typer, json.SerializerOptions{Strict: true}),
			StreamSerializer: &runtime.StreamSerializerInfo{
				EncodesAsText: true,
				Serializer:    json.NewSerializerWithOptions(json.DefaultMetaFactory, f.creator, f.typer, json.SerializerOptions{Pretty: false}),
				Framer:        json.Framer,
			},
		},
		{
			MediaType:        "application/yaml",
			MediaTypeType:    "application",
			MediaTypeSubType: "yaml",
			EncodesAsText:    true,
			Serializer:       json.NewSerializerWithOptions(json.DefaultMetaFactory, f.creator, f.typer, json.SerializerOptions{Yaml: true}),
		},
	}
}

func (f WithoutConversionCodecFactory) EncoderForVersion(serializer runtime.Encoder, gv runtime.GroupVersioner) runtime.Encoder {
	encoder := &SetVersionEncoder{
		Version: gv,
		encoder: serializer,
	}
	return encoder
}

func (f WithoutConversionCodecFactory) DecoderToVersion(serializer runtime.Decoder, _ runtime.GroupVersioner) runtime.Decoder {
	return serializer
}

func (s *SetVersionEncoder) Identifier() runtime.Identifier {
	return s.gvk.String()
}

func (s *SetVersionEncoder) Encode(obj runtime.Object, w io.Writer) error {
	if gv, ok := s.Version.(*WithKindGroupVersioner); ok {
		gvk, _ := gv.KindForGroupVersionKinds(nil)
		obj.GetObjectKind().SetGroupVersionKind(gvk)
	}
	return s.encoder.Encode(obj, w)
}

func (d *AdapterDecoder) Decode(data []byte, defaults *schema.GroupVersionKind, into runtime.Object) (runtime.Object, *schema.GroupVersionKind, error) {
	out, gvk, err := d.Decoder.Decode(data, defaults, into)
	if err != nil && gvk != nil {
		*defaults = *gvk
	}
	return out, gvk, err
}

func (s *WithKindGroupVersioner) KindForGroupVersionKinds(_ []schema.GroupVersionKind) (target schema.GroupVersionKind, ok bool) {
	return s.gvk, true
}

func (s *WithKindGroupVersioner) Identifier() string {
	return s.gvk.String()
}

func NewWithKindGroupVersioner(gvk schema.GroupVersionKind) *WithKindGroupVersioner {
	gv := &WithKindGroupVersioner{
		gvk: gvk,
	}
	return gv
}

