func (h x509CAHandler) GenPrivateKey() (PrivateKeyWrap, error) {
	pk, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, fmt.Errorf("failed to generate self signed CA private key, err: %v", err)
	}
	keyDER, err := x509.MarshalECPrivateKey(pk)
	if err != nil {
		return nil, fmt.Errorf("failed to convert an EC private key to SEC 1, ASN.1 DER form, err: %v", err)
	}
	return &x509PrivateKeyWrap{der: keyDER}, nil
}

func (h x509CAHandler) NewSelfSigned(key PrivateKeyWrap) (*pem.Block, error) {
	const year100 = time.Hour * 24 * 364 * 100

	tmpl := x509.Certificate{
		SerialNumber: big.NewInt(1024),
		Subject: pkix.Name{
			CommonName: constants.ProjectName,
		},
		NotBefore:             time.Now().UTC(),
		NotAfter:              time.Now().Add(year100),
		KeyUsage:              x509.KeyUsageKeyEncipherment | x509.KeyUsageDigitalSignature | x509.KeyUsageCertSign,
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
		BasicConstraintsValid: true,
		IsCA:                  true,
	}
	pk, err := key.Signer()
	if err != nil {
		return nil, fmt.Errorf("failed parse CA key der to private key, err: %v", err)
	}
	caDER, err := x509.CreateCertificate(rand.Reader, &tmpl, &tmpl, pk.Public(), pk)
	if err != nil {
		return nil, fmt.Errorf("failed to generate self signed CA cert, err: %v", err)
	}
	return &pem.Block{Type: certutil.CertificateBlockType, Bytes: caDER}, nil
}

func TestSignX509Certs(t *testing.T) {
	cah := new(x509CAHandler)
	certh := new(x509CertsHandler)

	capkw, err := cah.GenPrivateKey()
	if err != nil {
		t.Fatal(err)
	}
	cablock, err := cah.NewSelfSigned(capkw)
	if err != nil {
		t.Fatal(err)
	}

	certpkw, err := certh.GenPrivateKey()
	if err != nil {
		t.Fatal(err)
	}
	csrblock, err := certh.CreateCSR(pkix.Name{
		Country:      []string{"CN"},
		Organization: []string{"system:nodes"},
		Locality:     []string{"Hangzhou"},
		Province:     []string{"Zhejiang"},
		CommonName:   "test-node",
	}, certpkw, nil)

	opts := SignCertsOptionsWithCSR(csrblock.Bytes, cablock.Bytes, capkw.DER(),
		[]x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}, 24*time.Hour)
	certblock, err := certh.SignCerts(opts)
	if err != nil {
		t.Fatal(err)
	}
	if len(certblock.Bytes) == 0 {
		t.Fatal("cert bytes cannot be empty")
	}
}

func (h x509CertsHandler) GenPrivateKey() (PrivateKeyWrap, error) {
	pk, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, fmt.Errorf("failed to generate certificate private key, err: %v", err)
	}
	keyDER, err := x509.MarshalECPrivateKey(pk)
	if err != nil {
		return nil, fmt.Errorf("failed to convert an EC private key to SEC 1, ASN.1 DER form, err: %v", err)
	}
	return &x509PrivateKeyWrap{der: keyDER}, nil
}

func (h x509CertsHandler) CreateCSR(sub pkix.Name, pkw PrivateKeyWrap, alt *certutil.AltNames) (*pem.Block, error) {
	tpl := x509.CertificateRequest{
		Subject: sub,
	}
	if alt != nil {
		tpl.DNSNames = alt.DNSNames
		tpl.IPAddresses = alt.IPs
	}
	pk, err := pkw.Signer()
	if err != nil {
		return nil, fmt.Errorf("faild to parse the private key der to Signer, err: %v", err)
	}
	csrDER, err := x509.CreateCertificateRequest(rand.Reader, &tpl, pk)
	if err != nil {
		return nil, fmt.Errorf("faild to create x509 certificate request, err %v", err)
	}
	return &pem.Block{Type: certutil.CertificateRequestBlockType, Bytes: csrDER}, nil
}

func (h x509CertsHandler) SignCerts(opts SignCertsOptions) (*pem.Block, error) {
	pubkey := opts.publicKey
	if opts.csrDER != nil {
		csr, err := x509.ParseCertificateRequest(opts.csrDER)
		if err != nil {
			return nil, fmt.Errorf("failed to parse csr, err: %v", err)
		}
		opts.cfg.CommonName = csr.Subject.CommonName
		opts.cfg.Organization = csr.Subject.Organization
		opts.cfg.AltNames.DNSNames = csr.DNSNames
		opts.cfg.AltNames.IPs = csr.IPAddresses
		pubkey = csr.PublicKey
	}
	if len(opts.cfg.CommonName) == 0 {
		return nil, errors.New("must specify a CommonName")
	}
	if len(opts.cfg.Usages) == 0 {
		return nil, errors.New("must specify at least one ExtKeyUsage")
	}

	serial, err := rand.Int(rand.Reader, new(big.Int).SetInt64(math.MaxInt64))
	if err != nil {
		return nil, fmt.Errorf("failed to generate serial number, err: %v", err)
	}

	caKey, err := x509PrivateKeyWrap{der: opts.caKeyDER}.Signer()
	if err != nil {
		return nil, fmt.Errorf("failed to parse CA private key, err: %v", err)
	}

	ca, err := x509.ParseCertificate(opts.caDER)
	if err != nil {
		return nil, fmt.Errorf("failed to parse CA, err: %v", err)
	}

	certTmpl := x509.Certificate{
		Subject: pkix.Name{
			CommonName:   opts.cfg.CommonName,
			Organization: opts.cfg.Organization,
		},
		DNSNames:     opts.cfg.AltNames.DNSNames,
		IPAddresses:  opts.cfg.AltNames.IPs,
		SerialNumber: serial,
		NotBefore:    time.Now().UTC(),
		NotAfter:     time.Now().Add(opts.expiration),
		KeyUsage:     x509.KeyUsageKeyEncipherment | x509.KeyUsageDigitalSignature,
		ExtKeyUsage:  opts.cfg.Usages,
	}
	certDER, err := x509.CreateCertificate(rand.Reader, &certTmpl, ca, pubkey, caKey)
	if err != nil {
		return nil, fmt.Errorf("failed to create certificate, err: %v", err)
	}

	return &pem.Block{Type: certutil.CertificateBlockType, Bytes: certDER}, nil
}

func (k x509PrivateKeyWrap) Signer() (crypto.Signer, error) {
	return x509.ParseECPrivateKey(k.der)
}

func (k x509PrivateKeyWrap) DER() []byte {
	return k.der
}

func (k x509PrivateKeyWrap) PEM() []byte {
	privateKeyPemBlock := &pem.Block{
		Type:  keyutil.ECPrivateKeyBlockType,
		Bytes: k.der,
	}
	return pem.EncodeToMemory(privateKeyPemBlock)
}

func GetCAHandler(t CAHandlerType) CAHandler {
	switch t {
	case CAHandlerTypeX509:
		return &x509CAHandler{}
	}
	return nil
}

func GetHandler(t HanndlerType) Handler {
	switch t {
	case HandlerTypeX509:
		return &x509CertsHandler{}
	}
	return nil
}

func ReadPEMFile(file string) (*pem.Block, error) {
	bff, err := os.ReadFile(file)
	if err != nil {
		return nil, err
	}
	p, _ := pem.Decode(bff)
	return p, nil
}

func WriteDERToPEMFile(file, t string, der []byte) (*pem.Block, error) {
	dir := filepath.Dir(file)
	if err := os.MkdirAll(dir, 0722); err != nil {
		return nil, fmt.Errorf("failed to create dir %s, err: %v", dir, err)
	}
	block := &pem.Block{Type: t, Bytes: der}
	bff := pem.EncodeToMemory(block)
	if err := os.WriteFile(file, bff, 0622); err != nil {
		return nil, fmt.Errorf("failed to write file %s, err: %v", file, err)
	}
	return block, nil
}

func DataHandler(ctx context.Context, twin *common.Twin, client *driver.CustomizedClient, visitorConfig *driver.VisitorConfig, dataModel *common.DataModel) {
	dbConfig, err := NewDataBaseClient(twin.Property.PushMethod.DBMethod.DBConfig.MySQLClientConfig)
	if err != nil {
		klog.Errorf("new database client error: %v", err)
		return
	}
	err = dbConfig.InitDbClient()
	if err != nil {
		klog.Errorf("init redis database client err: %v", err)
		return
	}
	reportCycle := time.Duration(twin.Property.ReportCycle)
	if reportCycle == 0 {
		reportCycle = common.DefaultReportCycle
	}
	ticker := time.NewTicker(reportCycle)
	go func() {
		for {
			select {
			case <-ticker.C:
				deviceData, err := client.GetDeviceData(visitorConfig)
				if err != nil {
					klog.Errorf("publish error: %v", err)
					continue
				}
				sData, err := common.ConvertToString(deviceData)
				if err != nil {
					klog.Errorf("Failed to convert publish method data : %v", err)
					continue
				}
				dataModel.SetValue(sData)
				dataModel.SetTimeStamp()

				err = dbConfig.AddData(dataModel)
				if err != nil {
					klog.Errorf("mysql database add data error: %v", err)
					return
				}
			case <-ctx.Done():
				dbConfig.CloseSession()
				return
			}
		}
	}()
}

func NewDataBaseClient(config json.RawMessage) (*DataBaseConfig, error) {
	configdata := new(MySQLClientConfig)
	err := json.Unmarshal(config, configdata)
	if err != nil {
		return nil, err
	}
	return &DataBaseConfig{
		MySQLClientConfig: configdata,
	}, nil
}

func (d *DataBaseConfig) InitDbClient() error {
	password := os.Getenv("PASSWORD")
	usrName := d.MySQLClientConfig.UserName
	addr := d.MySQLClientConfig.Addr
	dataBase := d.MySQLClientConfig.Database
	dataSourceName := fmt.Sprintf("%s:%s@tcp(%s)/%s", usrName, password, addr, dataBase)
	var err error
	DB, err = sql.Open("mysql", dataSourceName)
	if err != nil {
		return fmt.Errorf("connection to %s of mysql faild with err:%v", dataBase, err)
	}

	return nil
}

func (d *DataBaseConfig) CloseSession() {
	err := DB.Close()
	if err != nil {
		klog.Errorf("close mysql failed with err:%v", err)
	}
}

func (d *DataBaseConfig) AddData(data *common.DataModel) error {
	tableName := data.Namespace + "/" + data.DeviceName + "/" + data.PropertyName
	datatime := time.Unix(data.TimeStamp/1e3, 0).Format("2006-01-02 15:04:05")

	createTable := fmt.Sprintf("CREATE TABLE IF NOT EXISTS `%s` (id INT AUTO_INCREMENT PRIMARY KEY, ts  DATETIME NOT NULL,field TEXT)", tableName)
	_, err := DB.Exec(createTable)
	if err != nil {
		return fmt.Errorf("create tabe into mysql failed with err:%v", err)
	}

	stmt, err := DB.Prepare(fmt.Sprintf("INSERT INTO `%s` (ts,field) VALUES (?,?)", tableName))
	if err != nil {
		return fmt.Errorf("prepare parament failed with err:%v", err)
	}
	defer func(stmt *sql.Stmt) {
		err := stmt.Close()
		if err != nil {
			klog.Errorf("close mysql's statement failed with err:%v", err)
		}
	}(stmt)
	_, err = stmt.Exec(datatime, data.Value)
	if err != nil {
		return fmt.Errorf("insert data into msyql failed with err:%v", err)
	}

	return nil
}

