func (f FakeResponseWriter) Header() http.Header {
	return make(map[string][]string)
}

func (f *FakeResponseWriter) Write(payload []byte) (int, error) {
	f.payload = payload
	return -1, nil
}

func (f *FakeResponseWriter) WriteHeader(code int) {
	f.code = code
}

func Error(w http.ResponseWriter, code int, err error) {
	ErrorMessage(w, code, err.Error())
}

func ErrorMessage(w http.ResponseWriter, code int, msg string) {
	if code == 0 {
		code = http.StatusInternalServerError
	}
	w.WriteHeader(code)
	if _, err := w.Write([]byte(msg)); err != nil {
		klog.Errorf("failed to write a error messge to the response, err: %v", err)
	}
}

func OK(w http.ResponseWriter, body []byte) {
	w.WriteHeader(http.StatusOK)
	if _, err := w.Write(body); err != nil {
		klog.Errorf("failed to write a payload to the response, err: %v", err)
	}
}

func TestErrorMessage(t *testing.T) {
	cases := []struct {
		name    string
		code    int
		message string
		err     error
	}{
		{
			name:    "default error code",
			message: "test message",
		},
		{
			name:    "specified error code",
			code:    http.StatusBadRequest,
			message: "bad request",
		},
		{
			name: "specified error",
			err:  errors.New("new error"),
		},
	}

	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			var wantCode int
			if c.code == 0 {
				wantCode = http.StatusInternalServerError
			} else {
				wantCode = c.code
			}
			w := new(FakeResponseWriter)
			var wantMsg string
			if c.err != nil {
				wantMsg = c.err.Error()
				Error(w, c.code, c.err)
			} else {
				wantMsg = c.message
				ErrorMessage(w, c.code, c.message)
			}
			if w.code != wantCode {
				t.Fatalf("want status code is %d, actual is %d", wantCode, w.code)
			}
			if msg := string(w.payload); msg != wantMsg {
				t.Fatalf("want error message is %s, actual is %s", wantMsg, msg)
			}
		})
	}
}

func TestOK(t *testing.T) {
	payload := []byte("test data")
	w := new(FakeResponseWriter)
	OK(w, payload)
	if w.code != http.StatusOK {
		t.Fatalf("want status code is %d, actual is %d", http.StatusOK, w.code)
	}
	if !reflect.DeepEqual(w.payload, payload) {
		t.Fatalf("want error message is %s, actual is %s", string(payload), string(w.payload))
	}
}

func InitDBConfig(driverName, dbName, dataSource string) {
	once.Do(func() {
		if err := orm.RegisterDriver(driverName, orm.DRSqlite); err != nil {
			klog.Exitf("Failed to register driver: %v", err)
		}
		if err := orm.RegisterDataBase(
			dbName,
			driverName,
			dataSource); err != nil {
			klog.Exitf("Failed to register db: %v", err)
		}
		// sync database schema
		if err := orm.RunSyncdb(dbName, false, true); err != nil {
			klog.Errorf("run sync db error %v", err)
		}
		defer func() {
			if err := recover(); err != nil {
				klog.Errorf("Using db access error as %v", err)
			}
		}()
		// create orm
		DBAccess = orm.NewOrmUsingDB(dbName)
		klog.Infof("!!!!!!!!!!in db.go, DBAccess = %v", DBAccess)
	})
}

