func NewRemoteBroker() *RemoteBroker {
	return &RemoteBroker{
		keeper: synckeeper.NewKeeper(),
	}
}

func (broker *RemoteBroker) Connect(opts ConnectOptions, connect ConnectFunc) wrapper.Conn {
	conn, err := connect(opts)
	if err != nil {
		klog.Errorf("failed to connect, address: %s; error:%+v", opts.Address, err)
		return nil
	}
	return wrapper.NewWrapper(opts.MessageType, conn, opts.BufferSize)
}

func (broker *RemoteBroker) Send(conn wrapper.Conn, message model.Message) error {
	//log.LOGGER.Infof("connection: %+v message: %+v", conn, message)
	err := conn.WriteJSON(&message)
	if err != nil {
		klog.Errorf("failed to write with error %+v", err)
		return fmt.Errorf("failed to write, error: %+v", err)
	}
	return nil
}

func (broker *RemoteBroker) Receive(conn wrapper.Conn) (model.Message, error) {
	var message model.Message
	for {
		err := conn.SetReadDeadline(time.Time{})
		err = conn.ReadJSON(&message)
		if err != nil {
			klog.Errorf("failed to read, error:%+v", err)
			return model.Message{}, fmt.Errorf("failed to read, error: %+v", err)
		}

		isResponse := broker.keeper.IsSyncResponse(message.GetParentID())
		if !isResponse {
			return message, nil
		}

		err = broker.keeper.SendToKeepChannel(message)
	}
}

func (broker *RemoteBroker) SendSyncInternal(conn wrapper.Conn, message model.Message, timeout time.Duration) (model.Message, error) {
	if timeout <= 0 {
		timeout = syncMessageTimeoutDefault
	}

	// make sure to set sync flag
	message.Header.Sync = true

	err := conn.WriteJSON(&message)
	if err != nil {
		klog.Errorf("failed to write with error %+v", err)
		return model.Message{}, fmt.Errorf("failed to write, error: %+v", err)
	}

	deadline := time.Now().Add(timeout)
	err = conn.SetReadDeadline(deadline)
	var response model.Message
	err = conn.ReadJSON(&response)
	if err != nil {
		klog.Errorf("failed to read with error %+v", err)
		return model.Message{}, fmt.Errorf("failed to read, error: %+v", err)
	}

	return response, nil
}

func (broker *RemoteBroker) SendSync(conn wrapper.Conn, message model.Message, timeout time.Duration) (model.Message, error) {
	if timeout <= 0 {
		timeout = syncMessageTimeoutDefault
	}

	deadline := time.Now().Add(timeout)

	// make sure to set sync flag
	message.Header.Sync = true

	err := conn.WriteJSON(&message)
	if err != nil {
		klog.Errorf("failed to write with error %+v", err)
		return model.Message{}, fmt.Errorf("failed to write, error: %+v", err)
	}

	tempChannel := broker.keeper.AddKeepChannel(message.GetID())
	sendTimer := time.NewTimer(time.Until(deadline))
	select {
	case response := <-tempChannel:
		sendTimer.Stop()
		broker.keeper.DeleteKeepChannel(response.GetParentID())
		return response, nil
	case <-sendTimer.C:
		klog.Warningf("timeout to receive response for message: %s", message.String())
		broker.keeper.DeleteKeepChannel(message.GetID())
		return model.Message{}, fmt.Errorf("timeout to receive response for message: %s", message.String())
	}
}

func serveSocket(socketType, address string, handle func(conn wrapper.Conn)) error {
	if strings.Contains(socketType, "unix") {
		os.Remove(address)
	}

	listener, err := net.Listen(socketType, address)
	defer func() {
		if listener != nil {
			err := listener.Close()
			if err != nil {
				klog.Errorf("listener close err %+v", err)
			}
		}
	}()
	if err != nil {
		klog.Errorf("failed to listen to unix domain socket with error %+v", err)
		return fmt.Errorf("failed to listen to unix domain socket, error: %+v ", err)
	}
	klog.Infof("Listening on addr: %s", listener.Addr().String())

	conn, err := listener.Accept()
	klog.Infof("Connected from %s", conn.LocalAddr().String())
	if err != nil {
		klog.Errorf("failed to accept with error %+v", err)
		return fmt.Errorf("failed to accept, error: %+v", err)
	}

	wrapper := wrapper.NewWrapper(socketType, conn, 10240)
	handle(wrapper)
	err = conn.Close()

	return err
}

func SocketConnect(opts ConnectOptions) (interface{}, error) {
	conn, err := net.Dial(opts.MessageType, opts.Address)
	if err != nil {
		klog.Errorf("failed to dail addrs %s, error:%+v", opts.Address, err)
		return nil, err
	}
	return conn, nil
}

func TestMessageBroker_SendReceive(t *testing.T) {
	broker := NewRemoteBroker()
	stopChan := make(chan struct{})
	handle := func(conn wrapper.Conn) {
		message, err := broker.Receive(conn)
		if err != nil {
			t.Fatalf("failed to receive message, error: %+v", err)
		}
		fmt.Printf("recive message: %+v", message)
		if message.GetContent() != "hello" {
			t.Fatalf("bad message content")
		}
		stopChan <- struct{}{}
	}
	go func() {
		err := serveSocket("tcp", "127.0.0.1:1234", handle)
		if err != nil {
			t.Errorf("failed to serve socket")
			return
		}
	}()

	time.Sleep(1 * time.Second)
	brokerClient := NewRemoteBroker()

	opts := ConnectOptions{
		Address:     "127.0.0.1:1234",
		MessageType: "tcp",
		BufferSize:  10240,
	}
	conn := brokerClient.Connect(opts, SocketConnect)
	if conn == nil {
		t.Fatalf("failed to connect tcp")
	}
	_ = brokerClient.Send(conn, *model.NewMessage("").FillBody("hello"))

	select {
	case _, ok := <-time.After(syncMessageTimeoutDefault):
		if ok {
			t.Fatalf("time out ti recive message")
		}
	case _, ok := <-stopChan:
		if ok {
			klog.Warningf("channel stopped")
		}
	}
	conn.Close()
}

func TestMessageBroker_SendSync(t *testing.T) {
	brokerServer := NewRemoteBroker()
	stopTChan := make(chan struct{})
	handle := func(conn wrapper.Conn) {
		message, err := brokerServer.Receive(conn)
		if err != nil {
			t.Fatalf("failed to receive message, error: %+v", err)
		}
		if message.GetContent() != "hello" {
			t.Fatalf("bad message content")
		}
		resp := message.NewRespByMessage(&message, "hello_response")
		_ = brokerServer.Send(conn, *resp)
	}
	go func() {
		err := serveSocket("tcp", "127.0.0.1:1234", handle)
		if err != nil {
			t.Errorf("failed to serve socket")
			return
		}
	}()

	time.Sleep(1 * time.Second)
	brokerClient := NewRemoteBroker()
	opts := ConnectOptions{
		Address:     "127.0.0.1:1234",
		MessageType: "tcp",
		BufferSize:  10240,
	}
	conn := brokerClient.Connect(opts, SocketConnect)
	if conn == nil {
		t.Fatalf("failed to connect tcp")
	}

	go func() {
		_, _ = brokerClient.Receive(conn)
	}()

	go func() {
		resp, err := brokerClient.SendSync(conn, *model.NewMessage("").
			SetRoute("source", "dest").FillBody("hello"), 0)
		if err != nil {
			t.Errorf("failed to send sync message, error: %+v", err)
			return
		}
		if resp.GetContent() != "hello_response" {
			t.Errorf("unexpected receive message")
			return
		}
		stopTChan <- struct{}{}
	}()

	select {
	case _, ok := <-time.After(syncMessageTimeoutDefault):
		if ok {
			t.Fatalf("time out to send sync")
		}
	case _, ok := <-stopTChan:
		if ok {
			klog.Warningf("channel stopped")
		}
	}
	conn.Close()
}

