	printDetail(fmt.Sprintf("create tmp file: %s", tmpPath))
	err := os.Mkdir(tmpPath, os.ModePerm)
	if err != nil {
		return err
	}

	// arch info
	if err = ExecuteShell(common.CmdArchInfo, tmpPath); err != nil {
