func NewPackageWriter(obj interface{}) *PackageWriter {
	if conn, ok := obj.(net.Conn); ok {
		packer := packer.NewPacker()
		return &PackageWriter{
			conn:   conn,
			packer: packer,
		}
	}
	klog.Errorf("bad conn obj")
	return nil
}

func (w *PackageWriter) Write(message []byte) error {
	w.lock.Lock()
	defer w.lock.Unlock()

	w.packer.Message = message
	w.packer.Length = int32(len(message))
	err := w.packer.Write(w.conn)
	if err != nil {
		klog.Errorf("failed to packer with error %+v", err)
		return fmt.Errorf("failed to packer, error:%+v", err)
	}
	return nil
}

func (w *PackageWriter) WriteJSON(obj interface{}) error {
	w.lock.Lock()
	defer w.lock.Unlock()

	objBytes, err := json.Marshal(obj)
	if err != nil {
		klog.Errorf("failed to marshal obj, error:%+v", err)
		return err
	}
	w.packer.Message = objBytes
	w.packer.Length = int32(len(objBytes))
	err = w.packer.Write(w.conn)
	if err != nil {
		klog.Errorf("failed to packer, error:%+v", err)
		return fmt.Errorf("failed to packer, error:%+v", err)
	}
	return nil
}

func NewRawWriter(obj interface{}) *RawWriter {
	if conn, ok := obj.(net.Conn); ok {
		return &RawWriter{conn: conn}
	}
	klog.Errorf("bad conn ")
	return nil
}

func (w *RawWriter) Write(message []byte) error {
	w.lock.Lock()
	defer w.lock.Unlock()

	number, err := w.conn.Write(message)
	if err != nil || number != len(message) {
		klog.Errorf("failed to write, error:%+v", err)
		return fmt.Errorf("failed to write, error: %+v", err)
	}
	return nil
}

func (w *RawWriter) WriteJSON(obj interface{}) error {
	w.lock.Lock()
	defer w.lock.Unlock()
	return json.NewEncoder(w.conn).Encode(obj)
}

func NewWriter(writerType string, conn interface{}) Writer {
	switch writerType {
	case WriterTypeRaw:
		return NewRawWriter(conn)
	case WriterTypePackage:
		return NewPackageWriter(conn)
	}
	klog.Errorf("bad writer type:%s", writerType)
	return nil
}

func NewEdgeDeviceGet() *cobra.Command {
	deviceGetOptions := NewDeviceGetOpts()
	cmd := &cobra.Command{
		Use:   "device",
		Short: edgeDeviceGetShortDescription,
		Long:  edgeDeviceGetShortDescription,
		RunE: func(cmd *cobra.Command, args []string) error {
			cmdutil.CheckErr(deviceGetOptions.getDevices(args))
			return nil
		},
		Aliases: []string{"devices"},
	}

	AddGetDeviceFlags(cmd, deviceGetOptions)
	return cmd
}

func (o *DeviceGetOptions) getDevices(args []string) error {
	config, err := util.ParseEdgecoreConfig(common.EdgecoreConfigPath)
	if err != nil {
		return fmt.Errorf("get edge config failed with err:%v", err)
	}
	nodeName := config.Modules.Edged.HostnameOverride

	ctx := context.Background()
	var deviceListFilter *v1beta1.DeviceList
	if len(args) > 0 {
		deviceListFilter = &v1beta1.DeviceList{
			Items: make([]v1beta1.Device, 0, len(args)),
		}
		var deviceRequest *client.DeviceRequest

		for _, deviceName := range args {
			deviceRequest = &client.DeviceRequest{
				Namespace:  o.Namespace,
				DeviceName: deviceName,
			}

			device, err := deviceRequest.GetDevice(ctx)
			if err != nil {
				klog.Error(err.Error())
				continue
			}

			if device.Spec.NodeName == nodeName {
				deviceListFilter.Items = append(deviceListFilter.Items, *device)
			} else {
				klog.Errorf("can't query device: \"%s\" for node: \"%s\"", device.Name, device.Spec.NodeName)
			}
		}
	} else {
		deviceRequest := &client.DeviceRequest{
			Namespace:     o.Namespace,
			LabelSelector: o.LabelSelector,
			AllNamespaces: o.AllNamespaces,
		}

		deviceList, err := deviceRequest.GetDevices(ctx)
		if err != nil {
			return err
		}

		deviceListFilter = &v1beta1.DeviceList{
			Items: make([]v1beta1.Device, 0, len(deviceList.Items)),
		}

		for _, device := range deviceList.Items {
			if device.Spec.NodeName == nodeName {
				deviceListFilter.Items = append(deviceListFilter.Items, device)
			}
		}
	}

	if len(deviceListFilter.Items) == 0 {
		if len(args) > 0 {
			return nil
		}
		if o.AllNamespaces {
			klog.Info("No resources found in all namespaces.")
		} else {
			klog.Infof("No resources found in %s namespace.", o.Namespace)
		}
		return nil
	}

	if *o.PrintFlags.OutputFormat == "" || *o.PrintFlags.OutputFormat == "wide" {
		return o.PrintToTable(deviceListFilter, o.AllNamespaces, os.Stdout)
	}
	runtimeObjects := make([]runtime.Object, 0, len(deviceListFilter.Items))
	for _, device := range deviceListFilter.Items {
		runtimeObjects = append(runtimeObjects, &device)
	}
	return o.PrintToJSONYaml(runtimeObjects)
}

