func NewFactory() *Factory {
	s, err := storage.NewREST()
	utilruntime.Must(err)
	f := Factory{
		storage:           s,
		scope:             scope.NewRequestScope(),
		MinRequestTimeout: 1800 * time.Second,
		handlers:          make(map[string]http.Handler),
		lock:              sync.RWMutex{},
	}
	return &f
}

func (f *Factory) Get() http.Handler {
	if h, ok := f.getHandler("get"); ok {
		return h
	}
	f.lock.Lock()
	defer f.lock.Unlock()
	h := handlers.GetResource(f.storage, f.scope)
	f.handlers["get"] = h
	return h
}

func (f *Factory) List() http.Handler {
	if h, ok := f.getHandler("list"); ok {
		return h
	}
	f.lock.Lock()
	defer f.lock.Unlock()
	h := handlers.ListResource(f.storage, f.storage, f.scope, false, f.MinRequestTimeout)
	f.handlers["list"] = h
	return h
}

func (f *Factory) Create(req *request.RequestInfo) http.Handler {
	s := scope.NewRequestScope()
	s.Kind = schema.GroupVersionKind{
		Group:   req.APIGroup,
		Version: req.APIVersion,
		Kind:    util.UnsafeResourceToKind(req.Resource),
	}
	h := handlers.CreateResource(f.storage, s, fakers.NewAlwaysAdmit())
	return h
}

func (f *Factory) Delete() http.Handler {
	if h, ok := f.getHandler("delete"); ok {
		return h
	}
	f.lock.Lock()
	defer f.lock.Unlock()
	h := handlers.DeleteResource(f.storage, true, f.scope, fakers.NewAlwaysAdmit())
	f.handlers["delete"] = h
	return h
}

func (f *Factory) getHandler(key string) (http.Handler, bool) {
	f.lock.RLock()
	defer f.lock.RUnlock()
	h, ok := f.handlers[key]
	return h, ok
}

func (f *Factory) Update(req *request.RequestInfo) http.Handler {
	if req.Resource == "devices" {
		h := updateEdgeDevice()
		return h
	}
	s := scope.NewRequestScope()
	s.Kind = schema.GroupVersionKind{
		Group:   req.APIGroup,
		Version: req.APIVersion,
		Kind:    util.UnsafeResourceToKind(req.Resource),
	}
	h := handlers.UpdateResource(f.storage, s, fakers.NewAlwaysAdmit())
	return h
}

func updateEdgeDevice() http.Handler {
	h := http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		body, err := io.ReadAll(req.Body)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		var device *v1beta1.Device
		if err := json.Unmarshal(body, &device); err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		source := modules.MetaManagerModuleName
		target := modules.DeviceTwinModuleName
		resourece := device.Namespace + "/device/updated"

		operation := model.UpdateOperation

		device.SetGroupVersionKind(schema.GroupVersionKind{
			Group:   v1beta1.GroupName,
			Version: v1beta1.Version,
			Kind:    constants.KindTypeDevice,
		})
		modelMsg := model.NewMessage("").
			SetResourceVersion(device.ResourceVersion).
			FillBody(device)
		modelMsg.BuildRouter(source, target, resourece, operation)
		resp, err := beehiveContext.SendSync(source, *modelMsg, 1*time.Minute)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		respData, err := resp.GetContentData()
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, err = w.Write(respData)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
	})
	return h
}

func (f *Factory) PassThrough() http.Handler {
	h := http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		options := metav1.GetOptions{}
		result, err := f.storage.PassThrough(req.Context(), &options)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		w.Write(result)
	})
	return h
}

func (f *Factory) Patch(reqInfo *request.RequestInfo) http.Handler {
	scope := wrapScope{RequestScope: scope.NewRequestScope()}
	scope.Kind = schema.GroupVersionKind{
		Group:   reqInfo.APIGroup,
		Version: reqInfo.APIVersion,
		Kind:    util.UnsafeResourceToKind(reqInfo.Resource),
	}

	h := func(w http.ResponseWriter, req *http.Request) {
		// Do this first, otherwise name extraction can fail for unrecognized content types
		// TODO: handle this in negotiation
		contentType := req.Header.Get("Content-Type")
		// Remove "; charset=" if included in header.
		if idx := strings.Index(contentType, ";"); idx > 0 {
			contentType = contentType[:idx]
		}
		patchType := types.PatchType(contentType)

		// TODO: we either want to remove timeout or document it (if we
		// document, move timeout out of this function and declare it in
		// api_installer)
		timeout := parseTimeout(req.URL.Query().Get("timeout"))

		namespace, name, err := scope.Namer.Name(req)
		if err != nil {
			scope.err(err, w, req)
			return
		}

		ctx, cancel := context.WithTimeout(req.Context(), timeout)
		defer cancel()
		ctx = request.WithNamespace(ctx, namespace)

		patchBytes, err := limitedReadBody(req, scope.MaxRequestBodyBytes)
		if err != nil {
			scope.err(err, w, req)
			return
		}

		options := &metav1.PatchOptions{}
		if err := metainternalversionscheme.ParameterCodec.DecodeParameters(req.URL.Query(), scope.MetaGroupVersion, options); err != nil {
			err = errors.NewBadRequest(err.Error())
			scope.err(err, w, req)
			return
		}
		if errs := validation.ValidatePatchOptions(options, patchType); len(errs) > 0 {
			err := errors.NewInvalid(schema.GroupKind{Group: metav1.GroupName, Kind: "PatchOptions"}, "", errs)
			scope.err(err, w, req)
			return
		}
		options.TypeMeta.SetGroupVersionKind(metav1.SchemeGroupVersion.WithKind("PatchOptions"))

		reqInfo, _ := request.RequestInfoFrom(req.Context())
		pi := metaserver.PatchInfo{
			Name:         name,
			PatchType:    patchType,
			Data:         patchBytes,
			Options:      *options,
			Subresources: []string{reqInfo.Subresource},
		}

		retObj, err := f.storage.Patch(ctx, pi)
		if err != nil {
			scope.err(err, w, req)
			return
		}

		responsewriters.WriteObjectNegotiated(scope.Serializer, scope, scope.Kind.GroupVersion(), w, req, 200, retObj, false)
	}
	return http.HandlerFunc(h)
}

func (scope *wrapScope) err(err error, w http.ResponseWriter, req *http.Request) {
	responsewriters.ErrorNegotiated(err, scope.Serializer, scope.Kind.GroupVersion(), w, req)
}

func parseTimeout(str string) time.Duration {
	if str != "" {
		timeout, err := time.ParseDuration(str)
		if err == nil {
			return timeout
		}
		klog.Errorf("Failed to parse %q: %v", str, err)
	}
	// 34 chose as a number close to 30 that is likely to be unique enough to jump out at me the next time I see a timeout.  Everyone chooses 30.
	return 34 * time.Second
}

func limitedReadBody(req *http.Request, limit int64) ([]byte, error) {
	defer req.Body.Close()
	if limit <= 0 {
		return io.ReadAll(req.Body)
	}
	lr := &io.LimitedReader{
		R: req.Body,
		N: limit + 1,
	}
	data, err := io.ReadAll(lr)
	if err != nil {
		return nil, err
	}
	if lr.N <= 0 {
		return nil, errors.NewRequestEntityTooLargeError(fmt.Sprintf("limit is %d", limit))
	}
	return data, nil
}

func (f *Factory) Restart(namespace string) http.Handler {
	h := http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		podNameBytes, err := limitedReadBody(req, int64(3*1024*1024))
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		var podNames []string
		err = json.Unmarshal(podNameBytes, &podNames)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		restartInfo := common.RestartInfo{
			PodNames:  podNames,
			Namespace: namespace,
		}
		restartResponse := f.storage.Restart(req.Context(), restartInfo)
		restartResBytes, err := json.Marshal(restartResponse)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		_, err = w.Write(restartResBytes)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
	})
	return h
}

func (f *Factory) ConfirmUpgrade() http.Handler {
	h := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		klog.Info("Begin to run upgrade command")
		opts := options.GetEdgeCoreOptions()
		var upgradeReq commontypes.NodeUpgradeJobRequest
		var nodeTaskReq types.NodeTaskRequest
		nodeTaskReq, _ = upgradedb.QueryNodeTaskRequestFromMetaV2()
		upgradeReq, _ = upgradedb.QueryNodeUpgradeJobRequestFromMetaV2()
		upgradeCmd := fmt.Sprintf("keadm upgrade edge --upgradeID %s --historyID %s --fromVersion %s --toVersion %s --config %s --image %s > /tmp/keadm.log 2>&1",
			upgradeReq.UpgradeID, upgradeReq.HistoryID, version.Get(), upgradeReq.Version, opts.ConfigFile, upgradeReq.Image)

		executor, _ := taskexecutor.GetExecutor(taskexecutor.TaskUpgrade)
		event, _ := executor.Do(nodeTaskReq)
		klog.Info("Confirm Upgrade:" + event.Type + "," + event.Msg)
		// run upgrade cmd to upgrade edge node
		// use nohup command to start a child progress
		command := fmt.Sprintf("nohup %s &", upgradeCmd)
		cmd := exec.Command("bash", "-c", command)
		s, err := cmd.CombinedOutput()
		if err != nil {
			http.Error(w, fmt.Sprintf("run upgrade command %s failed: %v, res: %s", command, err, s),
				http.StatusInternalServerError)
			return
		}
		klog.Infof("Finish upgrade from Version %s to %s ...", version.Get(), upgradeReq.Version)
		err = upgradedb.DeleteNodeTaskRequestFromMetaV2()
		if err != nil {
			klog.Errorf("Failed to delete NodeTaskRequest%s", err.Error())
		}
		err = upgradedb.DeleteNodeUpgradeJobRequestFromMetaV2()
		if err != nil {
			klog.Errorf("Failed to delete NodeUpgradeJobRequest%s", err.Error())
		}
	})
	return h
}

func (f *Factory) Logs(request *request.RequestInfo) http.Handler {
	h := http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		queryParams := req.URL.Query()

		containerName := queryParams.Get("container")
		follow := queryParams.Get("follow")
		tailLines := queryParams.Get("tailLines")
		insecureSkipTLSVerifyBackend := queryParams.Get("insecureSkipTLSVerifyBackend")
		limitBytes := queryParams.Get("limitBytes")
		pretty := queryParams.Get("pretty")
		sinceSeconds := queryParams.Get("sinceSeconds")
		timestamps := queryParams.Get("timestamps")

		logsInfo := common.LogsInfo{
			PodName:                      request.Name,
			Namespace:                    request.Namespace,
			ContainerName:                containerName,
			Follow:                       follow,
			TailLines:                    tailLines,
			InsecureSkipTLSVerifyBackend: insecureSkipTLSVerifyBackend,
			LimitBytes:                   limitBytes,
			Pretty:                       pretty,
			SinceSeconds:                 sinceSeconds,
			Timestamps:                   timestamps,
		}

		logsResponse, res := f.storage.Logs(req.Context(), logsInfo)
		if res == nil {
			http.Error(w, "Failed to get logs from edged", http.StatusInternalServerError)
			return
		}

		defer res.Body.Close()

		if res.StatusCode != http.StatusOK {
			http.Error(w, fmt.Sprintf("Unexpected status code from edged: %d", res.StatusCode), http.StatusInternalServerError)
			return
		}

		if logsInfo.Follow != "true" {
			buf := &bytes.Buffer{}
			if _, err := io.Copy(buf, res.Body); err != nil {
				errMessage := fmt.Sprintf("failed to read logs with err:%v\n", err)
				klog.Warningf("[metaserver/logs] %v", errMessage)
				logsResponse.ErrMessages = append(logsResponse.ErrMessages, errMessage)
			}

			logsResponse.LogMessages = append(logsResponse.LogMessages, buf.String())

			logsResBytes, err := json.Marshal(logsResponse)
			if err != nil {
				http.Error(w, err.Error(), http.StatusInternalServerError)
				return
			}
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusOK)
			_, err = w.Write(logsResBytes)
			if err != nil {
				http.Error(w, err.Error(), http.StatusInternalServerError)
				return
			}
		} else {
			// Logs are streamed
			w.Header().Set("Content-Type", "text/plain")
			w.Header().Set("Transfer-Encoding", "chunked")
			w.WriteHeader(http.StatusOK)

			flusher, ok := w.(http.Flusher)
			if !ok {
				http.Error(w, "Streaming not supported", http.StatusInternalServerError)
				return
			}

			scanner := bufio.NewScanner(res.Body)
			for scanner.Scan() {
				fmt.Fprintln(w, scanner.Text())
				flusher.Flush()
			}

			if err := scanner.Err(); err != nil {
				http.Error(w, fmt.Sprintf("Error reading logs: %v", err), http.StatusInternalServerError)
				return
			}
		}
	})
	return h
}

func (f *Factory) Exec(request *request.RequestInfo) http.Handler {
	h := http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		queryparams := req.URL.Query()

		commands := queryparams["command"]
		container := queryparams.Get("container")
		stdinStr := queryparams.Get("stdin")
		stdoutStr := queryparams.Get("stdout")
		stderrStr := queryparams.Get("stderr")
		ttyStr := queryparams.Get("tty")

		stdin := stdinStr == trueStr
		stdout := stdoutStr == trueStr
		stderr := stderrStr == trueStr
		tty := ttyStr == trueStr

		execInfo := common.ExecInfo{
			Namespace: request.Namespace,
			PodName:   request.Name,
			Container: container,
			Commands:  commands,
			Stdin:     stdin,
			Stdout:    stdout,
			Stderr:    stderr,
			TTY:       tty,
		}

		execResponse, handler := f.storage.Exec(req.Context(), execInfo)

		if handler != nil {
			handler.ServeHTTP(w, req)
		} else {
			execResBytes, err := json.Marshal(execResponse)
			if err != nil {
				http.Error(w, err.Error(), http.StatusInternalServerError)
				return
			}
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusOK)
			_, err = w.Write(execResBytes)
			if err != nil {
				http.Error(w, err.Error(), http.StatusInternalServerError)
				return
			}
		}
	})
	return h
}

