func NewDataBaseClient(clientConfig json.RawMessage, dataConfig json.RawMessage) (*DataBaseConfig, error) {
	// parse influx database config data
	influxdb2ClientConfig := new(Influxdb2ClientConfig)
	influxdb2DataConfig := new(Influxdb2DataConfig)
	err := json.Unmarshal(clientConfig, influxdb2ClientConfig)
	if err != nil {
		return nil, err
	}
	err = json.Unmarshal(dataConfig, influxdb2DataConfig)
	if err != nil {
		return nil, err
	}
	return &DataBaseConfig{
		Influxdb2ClientConfig: influxdb2ClientConfig,
		Influxdb2DataConfig:   influxdb2DataConfig,
	}, nil
}

func (d *DataBaseConfig) InitDbClient() influxdb2.Client {
	var usrtoken string
	usrtoken = os.Getenv("TOKEN")
	client := influxdb2.NewClient(d.Influxdb2ClientConfig.Url, usrtoken)

	return client
}

func (d *DataBaseConfig) CloseSession(client influxdb2.Client) {
	client.Close()
}

func (d *DataBaseConfig) AddData(data *common.DataModel, client influxdb2.Client) error {
	// write device data to influx database
	writeAPI := client.WriteAPIBlocking(d.Influxdb2ClientConfig.Org, d.Influxdb2ClientConfig.Bucket)
	p := influxdb2.NewPoint(d.Influxdb2DataConfig.Measurement,
		d.Influxdb2DataConfig.Tag,
		map[string]interface{}{d.Influxdb2DataConfig.FieldKey: data.Value},
		time.Now())
	// write point immediately
	err := writeAPI.WritePoint(context.Background(), p)
	if err != nil {
		klog.V(4).Info("Exit AddData")
		return err
	}
	return nil
}

func DataHandler(ctx context.Context, twin *common.Twin, client *driver.CustomizedClient, visitorConfig *driver.VisitorConfig, dataModel *common.DataModel) {
	dbConfig, err := NewDataBaseClient(twin.Property.PushMethod.DBMethod.DBConfig.Influxdb2ClientConfig, twin.Property.PushMethod.DBMethod.DBConfig.Influxdb2DataConfig)
	if err != nil {
		klog.Errorf("new database client error: %v", err)
		return
	}
	dbClient := dbConfig.InitDbClient()
	if err != nil {
		klog.Errorf("init database client err: %v", err)
		return
	}
	reportCycle := time.Millisecond * time.Duration(twin.Property.ReportCycle)
	if reportCycle == 0 {
		reportCycle = common.DefaultReportCycle
	}
	ticker := time.NewTicker(reportCycle)
	go func() {
		for {
			select {
			case <-ticker.C:
				deviceData, err := client.GetDeviceData(visitorConfig)
				if err != nil {
					klog.Errorf("publish error: %v", err)
					continue
				}
				sData, err := common.ConvertToString(deviceData)
				if err != nil {
					klog.Errorf("Failed to convert publish method data : %v", err)
					continue
				}
				dataModel.SetValue(sData)
				dataModel.SetTimeStamp()

				err = dbConfig.AddData(dataModel, dbClient)
				if err != nil {
					klog.Errorf("influx database add data error: %v", err)
					return
				}
			case <-ctx.Done():
				dbConfig.CloseSession(dbClient)
				return
			}
		}
	}()
}

func InitHandler() {
	timeout := routerConfig.Config.RestTimeout
	if timeout <= 0 {
		timeout = 60
	}
	RestHandlerInstance.restTimeout = time.Duration(timeout) * time.Second
	RestHandlerInstance.bindAddress = routerConfig.Config.Address
	RestHandlerInstance.port = int(routerConfig.Config.Port)
	if RestHandlerInstance.port <= 0 {
		RestHandlerInstance.port = 9443
	}
	klog.Infof("rest init: %v", RestHandlerInstance)
}

func (rh *RestHandler) Serve() {
	mux := http.NewServeMux()
	mux.HandleFunc("/", rh.httpHandler)

	server := &http.Server{
		Addr:    fmt.Sprintf("%s:%d", rh.bindAddress, rh.port),
		Handler: mux,
		// TODO: add tls for router
	}
	klog.Infof("router server listening in %d...", rh.port)
	//err := server.ListenAndServeTLS("", "")
	if err := server.ListenAndServe(); err != nil {
		klog.Errorf("start rest endpoint failed, err: %v", err)
	}
}

func (rh *RestHandler) AddListener(key interface{}, han Handle) {
	path, ok := key.(string)
	if !ok {
		return
	}

	rh.handlers.Store(path, han)
}

func (rh *RestHandler) RemoveListener(key interface{}) {
	path, ok := key.(string)
	if !ok {
		return
	}
	rh.handlers.Delete(path)
}

func (rh *RestHandler) matchedPath(uri string) (string, bool) {
	var candidateRes string
	rh.handlers.Range(func(key, value interface{}) bool {
		pathReg, ok := key.(string)
		if !ok {
			klog.Errorf("key type %T error", key)
			return true
		}
		if match := utils.IsMatch(pathReg, uri); match {
			if candidateRes != "" && utils.RuleContains(pathReg, candidateRes) {
				return true
			}
			candidateRes = pathReg
		}
		return true
	})
	if candidateRes == "" {
		return "", false
	}
	return candidateRes, true
}

func (rh *RestHandler) httpHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Transfer-Encoding", "chunked")
	uriSections := strings.Split(r.RequestURI, "/")
	if len(uriSections) < 2 {
		// URL format incorrect
		err := fmt.Errorf("url format incorrect: %s", r.URL.String())
		writeErr(w, r, http.StatusNotFound, err)
		return
	}

	aReaderCloser := http.MaxBytesReader(w, r.Body, MaxMessageBytes)
	b, err := io.ReadAll(aReaderCloser)
	if err != nil {
		writeErr(w, r, http.StatusBadRequest, err)
		return
	}

	edgeNodeName := uriSections[1]
	err = retry.Do(
		func() error {
			targetCloudCoreIP, err := GetEdgeToCloudCoreIP(r.Context(), edgeNodeName)
			if err != nil {
				return err
			}

			hostnameOverride := util.GetHostname()
			localIP, err := util.GetLocalIP(hostnameOverride)
			if err != nil {
				return fmt.Errorf("failed to get cloudcore localIP with err:%v", err)
			}
			if targetCloudCoreIP != localIP {
				var url string
				if r.TLS != nil {
					url = "https://" + targetCloudCoreIP
				} else {
					url = "http://" + targetCloudCoreIP
				}
				url += ":" + strconv.Itoa(rh.port) + r.RequestURI
				reqBody := io.NopCloser(bytes.NewBuffer(b))
				forwardReq, err := http.NewRequest(r.Method, url, reqBody)
				if err != nil {
					return fmt.Errorf("failed to create forward request: %v", err)
				}

				forwardReq.TLS = r.TLS
				forwardReq.Header = make(http.Header)
				for key, values := range r.Header {
					forwardReq.Header[key] = values
				}
				return requestForward(targetCloudCoreIP, w, forwardReq)
			}

			matchPath, exist := rh.matchedPath(r.RequestURI)
			if !exist {
				klog.Warningf("URL format incorrect: %s", r.RequestURI)
				w.WriteHeader(http.StatusNotFound)
				if _, err := w.Write([]byte("Request error")); err != nil {
					klog.Errorf("Response write error: %s, %s", r.RequestURI, err.Error())
				}
				return nil
			}
			v, ok := rh.handlers.Load(matchPath)
			if !ok {
				klog.Warningf("No matched handler for path: %s", matchPath)
				return nil
			}
			handle, ok := v.(Handle)
			if !ok {
				klog.Errorf("invalid convert to Handle. match path: %s", matchPath)
				return nil
			}

			if isNodeName(uriSections[1]) {
				params := make(map[string]interface{})
				msgID := uuid.New().String()
				params["messageID"] = msgID
				params["request"] = r
				params["timeout"] = rh.restTimeout
				params["data"] = b

				v, err := handle(params)
				if err != nil {
					klog.Errorf("handle request error, msg id: %s, err: %v", msgID, err)
					return nil
				}
				response, ok := v.(*http.Response)
				if !ok {
					klog.Errorf("response convert error, msg id: %s", msgID)
					return nil
				}
				body, err := io.ReadAll(io.LimitReader(response.Body, MaxMessageBytes))
				if err != nil {
					klog.Errorf("response body read error, msg id: %s, reason: %v", msgID, err)
					return nil
				}
				for key, values := range response.Header {
					for _, value := range values {
						w.Header().Add(key, value)
					}
				}

				if response.StatusCode != http.StatusOK {
					errMsg := string(body)
					return errors.New(errMsg)
				}

				w.WriteHeader(response.StatusCode)
				if _, err = w.Write(body); err != nil {
					klog.Errorf("response body write error, msg id: %s, reason: %v", msgID, err)
					return nil
				}
				klog.Infof("response to client, msg id: %s, write result: success", msgID)
				return nil
			}
			w.WriteHeader(http.StatusNotFound)
			_, err = w.Write([]byte("No rule match"))
			klog.Infof("no rule match, write result: %v", err)
			return nil
		},
		retry.Delay(1*time.Second),
		retry.Attempts(3),
		retry.DelayType(retry.FixedDelay),
	)

	if err != nil {
		writeErr(w, r, http.StatusInternalServerError, err)
		return
	}
}

func (rh *RestHandler) IsMatch(key interface{}, message interface{}) bool {
	res, ok := key.(string)
	if !ok {
		return false
	}
	uri, ok := message.(string)
	if !ok {
		return false
	}
	return utils.IsMatch(res, uri)
}

func isNodeName(_ string) bool {
	return true
}

func GetEdgeToCloudCoreIP(ctx context.Context, nodeName string) (string, error) {
	node, err := client.GetKubeClient().CoreV1().Nodes().Get(ctx, nodeName, metav1.GetOptions{})
	if err != nil {
		return "", fmt.Errorf("failed to get node:%s,err:%v", nodeName, err)
	}
	cloudCoreIP, ok := node.Annotations[constants.EdgeMappingCloudKey]
	if !ok {
		return "", fmt.Errorf("no corresponding cloudcore was found for edgeNode:%s", nodeName)
	}
	return cloudCoreIP, nil
}

func requestForward(targetCloudCoreIP string, w http.ResponseWriter, forwardReq *http.Request) error {
	httpClient := &http.Client{}
	resp, err := httpClient.Do(forwardReq)
	if err != nil {
		return fmt.Errorf("failed to forward request: %v", err)
	}
	defer func(Body io.ReadCloser) {
		err := Body.Close()
		if err != nil {
			klog.Errorf("failed to close resp.Body with err:%v", err)
		}
	}(resp.Body)

	for key, values := range resp.Header {
		for _, value := range values {
			w.Header().Add(key, value)
		}
	}

	if resp.StatusCode != http.StatusOK {
		bodyBytes, err := io.ReadAll(resp.Body)
		if err != nil {
			return fmt.Errorf("error reading body:%v", err)
		}
		errMsg := string(bodyBytes)
		return errors.New(errMsg)
	}

	w.WriteHeader(resp.StatusCode)
	_, err = io.Copy(w, resp.Body)
	if err != nil {
		return fmt.Errorf("failed to copy resp.Body to writer with err:%v", err)
	}

	klog.Infof("forwarded request to %s successfully", targetCloudCoreIP)
	return nil
}

func writeErr(w http.ResponseWriter, r *http.Request, statusCode int, err error) {
	klog.Errorf(err.Error())
	w.WriteHeader(statusCode)
	if _, err := w.Write([]byte(err.Error())); err != nil {
		klog.Errorf("Response write error: %s, %s", r.RequestURI, err.Error())
	}
}

func (mh *MessageHandler) AddListener(key interface{}, han Handle) {
	resource, ok := key.(string)
	if !ok {
		return
	}
	mh.handlers.Store(resource, han)
}

func (mh *MessageHandler) RemoveListener(key interface{}) {
	resource, ok := key.(string)
	if !ok {
		return
	}
	mh.handlers.Delete(resource)
}

func (mh *MessageHandler) getHandler(source string, resource string) (Handle, error) {
	rs := strings.Split(resource, "/")
	if len(rs) >= 2 && (rs[0] == model.ResourceTypeRuleEndpoint || rs[0] == model.ResourceTypeRule) {
		resource = rs[0]
	}
	key := fmt.Sprintf("%s/%s", source, resource)
	v, exist := mh.handlers.Load(key)
	if !exist {
		return nil, errors.New("no handler for message")
	}
	handle, ok := v.(Handle)
	if !ok {
		return nil, fmt.Errorf("handler invalid, key is %s", key)
	}
	return handle, nil
}

func Process(module string) {
	for {
		select {
		case <-beehiveContext.Done():
			klog.Info("router module stop dispatch message")
			return
		default:
		}
		msg, err := beehiveContext.Receive(module)
		if err != nil {
			klog.Errorf("get a message, header:%+v router:%+v, err: %v", msg.Header, msg.Router, err)
			continue
		}
		klog.Infof("get a message, header:%+v router:%+v", msg.Header, msg.Router)
		err = MessageHandlerInstance.HandleMessage(&msg)
		if err != nil {
			klog.Errorf("Process msg error: %s.", err.Error())
		}
	}
}

func (mh *MessageHandler) HandleMessage(message *model.Message) error {
	if message == nil {
		return fmt.Errorf("nil message error")
	}
	if message.GetParentID() != "" {
		mh.callback(message)
		return nil
	}
	handler, err := mh.getHandler(message.GetSource(), message.GetResource())
	if err != nil {
		klog.Errorf("No handler for message.msgID: %s, source: %s, resource %s can't find candidate", message.GetID(), message.GetSource(), message.GetResource())
		return err
	}
	go func(message *model.Message) {
		resp, err := handler(message)
		if err != nil {
			klog.Errorf("handle message occur error, msgID: %s, reason: %s", message.GetID(), err.Error())
		}
		if resp != nil {
			if err = resp.(*http.Response).Body.Close(); err != nil {
				klog.Errorf("close response occur error, msgID: %s, reason: %s", message.GetID(), err.Error())
			}
		}
	}(message)

	return nil
}

func (mh *MessageHandler) SetCallback(messageID string, callback func(message *model.Message)) {
	mh.callbackHandlers.Store(messageID, callback)
}

func (mh *MessageHandler) DelCallback(messageID string) {
	mh.callbackHandlers.Delete(messageID)
}

func (mh *MessageHandler) callback(message *model.Message) {
	pID := message.GetParentID()
	v, exist := mh.callbackHandlers.Load(pID)
	if exist {
		callback, ok := v.(func(message *model.Message))
		if !ok {
			klog.Warningf("invalid convert to model.Message")
			return
		}
		callback(message)
	}
	mh.callbackHandlers.Delete(pID)
}

func newTaskManager(enable bool) *TaskManager {
	if !enable {
		return &TaskManager{enable: enable}
	}
	taskMessage := make(chan util.TaskMessage, 10)
	downStreamMessage := make(chan model.Message, 10)
	downstream, err := manager.NewDownstreamController(downStreamMessage)
	if err != nil {
		klog.Exitf("New task manager downstream failed with error: %s", err)
	}
	upstream, err := manager.NewUpstreamController(downstream)
	if err != nil {
		klog.Exitf("New task manager upstream failed with error: %s", err)
	}
	executorMachine, err := manager.NewExecutorMachine(taskMessage, downStreamMessage)
	if err != nil {
		klog.Exitf("New executor machine failed with error: %s", err)
	}

	upgradeNodeController, err := nodeupgradecontroller.NewNodeUpgradeController(taskMessage)
	if err != nil {
		klog.Exitf("New upgrade node controller failed with error: %s", err)
	}

	imagePrePullController, err := imageprepullcontroller.NewImagePrePullController(taskMessage)
	if err != nil {
		klog.Exitf("New upgrade node controller failed with error: %s", err)
	}
	controller.Register(util.TaskUpgrade, upgradeNodeController)
	controller.Register(util.TaskPrePull, imagePrePullController)

	return &TaskManager{
		downstream:      downstream,
		executorMachine: executorMachine,
		upstream:        upstream,
		enable:          enable,
	}
}

func Register(dc *v1alpha1.TaskManager) {
	config.InitConfigure(dc)
	core.Register(newTaskManager(dc.Enable))
	//core.Register(newNodeUpgradeJobController())
}

func (uc *TaskManager) Name() string {
	return modules.TaskManagerModuleName
}

func (uc *TaskManager) Group() string {
	return modules.TaskManagerModuleGroup
}

func (uc *TaskManager) Enable() bool {
	return uc.enable
}

func (uc *TaskManager) Start() {
	if err := uc.downstream.Start(); err != nil {
		klog.Exitf("start task manager downstream failed with error: %s", err)
	}
	// wait for downstream controller to start and load NodeUpgradeJob
	// TODO think about sync
	time.Sleep(1 * time.Second)
	if err := uc.upstream.Start(); err != nil {
		klog.Exitf("start task manager upstream failed with error: %s", err)
	}
	if err := uc.executorMachine.Start(); err != nil {
		klog.Exitf("start task manager executorMachine failed with error: %s", err)
	}

	if err := controller.StartAllController(); err != nil {
		klog.Exitf("start controller failed with error: %s", err)
	}
}

