func SendHTTPRequest(method, reqAPI string) (*http.Response, error) {
	var body io.Reader
	var resp *http.Response

	tr := &http.Transport{
		TLSClientConfig: &tls.Config{InsecureSkipVerify: true},
	}
	client := &http.Client{
		Transport: tr,
	}
	req, err := http.NewRequest(method, reqAPI, body)
	if err != nil {
		// handle error
		Fatalf("Frame HTTP request failed: %v", err)
		return resp, err
	}
	req.Header.Set("Content-Type", "application/json")
	t := time.Now()
	resp, err = client.Do(req)
	if err != nil {
		// handle error
		Fatalf("HTTP request is failed :%v", err)
		return resp, err
	}
	Infof("%s %s %v in %v", req.Method, req.URL, resp.Status, time.Since(t))
	return resp, nil
}

func (testTimer *TestTimer) End() {
	if !testTimer.IsEnded() {
		testTimer.EndTime = time.Now()
	}
}

func (testTimer *TestTimer) IsEnded() bool {
	return !testTimer.EndTime.IsZero()
}

func (testTimer *TestTimer) Duration() time.Duration {
	endTime := testTimer.EndTime
	if !testTimer.IsEnded() {
		endTime = time.Now()
	}
	return endTime.Sub(testTimer.StartTime)
}

