func TestRuleContains(t *testing.T) {
	cases := []struct {
		name      string
		rulePath  string
		rule2Path string
		want      bool
	}{
		{
			name:      "case1",
			rulePath:  "/a",
			rule2Path: "/a/b",
			want:      true,
		},
		{
			name:      "case2",
			rulePath:  "/a",
			rule2Path: "/b",
			want:      false,
		},
	}

	for _, c := range cases {
		if actual := RuleContains(c.rulePath, c.rule2Path); c.want != actual {
			t.Errorf("%v: expected %v, but got %v", c.name, c.want, actual)
		}
	}
}

