}

func NewCommonResourceEventHandler(
	gvr schema.GroupVersionResource,
	listenerManager *listenerManager,
	layer messagelayer.MessageLayer) *CommonResourceEventHandler {
	handler := &CommonResourceEventHandler{
		listenerManager: listenerManager,
		events:          make(chan watch.Event, 100),
		messageLayer:    layer,
		gvr:             gvr,
	}

	klog.Infof("[metaserver/resourceEventHandler] handler(%v) init, prepare informer...", gvr)
	informerPair, err := genericinformers.GetInformersManager().GetInformerPair(gvr)
	if err != nil {
		klog.Exitf("get informer for %s err: %v", gvr.String(), err)
	}

	_, err = informerPair.Informer.AddEventHandler(cache.ResourceEventHandlerFuncs{
		AddFunc: func(obj interface{}) {
			handler.objToEvent(watch.Added, obj)
		},
		UpdateFunc: func(oldObj, obj interface{}) {
			handler.objToEvent(watch.Modified, obj)
		},
		DeleteFunc: func(obj interface{}) {
			handler.objToEvent(watch.Deleted, obj)
		},
	})
	if err != nil {
		klog.Exitf("add evenet handler err: %v", err)
	}

	handler.informer = informerPair
	klog.Infof("[metaserver/resourceEventHandler] handler(%v) init successfully, start to dispatch events to it's listeners", gvr)
	go handler.dispatchEvents()
	return handler
}

func (c *CommonResourceEventHandler) objToEvent(t watch.EventType, obj interface{}) {
	eventObj, ok := obj.(runtime.Object)
	if !ok {
		klog.Warningf("Unknown type: %T, ignore", obj)
		return
	}
	// All obj from client has been removed the information of apiversion/kind called MetaType,
	// which is fatal to decode the obj as unstructured.Unstructure or unstructured.UnstructureList at edge.
	err := util.SetMetaType(eventObj)
	if err != nil {
		klog.Warningf("Failed to set metatype :%v", err)
	}
	c.events <- watch.Event{Type: t, Object: eventObj}
}

func (c *CommonResourceEventHandler) AddListener(s *SelectorListener) error {
	// filter s.selector.field when sendAllObjects
	ret, err := c.informer.Lister.List(s.selector.Label)
	if err != nil {
		return fmt.Errorf("Failed to list: %v", err)
	}
	s.sendAllObjects(ret, c)

	c.listenerManager.AddListener(s)

	return nil
}

func (c *CommonResourceEventHandler) DeleteListener(s *SelectorListener) {
	c.listenerManager.DeleteListener(s)
}

func (c *CommonResourceEventHandler) dispatchEvents() {
	for event := range c.events {
		klog.V(4).Infof("[metaserver/resourceEventHandler] handler(%v), send obj event{%v/%v} to listeners", c.gvr, event.Type, event.Object.GetObjectKind().GroupVersionKind().String())
		for _, listener := range c.listenerManager.GetListenersForGVR(c.gvr) {
			listener.sendObj(event, c.messageLayer)
		}
	}
	klog.Warningf("[metaserver/resourceEventHandler] handler(%v) stopped!", c.gvr.String())
}

func NewSelectorListener(ID, nodeName string, gvr schema.GroupVersionResource, selector LabelFieldSelector) *SelectorListener {
	return &SelectorListener{id: ID, nodeName: nodeName, gvr: gvr, selector: selector}
}

func (l *SelectorListener) sendAllObjects(rets []runtime.Object, handler *CommonResourceEventHandler) {
	for _, ret := range rets {
		event := watch.Event{
			Type:   watch.Added,
			Object: ret,
		}
		l.sendObj(event, handler.messageLayer)
	}
}

func (l *SelectorListener) sendObj(event watch.Event, messageLayer messagelayer.MessageLayer) {
	accessor, err := meta.Accessor(event.Object)
	if err != nil {
		klog.Error(err)
		return
	}
	klog.V(4).Infof("[dynamiccontroller/selectorListener] listener(%v) is sending obj %v", *l, accessor.GetName())
	// do not send obj if obj does not match listener's selector
	if !l.selector.MatchObj(event.Object) {
		return
	}
	// filter message
	filterEvent := *(event.DeepCopy())
	filter.MessageFilter(filterEvent.Object, l.nodeName)

	namespace := accessor.GetNamespace()
	if namespace == "" {
		namespace = v2.NullNamespace
	}
	kind := util.UnsafeResourceToKind(l.gvr.Resource)
	resourceType := strings.ToLower(kind)
	resource, err := messagelayer.BuildResource(l.nodeName, namespace, resourceType, accessor.GetName())
	if err != nil {
		klog.Warningf("built message resource failed with error: %s", err)
		return
	}

	var operation string
	switch filterEvent.Type {
	case watch.Added:
		operation = model.InsertOperation
	case watch.Modified:
		operation = model.UpdateOperation
	case watch.Deleted:
		operation = model.DeleteOperation
	default:
		klog.Warningf("event type: %s unsupported", filterEvent.Type)
		return
	}

	msg := model.NewMessage("").
		SetResourceVersion(accessor.GetResourceVersion()).
		BuildRouter(modules.DynamicControllerModuleName, constants.GroupResource, resource, operation).
		FillBody(filterEvent.Object)

	if err := messageLayer.Send(*msg); err != nil {
		klog.Warningf("send message failed with error: %s, operation: %s, resource: %s", err, msg.GetOperation(), msg.GetResource())
	} else {
		klog.V(4).Infof("send message successfully, operation: %s, resource: %s", msg.GetOperation(), msg.GetResource())
	}
}

func newListenerManager() *listenerManager {
	return &listenerManager{
		listenerByNodeID: make(map[string]map[string]*SelectorListener),
		listenerByGVR:    make(map[schema.GroupVersionResource]map[string]*SelectorListener),
	}
}

func (lm *listenerManager) AddListener(listener *SelectorListener) {
	lm.lock.Lock()
	defer lm.lock.Unlock()

	klog.Infof("add listener %s node %s", listener.id, listener.nodeName)

	_, exists := lm.listenerByNodeID[listener.nodeName]
	if !exists {
		lm.listenerByNodeID[listener.nodeName] = map[string]*SelectorListener{}
	}
	lm.listenerByNodeID[listener.nodeName][listener.id] = listener

	_, exists = lm.listenerByGVR[listener.gvr]
	if !exists {
		lm.listenerByGVR[listener.gvr] = map[string]*SelectorListener{}
	}
	lm.listenerByGVR[listener.gvr][listener.id] = listener
}

func (lm *listenerManager) DeleteListener(listener *SelectorListener) {
	lm.lock.Lock()
	defer lm.lock.Unlock()

	listeners, exists := lm.listenerByNodeID[listener.nodeName]
	if exists {
		delete(listeners, listener.id)
		if len(lm.listenerByNodeID[listener.nodeName]) == 0 {
			delete(lm.listenerByNodeID, listener.nodeName)
		}
	}

	listeners, exists = lm.listenerByGVR[listener.gvr]
	if exists {
		delete(listeners, listener.id)
		if len(lm.listenerByGVR[listener.gvr]) == 0 {
			delete(lm.listenerByGVR, listener.gvr)
		}
	}
}

func (lm *listenerManager) GetListenersForNode(nodeName string) map[string]*SelectorListener {
	lm.lock.RLock()
	defer lm.lock.RUnlock()

	listeners, exists := lm.listenerByNodeID[nodeName]
	if !exists {
		return nil
	}

	return listeners
}

func (lm *listenerManager) GetListenersForGVR(gvr schema.GroupVersionResource) map[string]*SelectorListener {
	lm.lock.RLock()
	defer lm.lock.RUnlock()

	listeners, exists := lm.listenerByGVR[gvr]
	if !exists {
		return nil
	}

	return listeners
}

func TestAddListener(t *testing.T) {
	assert := assert.New(t)

	listener1 := NewSelectorListener("testID1", "node1", testGVR, selector1)
	listener2 := NewSelectorListener("testID2", "node2", testGVR, selector2)

	lm := newListenerManager()

	lm.AddListener(listener1)
	lm.AddListener(listener2)

	listenerByNodeID := lm.GetListenersForNode("node1")
	assert.Len(listenerByNodeID, 1)

	for _, v := range listenerByNodeID {
		assert.Equal(listener1, v)
