	testCases := []struct {
		name              string
		metas             []string
		expectedConfigMap *api.ConfigMap
		expectedErr       bool
	}{
		{
			name:  "Valid ConfigMap",
			metas: []string{"{\"metadata\":{\"name\":\"test-config\",\"namespace\":\"default\"},\"data\":{\"key\":\"value\"}}"},
			expectedConfigMap: &api.ConfigMap{
				Data: map[string]string{"key": "value"},
