			expectedErr: false,
		},
		{
			name:              "Invalid JSON",
			metas:             []string{"invalid json"},
			expectedConfigMap: nil,
			expectedErr:       true,
		},
		{
			name:              "Empty list",
			metas:             []string{},
			expectedConfigMap: nil,
			expectedErr:       true,
		},
		{
			name:              "Multiple ConfigMaps",
			metas:             []string{"", ""},
