func CheckTokenExist(token string) bool {
	if token == "" {
		return false
	}
	metas, err := dao.QueryMeta("type", model.ResourceTypeServiceAccountToken)
	if err != nil {
		klog.Errorf("query meta %s failed: %v", model.ResourceTypeServiceAccountToken, err)
		return false
	}

	for _, v := range *metas {
		var tokenRequest authenticationv1.TokenRequest
		err = json.Unmarshal([]byte(v), &tokenRequest)
		if err != nil {
			klog.Errorf("unmarshal resource %s token request failed: %v", model.ResourceTypeServiceAccountToken, err)
			return false
		}
		if tokenRequest.Status.Token == token {
			return true
		}
	}
	return false
}

func TestRequiresRefresh(t *testing.T) {
	assert := assert.New(t)

	now := time.Now()
	testcases := []struct {
		name     string
		tr       *authenticationv1.TokenRequest
		expected bool
	}{
		{
			name: "Not expired",
			tr: &authenticationv1.TokenRequest{
				Spec: authenticationv1.TokenRequestSpec{
					ExpirationSeconds: func() *int64 { i := int64(3600); return &i }(),
				},
				Status: authenticationv1.TokenRequestStatus{
					ExpirationTimestamp: metav1.NewTime(now.Add(time.Hour)),
				},
			},
			expected: false,
		},
		{
			name: "Expired",
			tr: &authenticationv1.TokenRequest{
				Spec: authenticationv1.TokenRequestSpec{
					ExpirationSeconds: func() *int64 { i := int64(3600); return &i }(),
				},
				Status: authenticationv1.TokenRequestStatus{
					ExpirationTimestamp: metav1.NewTime(now.Add(-time.Hour)),
				},
			},
			expected: true,
		},
	}

	for _, test := range testcases {
		t.Run(test.name, func(t *testing.T) {
			result := requiresRefresh(test.tr)
			assert.Equal(test.expected, result)
		})
	}
}

func TestKeyFunc(t *testing.T) {
	assert := assert.New(t)

	testcases := []struct {
		name      string
		saName    string
		namespace string
		tr        *authenticationv1.TokenRequest
		expected  string
	}{
