func LogsRequest(namespace string, podName string, containerName string, logsInfo common.LogsInfo) *Request {
	queryString, err := structToQueryString(logsInfo)
	if err != nil {
		return nil
	}
	return &Request{
		Method: http.MethodGet,
		Path:   "/" + CONTAINERLOGS + "/" + namespace + "/" + podName + "/" + containerName + "?" + queryString,
	}
}

func structToQueryString(s interface{}) (string, error) {
	v := reflect.ValueOf(s)
	t := reflect.TypeOf(s)

	values := url.Values{}
	for i := 0; i < v.NumField(); i++ {
		field := v.Field(i)
		fieldType := t.Field(i)
		tag := fieldType.Tag.Get("query")

		if fieldType.Name == "Namespace" || fieldType.Name == "PodName" || fieldType.Name == "ContainerName" {
			continue
		}

		if field.IsZero() {
			continue
		}

		switch field.Kind() {
		case reflect.String:
			values.Add(tag, field.String())
		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
			values.Add(tag, strconv.FormatInt(field.Int(), 10))
		}
	}
	return values.Encode(), nil
}

func (req *Request) RestfulRequest() (*http.Response, error) {
	var client http.Client
	edgedAddress := config.Config.Edged.TailoredKubeletConfig.Address
	edgedPort := config.Config.Edged.TailoredKubeletConfig.ReadOnlyPort
	port := strconv.Itoa(int(edgedPort))

	url := "http://" + edgedAddress + ":" + port
	client = http.Client{}

	request, err := http.NewRequest(req.Method, url+req.Path, req.Body)
	if err != nil {
		return nil, fmt.Errorf("restful format failed with err: %v", err)
	}
	response, err := client.Do(request)
	if err != nil {
		return nil, fmt.Errorf("restful request failed with err: %v", err)
	}
	return response, nil
}

func init() {
	core.Register(&stubCloudHub{enable: true})
}

func (*stubCloudHub) Name() string {
	return "stubCloudHub"
}

func (*stubCloudHub) Group() string {
	//return core.MetaGroup
	return modules.MetaGroup
}

func (tm *stubCloudHub) Enable() bool {
	return tm.enable
}

func (tm *stubCloudHub) eventReadLoop(conn *websocket.Conn, stop chan bool) {
	for {
		var event interface{}
		err := conn.ReadJSON(&event)
		if err != nil {
			klog.Errorf("read error, connection will be closed: %v", err)
			stop <- true
			return
		}
		klog.Infof("cloud hub receive message %+v", event)
	}
}

func (tm *stubCloudHub) serveEvent(w http.ResponseWriter, r *http.Request) {
	upgrader := websocket.Upgrader{}
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		klog.Errorf("fail to build websocket connection: %v", err)
		http.Error(w, "fail to upgrade to websocket protocol", http.StatusInternalServerError)
