func (e *edgestream) Start() {
	serverURL := url.URL{
		Scheme: "wss",
		Host:   config.Config.TunnelServer,
		Path:   "/v1/kubeedge/connect",
	}
	// TODO: Will improve in the future
	if ok := <-edgehub.GetCertSyncChannel()[e.Name()]; !ok {
		klog.Exitf("Failed to find cert key pair")
	}

	cert, err := tls.LoadX509KeyPair(config.Config.TLSTunnelCertFile, config.Config.TLSTunnelPrivateKeyFile)
	if err != nil {
		klog.Exitf("Failed to load x509 key pair: %v", err)
	}
	tlsConfig := &tls.Config{
		InsecureSkipVerify: true,
		Certificates:       []tls.Certificate{cert},
	}

	ticker := time.NewTicker(time.Second * 2)
	defer ticker.Stop()

	for {
		select {
		case <-beehiveContext.Done():
			return
		case <-ticker.C:
			err := e.TLSClientConnect(serverURL, tlsConfig)
			if err != nil {
				klog.Errorf("TLSClientConnect error %v", err)
			}
		}
	}
}

func (e *edgestream) TLSClientConnect(url url.URL, tlsConfig *tls.Config) error {
	klog.Info("Start a new tunnel stream connection ...")

	// If the node IP address is not specified in the configuration file,
	// the node IP address is reacquired each time the tunnel stream is reconnected
	var nodeIP string
	if e.nodeIP == "" {
		ip, err := util.GetLocalIP(util.GetHostname())
		if err != nil {
			return fmt.Errorf("failed to get Local IP address: %v", err)
		}
		klog.Infof("get node local IP address successfully: %s", ip)
		nodeIP = ip
	} else {
		nodeIP = e.nodeIP
	}

	dial := websocket.Dialer{
		TLSClientConfig:  tlsConfig,
		HandshakeTimeout: time.Duration(config.Config.HandshakeTimeout) * time.Second,
	}
	header := http.Header{}
	header.Add(stream.SessionKeyHostNameOverride, e.hostnameOverride)
	header.Add(stream.SessionKeyInternalIP, nodeIP)

	con, _, err := dial.Dial(url.String(), header)
	if err != nil {
		klog.Errorf("dial %v error %v", url.String(), err)
		return err
	}
	session := NewTunnelSession(con)
	return session.Serve()
}

func NewTunnelSession(c *websocket.Conn) *TunnelSession {
	return &TunnelSession{
		closeLock:     sync.Mutex{},
		localConsLock: sync.RWMutex{},
		Tunnel:        stream.NewDefaultTunnel(c),
		localCons:     make(map[uint64]stream.EdgedConnection, 128),
	}
}

func (s *TunnelSession) serveLogsConnection(m *stream.Message) error {
	logCon := &stream.EdgedLogsConnection{
		ReadChan: make(chan *stream.Message, 128),
		Stop:     make(chan struct{}, 2),
	}
	if err := json.Unmarshal(m.Data, logCon); err != nil {
		klog.Errorf("unmarshal connector data error %v", err)
		return err
	}

	s.AddLocalConnection(m.ConnectID, logCon)
	return logCon.Serve(s.Tunnel)
}

func (s *TunnelSession) serveContainerExecConnection(m *stream.Message) error {
	execCon := &stream.EdgedExecConnection{
		ReadChan: make(chan *stream.Message, 128),
		Stop:     make(chan struct{}, 2),
	}
	if err := json.Unmarshal(m.Data, execCon); err != nil {
		klog.Errorf("unmarshal connector data error %v", err)
		return err
	}

	s.AddLocalConnection(m.ConnectID, execCon)
	klog.V(6).Infof("Get Exec Connection info: %+v", *execCon)
	return execCon.Serve(s.Tunnel)
}

func (s *TunnelSession) serveContainerAttachConnection(m *stream.Message) error {
	attachCon := &stream.EdgedAttachConnection{
		ReadChan: make(chan *stream.Message, 128),
		Stop:     make(chan struct{}, 2),
	}
	if err := json.Unmarshal(m.Data, attachCon); err != nil {
		klog.Errorf("unmarshal connector data error %v", err)
		return err
	}

	s.AddLocalConnection(m.ConnectID, attachCon)
	klog.V(6).Infof("Get Attach Connection info: %+v", *attachCon)
