			}
			obj.SetGroupVersionKind(gvk)
			obj.SetNamespace(test.attr[3])
			obj.SetName(test.attr[4])

			key, err := KeyFuncObj(&obj)
			assert.NoError(err)
			assert.Equal(test.stdResult, key)
		})
	}
}

