func (f FlushWriter) Write(p []byte) (n int, err error) {
	n, err = f.writer.Write(p)
	if err != nil {
		return
	}
	if f.flusher != nil {
		f.flusher.Flush()
	}
	return
}

func Wrap(w io.Writer) io.Writer {
	writer := &FlushWriter{
		writer: w,
	}
	if flusher, ok := w.(http.Flusher); ok {
		writer.flusher = flusher
	}
	return writer
}

func (m *mockFlusher) Flush() {
	m.flushCalled = true
}

func TestFlushWriter_Write(t *testing.T) {
	tests := []struct {
		name          string
		writer        io.Writer
		input         []byte
		expectedN     int
		expectedErr   error
		flushExpected bool
	}{
		{
			name:          "Write with flusher",
			writer:        &mockWriterFlusher{&bytes.Buffer{}, &mockFlusher{}},
			input:         []byte("test data"),
			expectedN:     9,
			expectedErr:   nil,
			flushExpected: true,
		},
		{
			name:          "Write without flusher",
			writer:        &bytes.Buffer{},
			input:         []byte("test data"),
			expectedN:     9,
			expectedErr:   nil,
			flushExpected: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			fw := Wrap(tt.writer)
			n, err := fw.Write(tt.input)

			assert.Equal(t, tt.expectedN, n)
			assert.Equal(t, tt.expectedErr, err)

			if tt.flushExpected {
				if mw, ok := tt.writer.(*mockWriterFlusher); ok {
					assert.True(t, mw.flushCalled)
				}
			}
		})
	}
}

func TestWrap(t *testing.T) {
	tests := []struct {
		name          string
		writer        io.Writer
		expectFlusher bool
	}{
		{
			name:          "Wrap writer with flusher",
			writer:        &mockWriterFlusher{&bytes.Buffer{}, &mockFlusher{}},
			expectFlusher: true,
		},
		{
			name:          "Wrap writer without flusher",
			writer:        &bytes.Buffer{},
			expectFlusher: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			wrapped := Wrap(tt.writer)
			fw, ok := wrapped.(*FlushWriter)
			assert.True(t, ok)

			if tt.expectFlusher {
				assert.NotNil(t, fw.flusher)
			} else {
