func (f *sharedInformerFactory) ForResource(resource schema.GroupVersionResource) (GenericInformer, error) {
	switch resource {
	// Group=apps.kubeedge.io, Version=v1alpha1
	case v1alpha1.SchemeGroupVersion.WithResource("edgeapplications"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Apps().V1alpha1().EdgeApplications().Informer()}, nil
	case v1alpha1.SchemeGroupVersion.WithResource("nodegroups"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Apps().V1alpha1().NodeGroups().Informer()}, nil

		// Group=devices, Version=v1beta1
	case v1beta1.SchemeGroupVersion.WithResource("devices"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Devices().V1beta1().Devices().Informer()}, nil
	case v1beta1.SchemeGroupVersion.WithResource("devicemodels"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Devices().V1beta1().DeviceModels().Informer()}, nil

		// Group=operations, Version=v1alpha1
	case operationsv1alpha1.SchemeGroupVersion.WithResource("imageprepulljobs"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Operations().V1alpha1().ImagePrePullJobs().Informer()}, nil
	case operationsv1alpha1.SchemeGroupVersion.WithResource("nodeupgradejobs"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Operations().V1alpha1().NodeUpgradeJobs().Informer()}, nil

		// Group=policy.kubeedge.io, Version=v1alpha1
	case policyv1alpha1.SchemeGroupVersion.WithResource("serviceaccountaccesses"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Policy().V1alpha1().ServiceAccountAccesses().Informer()}, nil

		// Group=reliablesyncs.kubeedge.io, Version=v1alpha1
	case reliablesyncsv1alpha1.SchemeGroupVersion.WithResource("clusterobjectsyncs"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Reliablesyncs().V1alpha1().ClusterObjectSyncs().Informer()}, nil
	case reliablesyncsv1alpha1.SchemeGroupVersion.WithResource("objectsyncs"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Reliablesyncs().V1alpha1().ObjectSyncs().Informer()}, nil

		// Group=rules.kubeedge.io, Version=v1
	case v1.SchemeGroupVersion.WithResource("rules"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Rules().V1().Rules().Informer()}, nil
	case v1.SchemeGroupVersion.WithResource("ruleendpoints"):
		return &genericInformer{resource: resource.GroupResource(), informer: f.Rules().V1().RuleEndpoints().Informer()}, nil

	}

	return nil, fmt.Errorf("no informer found for %v", resource)
}

