func init() {
	var filepath string
	filepath = os.Getenv("SOCKET_MODULE_CONFIG")
	if filepath == "" {
		filepath = "/etc/kubeedge/config/socket_module.yaml"
		if _, err := os.Stat(filepath); err != nil {
			return
		}
	}

	buildinModuleConfig = InitBuildinModuleConfig(filepath)
}

func InitBuildinModuleConfig(filepath string) *BuildinModuleConfig {
	moduleConfig := BuildinModuleConfig{}
	data, err := os.ReadFile(filepath)
	if err != nil {
		klog.Errorf("failed to read file %v: %v", filepath, err)
		return nil
	}
	err = yaml.Unmarshal(data, &moduleConfig.socketList)
	if err != nil {
		klog.Errorf("failed to yaml unmarshal config: %v", err)
		return nil
	}

	return &moduleConfig
}

func GetClientSocketConfig(module string) (SocketConfig, error) {
	for _, socketConfig := range buildinModuleConfig.socketList {
		if socketConfig.ModuleName == module && !socketConfig.Server {
			return socketConfig, nil
		}
	}

	return SocketConfig{}, fmt.Errorf("failed to get socket config by name(%s)", module)
}

func GetServerSocketConfig() ([]SocketConfig, error) {
	var serversSocket []SocketConfig
	for _, socketConfig := range buildinModuleConfig.socketList {
		if socketConfig.Server {
			serversSocket = append(serversSocket, socketConfig)
		}
	}

	if len(serversSocket) != 0 {
		return serversSocket, nil
	}
	return []SocketConfig{}, fmt.Errorf("failed to get socket config")
}

func InitConfigure(hub *v1alpha1.CloudHub) {
	once.Do(func() {
		if len(hub.AdvertiseAddress) == 0 {
			klog.Exit("AdvertiseAddress must be specified!")
		}

		Config = Configure{CloudHub: *hub}

		var ca, caKey, cert, key []byte

		if hub.TLSCAFile != "" {
			if block, err := certs.ReadPEMFile(hub.TLSCAFile); err == nil {
				ca = block.Bytes
				klog.Info("succeed in loading CA certificate from local directory")
			} else {
				klog.Warningf("failed to load the CA certificate file %s, err: %v", hub.TLSCAFile, err)
			}
		}
		if hub.TLSCAKeyFile != "" {
			if block, err := certs.ReadPEMFile(hub.TLSCAKeyFile); err == nil {
				caKey = block.Bytes
				klog.Info("succeed in loading CA key from local directory")
			} else {
				klog.Warningf("failed to load the CA key file %s, err: %v", hub.TLSCAKeyFile, err)
			}
		}
		if ca != nil && caKey != nil {
			Config.Ca = ca
			Config.CaKey = caKey
		} else if !(ca == nil && caKey == nil) {
			klog.Exit("Both of ca and caKey should be specified!")
		}

		if hub.TLSCertFile != "" {
			if block, err := certs.ReadPEMFile(hub.TLSCertFile); err == nil {
				cert = block.Bytes
				klog.Info("succeed in loading certificate from local directory")
			} else {
				klog.Warningf("failed to load the certificate file %s, err: %v", hub.TLSCertFile, err)
			}
		}
		if hub.TLSPrivateKeyFile != "" {
			if block, err := certs.ReadPEMFile(hub.TLSPrivateKeyFile); err == nil {
				key = block.Bytes
				klog.Info("succeed in loading private key from local directory")
			} else {
				klog.Warningf("failed to load the private key file %s, err: %v", hub.TLSPrivateKeyFile, err)
			}
		}
		if cert != nil && key != nil {
			Config.Cert = cert
			Config.Key = key
		} else if !(cert == nil && key == nil) {
			klog.Exit("Both of cert and key should be specified!")
		}
	})
}

func (c *Configure) UpdateCA(ca, caKey []byte) {
	if ca != nil {
		c.Ca = ca
	}
	if caKey != nil {
		c.CaKey = caKey
	}
}

func (c *Configure) UpdateCerts(cert, key []byte) {
