func ServeMonitor(config config.MonitorServer) {
	registerMetrics()

	mux := http.NewServeMux()
	mux.Handle("/metrics", promhttp.Handler())
	if config.EnableProfiling {
		InstallHandlerForPProf(mux)
	}

	s := http.Server{
		Addr:    config.BindAddress,
		Handler: mux,
	}

	go func() {
		ctx := beehivecontext.GetContext()
		<-ctx.Done()

		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()

		if err := s.Shutdown(ctx); err != nil {
			klog.Errorf("Server shutdown failed: %v", err)
		}
	}()

	klog.Infof("starting monitor server on addr: %s", config.BindAddress)
	klog.Exit(s.ListenAndServe())
}

func TestImageOverrider_ApplyOverrides(t *testing.T) {
	assert := assert.New(t)

	testCases := []struct {
		name           string
		rawObj         *unstructured.Unstructured
		overriderInfo  OverriderInfo
		expectedResult *unstructured.Unstructured
		expectError    bool
	}{
		{
			name: "Apply image overrides on Pod",
			rawObj: &unstructured.Unstructured{
				Object: map[string]interface{}{
					"kind": "Pod",
					"spec": map[string]interface{}{
						"containers": []interface{}{
							map[string]interface{}{
								"name":  "test-container",
								"image": "nginx:1.14.2",
							},
						},
					},
				},
			},
			overriderInfo: OverriderInfo{
				Overriders: &appsv1alpha1.Overriders{
					ImageOverriders: []appsv1alpha1.ImageOverrider{
						{
							Component: appsv1alpha1.Tag,
							Operator:  appsv1alpha1.OverriderOpReplace,
							Value:     "1.15.0",
						},
					},
				},
			},
			expectedResult: &unstructured.Unstructured{
				Object: map[string]interface{}{
					"kind": "Pod",
					"spec": map[string]interface{}{
						"containers": []interface{}{
							map[string]interface{}{
								"name":  "test-container",
								"image": "nginx:1.15.0",
							},
						},
					},
				},
			},
			expectError: false,
		},
		{
			name: "Apply image overrides on Deployment",
			rawObj: &unstructured.Unstructured{
				Object: map[string]interface{}{
					"kind": "Deployment",
					"spec": map[string]interface{}{
						"template": map[string]interface{}{
							"spec": map[string]interface{}{
								"containers": []interface{}{
									map[string]interface{}{
										"name":  "test-container",
										"image": "nginx:1.14.2",
									},
								},
							},
						},
					},
				},
			},
			overriderInfo: OverriderInfo{
				Overriders: &appsv1alpha1.Overriders{
					ImageOverriders: []appsv1alpha1.ImageOverrider{
						{
							Component: appsv1alpha1.Registry,
							Operator:  appsv1alpha1.OverriderOpReplace,
							Value:     "test-registry.com",
						},
					},
				},
			},
			expectedResult: &unstructured.Unstructured{
				Object: map[string]interface{}{
					"kind": "Deployment",
					"spec": map[string]interface{}{
						"template": map[string]interface{}{
							"spec": map[string]interface{}{
								"containers": []interface{}{
									map[string]interface{}{
										"name":  "test-container",
										"image": "test-registry.com/nginx:1.14.2",
									},
								},
							},
						},
					},
				},
			},
			expectError: false,
		},
		{
			name: "Apply image override with predicate",
			rawObj: &unstructured.Unstructured{
				Object: map[string]interface{}{
					"kind": "Pod",
					"spec": map[string]interface{}{
						"containers": []interface{}{
							map[string]interface{}{
								"name":  "test-container",
								"image": "nginx:1.14.2",
							},
						},
					},
				},
			},
			overriderInfo: OverriderInfo{
				Overriders: &appsv1alpha1.Overriders{
					ImageOverriders: []appsv1alpha1.ImageOverrider{
						{
							Component: appsv1alpha1.Repository,
							Operator:  appsv1alpha1.OverriderOpReplace,
							Value:     "test-nginx",
							Predicate: &appsv1alpha1.ImagePredicate{
								Path: "/spec/containers/0/image",
							},
						},
					},
				},
			},
			expectedResult: &unstructured.Unstructured{
				Object: map[string]interface{}{
					"kind": "Pod",
					"spec": map[string]interface{}{
						"containers": []interface{}{
							map[string]interface{}{
								"name":  "test-container",
								"image": "test-nginx:1.14.2",
							},
						},
					},
				},
			},
			expectError: false,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			overrider := &ImageOverrider{}
			err := overrider.ApplyOverrides(tc.rawObj, tc.overriderInfo)

			if tc.expectError {
				assert.Error(err)
			} else {
				assert.NoError(err)
				assert.Equal(tc.expectedResult, tc.rawObj)
			}
		})
	}
}

