func (o *NameOverrider) ApplyOverrides(rawObj *unstructured.Unstructured, overriders OverriderInfo) error {
	oldName := rawObj.GetName()
	if overriders.TargetNodeGroup != "" {
		newName := fmt.Sprintf("%s-%s", oldName, overriders.TargetNodeGroup)
		rawObj.SetName(newName)
	}
	if len(overriders.TargetNodeLabelSelector.MatchLabels) > 0 {
		suffix := CreateSuffixFromLabels(overriders.TargetNodeLabelSelector.MatchLabels)
		newName := fmt.Sprintf("%s-%s", oldName, suffix)
		rawObj.SetName(newName)
	}

	return nil
}

func CreateSuffixFromLabels(labels map[string]string) string {
	// Sort keys for deterministic hash
	keys := make([]string, 0, len(labels))
	for k := range labels {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	// Create hash from labels
	h := sha256.New()
	for _, k := range keys {
		h.Write([]byte(k))
		h.Write([]byte(labels[k]))
	}

	return fmt.Sprintf("ls-%x", h.Sum(nil)[:4]) // ls prefix indicates LabelSelector
}

func (o *OverrideManager) ApplyOverrides(rawObjs *unstructured.Unstructured, overrideInfo OverriderInfo) error {
	errs := []error{}
	for _, overrider := range o.Overriders {
		if err := overrider.ApplyOverrides(rawObjs, overrideInfo); err != nil {
			errs = append(errs, fmt.Errorf("failed to override the obj, %v", err))
		}
	}
	return errorutil.NewAggregate(errs)
}

func applyJSONPatch(obj *unstructured.Unstructured, overrides []overrideOption) error {
	jsonPatchBytes, err := json.Marshal(overrides)
	if err != nil {
		return err
	}

	patch, err := jsonpatch.DecodePatch(jsonPatchBytes)
	if err != nil {
		return err
	}

	objectJSONBytes, err := obj.MarshalJSON()
	if err != nil {
		return err
	}

	patchedObjectJSONBytes, err := patch.Apply(objectJSONBytes)
	if err != nil {
		return err
	}

	err = obj.UnmarshalJSON(patchedObjectJSONBytes)
	return err
}

