func (l *ContainerLogsConnection) Serve() error {
	defer func() {
		close(l.closeChan)
		klog.Infof("%s end successful", l.String())
	}()

	// first send connect message
	if _, err := l.SendConnection(); err != nil {
		klog.Errorf("%s send %s info error %v", l.String(), stream.MessageTypeLogsConnect, err)
		return err
	}

	for {
		select {
		case <-l.ctx.Done():
			// if apiserver request end, send close message to edge
			msg := stream.NewMessage(l.MessageID, stream.MessageTypeRemoveConnect, nil)
			for retry := 0; retry < 3; retry++ {
				if err := l.WriteToTunnel(msg); err != nil {
					klog.Warningf("%v send %s message to edge error %v", l, msg.MessageType, err)
				} else {
					break
				}
			}
			klog.Infof("%s send close message to edge successfully", l.String())
			return nil
		case <-l.EdgePeerDone():
			klog.V(6).Infof("%s find edge peer done, so stop this connection", l.String())
			return fmt.Errorf("%s find edge peer done, so stop this connection", l.String())
		}
	}
}

func (ms *ContainerMetricsConnection) String() string {
	return fmt.Sprintf("APIServer_MetricsConnection MessageID %v", ms.MessageID)
}

func (ms *ContainerMetricsConnection) WriteToAPIServer(p []byte) (n int, err error) {
	return ms.writer.Write(p)
}

func (ms *ContainerMetricsConnection) SetMessageID(id uint64) {
	ms.MessageID = id
}

func (ms *ContainerMetricsConnection) GetMessageID() uint64 {
	return ms.MessageID
}

func (ms *ContainerMetricsConnection) SetEdgePeerDone() {
	select {
	case <-ms.closeChan:
		return
	case ms.EdgePeerDone() <- struct{}{}:
		klog.V(6).Infof("success send channel deleting connection with messageID %v", ms.MessageID)
	}
}

func (ms *ContainerMetricsConnection) EdgePeerDone() chan struct{} {
	return ms.edgePeerStop
}

func (ms *ContainerMetricsConnection) WriteToTunnel(m *stream.Message) error {
	return ms.session.WriteMessageToTunnel(m)
}

func (ms *ContainerMetricsConnection) SendConnection() (stream.EdgedConnection, error) {
	connector := &stream.EdgedMetricsConnection{
		MessID: ms.MessageID,
		URL:    *ms.r.Request.URL,
		Header: ms.r.Request.Header,
	}
	connector.URL.Scheme = httpScheme
	connector.URL.Host = net.JoinHostPort(defaultServerHost, strconv.Itoa(constants.ServerPort))
	m, err := connector.CreateConnectMessage()
	if err != nil {
		return nil, err
	}
	if err := ms.WriteToTunnel(m); err != nil {
		klog.Errorf("%s write %s error %v", ms.String(), connector.String(), err)
		return nil, err
	}
	return connector, nil
}

func (ms *ContainerMetricsConnection) Serve() error {
	defer func() {
		close(ms.closeChan)
		klog.Infof("%s end successful", ms.String())
	}()

	// first send connect message
	if _, err := ms.SendConnection(); err != nil {
		klog.Errorf("%s send %s info error %v", ms.String(), stream.MessageTypeMetricConnect, err)
		return err
	}

	for {
		select {
		case <-ms.ctx.Done():
			// if apiserver request end, send close message to edge
			msg := stream.NewMessage(ms.MessageID, stream.MessageTypeRemoveConnect, nil)
			for retry := 0; retry < 3; retry++ {
				if err := ms.WriteToTunnel(msg); err != nil {
					klog.Warningf("%v send %s message to edge error %v", ms, msg.MessageType, err)
				} else {
					break
				}
			}
			klog.Infof("%s send close message to edge successfully", ms.String())
			return nil
		case <-ms.EdgePeerDone():
			klog.V(6).Infof("%s find edge peer done, so stop this connection", ms.String())
			return fmt.Errorf("%s find edge peer done, so stop this connection", ms.String())
		}
	}
}

func (s *Session) WriteMessageToTunnel(m *stream.Message) error {
	return s.tunnel.WriteMessage(m)
}

func (s *Session) Close() {
	s.apiConnlock.Lock()
	defer s.apiConnlock.Unlock()
	for _, c := range s.apiServerConn {
		c.SetEdgePeerDone()
	}
	s.tunnel.Close()
	s.tunnelClosed = true
}

func (s *Session) Serve() {
	defer s.Close()

	for {
		t, r, err := s.tunnel.NextReader()
		if err != nil {
			klog.Errorf("get %v reader error %v", s.String(), err)
			return
		}
		if t != websocket.TextMessage {
			klog.Errorf("Websocket message type must be %v type", websocket.TextMessage)
			return
		}
		message, err := stream.ReadMessageFromTunnel(r)
		if err != nil {
			klog.Errorf("Read message from tunnel %v error %v", s.String(), err)
			return
		}

		if err := s.ProxyTunnelMessageToApiserver(message); err != nil {
			klog.Errorf("Proxy tunnel message [%s] to kube-apiserver error %v", message.String(), err)
			continue
		}
	}
}

func (s *Session) ProxyTunnelMessageToApiserver(message *stream.Message) error {
	s.apiConnlock.RLock()
	defer s.apiConnlock.RUnlock()
	kubeCon, ok := s.apiServerConn[message.ConnectID]
	if !ok {
		return fmt.Errorf("can not find apiServer connection id %v in %v",
			message.ConnectID, s.String())
	}
	switch message.MessageType {
	case stream.MessageTypeRemoveConnect:
		klog.V(6).Infof("delete connection %v from %v", message.ConnectID, s.String())
		kubeCon.SetEdgePeerDone()
	case stream.MessageTypeData:
		for i := 0; i < len(message.Data); {
			n, err := kubeCon.WriteToAPIServer(message.Data[i:])
			if err != nil {
				return err
			}
			i += n
		}
	default:
	}
	return nil
}

func (s *Session) String() string {
	return fmt.Sprintf("Tunnel session [%v]", s.sessionID)
}

func (s *Session) AddAPIServerConnection(ss *StreamServer, connection APIServerConnection) (APIServerConnection, error) {
	id := atomic.AddUint64(&(ss.nextMessageID), 1)

	s.apiConnlock.Lock()
	defer s.apiConnlock.Unlock()

	if s.tunnelClosed {
		return nil, fmt.Errorf("the tunnel connection of %v has closed", s.String())
	}
	connection.SetMessageID(id)
	s.apiServerConn[id] = connection
	klog.Infof("Add a new apiserver connection %s in to %s", connection.String(), s.String())
	return connection, nil
}

func (s *Session) DeleteAPIServerConnection(con APIServerConnection) {
	s.apiConnlock.Lock()
	delete(s.apiServerConn, con.GetMessageID())
	// Other operations do not affect the release of the lock,
	// but will increase the lock holding time,
	// so the lock needs to be released in advance.
	s.apiConnlock.Unlock()
	klog.Infof("Delete a apiserver connection %s from %s", con.String(), s.String())
}

