func NewSyncKeeper() *SyncKeeper {
	return &SyncKeeper{}
}

func (k *SyncKeeper) sendToKeepChannel(msg model.Message) error {
	obj, exist := k.keeper.Load(msg.GetParentID())
	if !exist {
		klog.Errorf("failed to get sync keeper channel, message id:%s", msg.GetID())
		return fmt.Errorf("failed to get sync keeper channel")
	}

	channel := obj.(chan model.Message)
	select {
	case channel <- msg:
	default:
		klog.Error("keeper channel is full")
		return fmt.Errorf("keeper channel is full")
	}
	return nil
}

func (k *SyncKeeper) addKeepChannel(msgID string) chan model.Message {
	channel := make(chan model.Message)
	k.keeper.Store(msgID, channel)
	return channel
}

func (k *SyncKeeper) deleteKeepChannel(msgID string) {
	k.keeper.Delete(msgID)
}

func (k *SyncKeeper) Match(msg model.Message) bool {
	_, exist := k.keeper.Load(msg.GetParentID())
	return exist
}

func (k *SyncKeeper) MatchAndNotify(msg model.Message) bool {
	if matched := k.Match(msg); !matched {
		return false
	}

	if err := k.sendToKeepChannel(msg); err != nil {
		klog.Errorf("failed to send to keep channel, error:%+v", err)
	}
	return true
}

func (k *SyncKeeper) WaitResponse(msg *model.Message, deadline time.Time) (model.Message, error) {
	msgID := msg.GetID()
	channel := k.addKeepChannel(msgID)
	timer := time.NewTimer(time.Until(deadline))
	select {
	case resp := <-channel:
		timer.Stop()
		k.keeper.Delete(msgID)
		return resp, nil
	case <-timer.C:
		klog.Warningf("wait response timeout, message id:%s", msgID)
		k.keeper.Delete(msgID)
		return model.Message{}, fmt.Errorf("wait response timeout, message id:%s", msgID)
	}
}

func (f *LoggerFilter) Write(p []byte) (n int, err error) {
	output := string(p)
	if strings.Contains(output, "http: TLS handshake error from") {
		return 0, nil
	}
	klog.Error(output)
	return os.Stderr.Write(p)
}

func NewWSServer(opts Options, exOpts interface{}) *WSServer {
	extendOption, ok := exOpts.(api.WSServerOption)
	if !ok {
		panic("bad websocket option")
	}

	server := http.Server{
		Addr:      opts.Addr,
		TLSConfig: opts.TLS,
		ErrorLog:  glog.New(&LoggerFilter{}, "", glog.LstdFlags),
	}

	wsServer := &WSServer{
		options: opts,
		exOpts:  extendOption,
		server:  &server,
	}
	http.HandleFunc(extendOption.Path, wsServer.ServeHTTP)
	return wsServer
}

func (srv *WSServer) upgrade(w http.ResponseWriter, r *http.Request) *websocket.Conn {
	upgrader := websocket.Upgrader{
		HandshakeTimeout: srv.options.HandshakeTimeout,
	}
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		klog.Error("failed to upgrade to websocket")
		return nil
	}
	return conn
}

func (srv *WSServer) ServeHTTP(w http.ResponseWriter, req *http.Request) {
	if srv.exOpts.Filter != nil {
		if filtered := srv.exOpts.Filter(w, req); filtered {
			klog.Warning("failed to filter req")
			return
		}
	}

	wsConn := srv.upgrade(w, req)
	if wsConn == nil {
		return
	}

	conn := conn.NewConnection(&conn.ConnectionOptions{
		ConnType: api.ProtocolTypeWS,
		Base:     wsConn,
		ConnUse:  api.UseType(req.Header.Get("ConnectionUse")),
		Consumer: srv.options.Consumer,
		Handler:  srv.options.Handler,
		CtrlLane: lane.NewLane(api.ProtocolTypeWS, wsConn),
		State: &conn.ConnectionState{
			State:            api.StatConnected,
			Headers:          req.Header.Clone(),
			PeerCertificates: req.TLS.PeerCertificates,
		},
		AutoRoute:          srv.options.AutoRoute,
		OnReadTransportErr: srv.options.OnReadTransportErr,
	})

	// connection callback
	if srv.options.ConnNotify != nil {
		srv.options.ConnNotify(conn)
	}

	// connection manager
	if srv.options.ConnMgr != nil {
		srv.options.ConnMgr.AddConnection(conn)
	}

	// serve connection
	go conn.ServeConn()
}

func (srv *WSServer) ListenAndServeTLS() error {
	return srv.server.ListenAndServeTLS("", "")
}

func (srv *WSServer) Close() error {
	if srv.server != nil {
		return srv.server.Close()
	}
	return nil
}

func NewQuicServer(opts Options, exOpts interface{}) *QuicServer {
	extendOption, ok := exOpts.(api.QuicServerOption)
	if !ok {
		panic("bad extend options")
	}
	return &QuicServer{
		options: opts,
		exOpts:  extendOption,
	}
}

func (srv *QuicServer) serveTLS(quicConfig *quic.Config) error {
	srv.listenerLock.Lock()
	if srv.listener != nil {
		srv.listenerLock.Unlock()
		return fmt.Errorf("ListenAndServeTLS may only be called once")
	}

	listener, err := quic.ListenAddr(srv.options.Addr, srv.options.TLS, quicConfig)
	if err != nil {
		srv.listenerLock.Unlock()
		return err
	}
	srv.listener = listener
	srv.listenerLock.Unlock()

	for {
		session, err := listener.Accept()
		if err != nil {
			return err
		}

		go srv.handleSession(session)
	}
}

func (srv *QuicServer) acceptControlStream(session quic.Session) quic.Stream {
	stream, err := session.AcceptStream()
	if err != nil {
		klog.Errorf("failed to accept stream, error:%+v", err)
		return nil
	}
	return stream
}

func (srv *QuicServer) receiveHeader(lane lane.Lane) (http.Header, error) {
	var msg model.Message
	// read control message
	err := lane.ReadMessage(&msg)
	if err != nil {
		klog.Error("failed read control message")
		return nil, err
	}

	// process control message
	result := comm.RespTypeAck
	headers := make(http.Header)
	err = json.Unmarshal(msg.GetContent().([]byte), &headers)
	if err != nil {
		klog.Errorf("failed to unmarshal header, error: %+v", err)
		result = comm.RespTypeNack
	}

	// feedback the response
	resp := msg.NewRespByMessage(&msg, result)
	err = lane.WriteMessage(resp)
	if err != nil {
		klog.Errorf("failed to send response back, error:%+v", err)
		return nil, err
	}
	return headers, nil
}

func (srv *QuicServer) handleSession(session quic.Session) {
	ctrlStream := srv.acceptControlStream(session)
	if ctrlStream == nil {
		klog.Error("failed to accept control stream")
		return
	}

	ctrlLane := lane.NewLane(api.ProtocolTypeQuic, ctrlStream)
	header, err := srv.receiveHeader(ctrlLane)
	if err != nil {
		klog.Errorf("failed to complete get header, error: %+v", err)
	}

	conn := conn.NewConnection(&conn.ConnectionOptions{
		ConnType: api.ProtocolTypeQuic,
		// TODO:
		ConnUse:  api.UseTypeShare,
		Consumer: srv.options.Consumer,
		Base:     session,
		CtrlLane: lane.NewLane(api.ProtocolTypeQuic, ctrlStream),
		Handler:  srv.options.Handler,
		State: &conn.ConnectionState{
			State:            api.StatConnected,
			Headers:          header,
			PeerCertificates: session.ConnectionState().PeerCertificates,
		},
		AutoRoute:          srv.options.AutoRoute,
		OnReadTransportErr: srv.options.OnReadTransportErr,
	})

	// connection callback
	if srv.options.ConnNotify != nil {
		srv.options.ConnNotify(conn)
	}

	// connection manager
	if srv.options.ConnMgr != nil {
		srv.options.ConnMgr.AddConnection(conn)
	}

	// serve connection
	conn.ServeConn()
}

func (srv *QuicServer) getQuicConfig() *quic.Config {
	return &quic.Config{
		HandshakeTimeout:   srv.options.HandshakeTimeout,
		KeepAlive:          true,
		MaxIncomingStreams: srv.exOpts.MaxIncomingStreams,
	}
}

func (srv *QuicServer) ListenAndServeTLS() error {
	config := srv.getQuicConfig()
	return srv.serveTLS(config)
}

func (srv *QuicServer) Close() error {
	srv.listenerLock.Lock()
	defer srv.listenerLock.Unlock()

	if srv.listener != nil {
		err := srv.listener.Close()
		srv.listener = nil
		return err
	}

	return nil
}

func (s *Server) getTLSConfig(cert, key string) (*tls.Config, error) {
	var tlsConfig *tls.Config

	if s.TLSConfig == nil {
		tlsConfig = &tls.Config{}
	} else {
		tlsConfig = s.TLSConfig.Clone()
	}

	hasCert := false
	if len(tlsConfig.Certificates) > 0 ||
		tlsConfig.GetCertificate != nil {
		hasCert = true
	}
	if !hasCert || cert != "" || key != "" {
		var err error
		tlsConfig.Certificates = make([]tls.Certificate, 1)
		tlsConfig.Certificates[0], err = tls.LoadX509KeyPair(cert, key)
		if err != nil {
			return nil, err
		}
	}

	return tlsConfig, nil
}

func (s *Server) getProtoServer(opts Options) error {
	switch s.Type {
	case api.ProtocolTypeQuic:
		s.protoServer = NewQuicServer(opts, s.ExOpts)
		return nil
	case api.ProtocolTypeWS:
		s.protoServer = NewWSServer(opts, s.ExOpts)
		return nil
	}
	return fmt.Errorf("bad protocol type(%s)", s.Type)
}

func (s *Server) ListenAndServeTLS(certFile, keyFile string) error {
	tlsConfig, err := s.getTLSConfig(certFile, keyFile)
	if err != nil {
		return err
	}

	err = s.getProtoServer(Options{
		Addr:               s.Addr,
		TLS:                tlsConfig,
		ConnNotify:         s.ConnNotify,
		ConnMgr:            s.ConnMgr,
		HandshakeTimeout:   s.HandshakeTimeout,
		AutoRoute:          s.AutoRoute,
		Handler:            s.Handler,
		Consumer:           s.Consumer,
		OnReadTransportErr: s.OnReadTransportErr,
	})
	if err != nil {
		return err
	}

	return s.protoServer.ListenAndServeTLS()
}

func (s *Server) Close() error {
	return s.protoServer.Close()
}

func NewApplicationAgent() *Agent {
	defaultAgent := &Agent{
		watchSyncQueue: workqueue.NewRateLimitingQueue(workqueue.DefaultControllerRateLimiter()),
	}

	go wait.Until(func() {
		defaultAgent.GC()
	}, time.Minute*5, beehiveContext.Done())

	go defaultAgent.watchSync()

	return defaultAgent
}

func (a *Agent) Generate(ctx context.Context, verb metaserver.ApplicationVerb, option interface{}, obj runtime.Object) (*metaserver.Application, error) {
	// If the connection is lost between EdgeCore and CloudCore, we do not generate
	// the application since we can not send the application to the CloudCore
	if !connect.IsConnected() {
		return nil, connect.ErrConnectionLost
	}

	key, err := metaserver.KeyFuncReq(ctx, "")
	if err != nil {
		return nil, err
	}

	info, _ := apirequest.RequestInfoFrom(ctx)

	app, err := metaserver.NewApplication(ctx, key, verb, metaserverconfig.Config.NodeName, info.Subresource, option, obj)
	if err != nil {
		return nil, err
	}
	store, ok := a.Applications.LoadOrStore(app.Identifier(), app)
	if ok {
		app = store.(*metaserver.Application)
		app.Add()
		return app, nil
	}
	return app, nil
}

func (a *Agent) Apply(app *metaserver.Application) error {
	store, ok := a.Applications.Load(app.Identifier())
	if !ok {
		return fmt.Errorf("application %v has not been registered to agent", app.String())
	}
	app = store.(*metaserver.Application)
	switch app.GetStatus() {
	case metaserver.PreApplying:
		go a.doApply(app)
	case metaserver.Completed:
		app.Reset()
		go a.doApply(app)
	case metaserver.Rejected:
		return &app.Error
	case metaserver.Failed:
		return errors.New(app.Reason)
	case metaserver.Approved:
		return nil
	case metaserver.InApplying:
		//continue
	}
	app.Wait()
	if app.GetStatus() == metaserver.Rejected {
		return &app.Error
	}
	if app.GetStatus() != metaserver.Approved {
		return errors.New(app.Reason)
	}
	return nil
}

func (a *Agent) doApply(app *metaserver.Application) {
	defer app.Cancel()
	// encapsulate as a message
	app.Status = metaserver.InApplying
	msg := model.NewMessage("").SetRoute(metaserver.MetaServerSource, modules.DynamicControllerModuleGroup).FillBody(app)
	msg.SetResourceOperation("null", "null")
	resp, err := beehiveContext.SendSync(edgemodule.EdgeHubModuleName, *msg, 10*time.Second)
	if err != nil {
		app.Status = metaserver.Failed
		app.Reason = fmt.Sprintf("failed to access cloud Application center: %v", err)
		return
	}

	retApp, err := metaserver.MsgToApplication(resp)
	if err != nil {
		app.Status = metaserver.Failed
		app.Reason = fmt.Sprintf("failed to get Application from resp msg: %v", err)
		return
	}

	//merge returned application to local application
	app.Status = retApp.Status
	app.Reason = retApp.Reason
	app.Error = retApp.Error
	app.RespBody = retApp.RespBody
}

func (a *Agent) CloseApplication(appID string) {
	a.Applications.Delete(appID)
	a.SyncWatchAppOnConnected()
}

func (a *Agent) GC() {
	a.Applications.Range(func(key, value interface{}) bool {
		app := value.(*metaserver.Application)
		lastCloseTime := app.LastCloseTime()
		if !lastCloseTime.IsZero() && time.Since(lastCloseTime) >= time.Minute*5 {
			a.Applications.Delete(key)
		}
		return true
	})
}

func (a *Agent) SyncWatchAppOnConnected() {
	a.watchSyncQueue.Add("SyncWatchApp")
}

func (a *Agent) watchSync() {
	for a.processNextWorkItem() {
	}
}

func (a *Agent) processNextWorkItem() bool {
	key, quit := a.watchSyncQueue.Get()
	if quit {
		return false
	}
	defer a.watchSyncQueue.Done(key)

	err := a.syncWatchApplications()
	if err == nil {
		a.watchSyncQueue.Forget(key)
		return true
	}

	a.watchSyncQueue.AddRateLimited(key)
	return true
}

func (a *Agent) syncWatchApplications() error {
	watchApps := a.listWatchApplications()

	msg := model.NewMessage("").SetRoute(metaserver.MetaServerSource, modules.DynamicControllerModuleGroup).FillBody(watchApps)
	msg.SetResourceOperation(metaserver.WatchAppSync, "null")

	resp, err := beehiveContext.SendSync(edgemodule.EdgeHubModuleName, *msg, 10*time.Second)
	if err != nil {
		klog.Errorf("syncWatchApplications SendSync msg err: %v", err)
		return err
	}

	failedWatchApps, err := metaserver.MsgToApplications(resp)
	if err != nil {
		klog.Errorf("syncWatchApplications MsgToApplications err: %v", err)
		return err
	}

	klog.Errorf("failed to process watch apps: %+v", failedWatchApps)

	return nil
}

func (a *Agent) listWatchApplications() map[string]metaserver.Application {
	watchApps := make(map[string]metaserver.Application)
	a.Applications.Range(func(key, value interface{}) bool {
		app := value.(*metaserver.Application)
		if app.Verb != metaserver.Watch {
			return true
		}

		watchApps[app.ID] = *app
		return true
	})

	return watchApps
}

func TestApplicationGC(t *testing.T) {
	tests := []struct {
		name string
	}{
		{
			"Test ApplicationGC Func",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			metaserverconfig.Config.NodeName = "test"
			a := Agent{}
			requestInfo := &apirequest.RequestInfo{
				IsResourceRequest: true,
				Verb:              "GET",
				Path:              "http://127.0.0.1:10550/api/v1/nodes",
				APIPrefix:         "api",
				APIGroup:          "",
				APIVersion:        "v1",
				Resource:          "nodes",
			}
			ctx := apirequest.WithRequestInfo(context.Background(), requestInfo)
			ctx = context.WithValue(ctx, commontypes.HeaderAuthorization, "Bearer xxxx")

			connect.SetConnected(true)

			app, _ := a.Generate(ctx, "get", metav1.GetOptions{}, nil)
			app.Close()
			// make sure that the last closing time is more than 5 minutes from now
			app.Timestamp = time.Unix(1469579899, 0)
			a.GC()
			_, ok := a.Applications.Load(app.Identifier())
			if ok {
				t.Errorf("Application delete failed")
			}
		})
	}
}

func NewMessageHandler(
	KeepaliveInterval int,
	manager *session.Manager,
	reliableClient reliableclient.Interface,
	dispatcher dispatcher.MessageDispatcher,
	authorizer authorization.Authorizer) Handler {
	messageHandler := &messageHandler{
		KeepaliveInterval: KeepaliveInterval,
		SessionManager:    manager,
		MessageDispatcher: dispatcher,
		reliableClient:    reliableClient,
		authorizer:        authorizer,
	}

	// init handler that process upstream message
	messageHandler.initServerEntries()

	return messageHandler
}

func (mh *messageHandler) initServerEntries() {
	mux.Entry(mux.NewPattern("*").Op("*"), mh.HandleMessage)
}

func (mh *messageHandler) HandleMessage(container *mux.MessageContainer, _ mux.ResponseWriter) {
	nodeID := container.Header.Get("node_id")
	projectID := container.Header.Get("project_id")

	// validate message
	if container.Message == nil {
		klog.Errorf("The message is nil for node: %s", nodeID)
		return
	}

	klog.V(4).Infof("[messageHandler]get msg from node(%s): %+v", nodeID, container.Message)

	hubInfo := model.HubInfo{ProjectID: projectID, NodeID: nodeID}

	if err := mh.authorizer.AdmitMessage(*container.Message, hubInfo); err != nil {
		klog.Errorf("The message is rejected by CloudHub: node=%q, message=(%+v), error=%v", nodeID, container.Message.Router, err)
		return
	}

	// dispatch upstream message
	mh.MessageDispatcher.DispatchUpstream(container.Message, &hubInfo)
}

func (mh *messageHandler) HandleConnection(connection conn.Connection) {
	nodeID := connection.ConnectionState().Headers.Get("node_id")
	projectID := connection.ConnectionState().Headers.Get("project_id")

	if err := mh.authorizer.AuthenticateConnection(connection); err != nil {
		klog.Errorf("The connection is rejected by CloudHub: node=%q, error=%v", nodeID, err)
		return
	}

	if mh.SessionManager.ReachLimit() {
		klog.Errorf("Fail to serve node %s, reach node limit", nodeID)
		return
	}

	nodeInfo := &model.HubInfo{ProjectID: projectID, NodeID: nodeID}

	if err := mh.OnEdgeNodeConnect(nodeInfo, connection); err != nil {
		klog.Errorf("publish connect event for node %s, err %v", nodeInfo.NodeID, err)
		return
	}

	// start a goroutine for serving the node connection
	go func() {
		klog.Infof("edge node %s for project %s connected", nodeInfo.NodeID, nodeInfo.ProjectID)

		// init node message pool and add to the dispatcher
		nodeMessagePool := common.InitNodeMessagePool(nodeID)
		mh.MessageDispatcher.AddNodeMessagePool(nodeID, nodeMessagePool)

		keepaliveInterval := time.Duration(mh.KeepaliveInterval) * time.Second
		// create a node session for each edge node
		nodeSession := session.NewNodeSession(nodeID, projectID, connection,
			keepaliveInterval, nodeMessagePool, mh.reliableClient)
		// add node session to the session manager
		mh.SessionManager.AddSession(nodeSession)
		go func() {
			err := retry.Do(
				func() error {
					return controller.UpdateAnnotation(context.TODO(), nodeID)
				},
				retry.Delay(1*time.Second),
				retry.Attempts(3),
				retry.DelayType(retry.FixedDelay),
			)
			if err != nil {
				klog.Errorf(err.Error())
			}
		}()

		// start session for each edge node and it will keep running until
		// it encounters some Transport Error from underlying connection.
		nodeSession.Start()

		klog.Infof("edge node %s for project %s disConnected", nodeInfo.NodeID, nodeInfo.ProjectID)

		// clean node message pool and session
		mh.MessageDispatcher.DeleteNodeMessagePool(nodeInfo.NodeID, nodeMessagePool)
		mh.SessionManager.DeleteSession(nodeSession)
		mh.OnEdgeNodeDisconnect(nodeInfo, connection)
	}()
}

func (mh *messageHandler) OnEdgeNodeConnect(info *model.HubInfo, connection conn.Connection) error {
	err := mh.MessageDispatcher.Publish(common.ConstructConnectMessage(info, true))
	if err != nil {
		common.NotifyEventQueueError(connection, info.NodeID)
		return err
	}

	return nil
}

func (mh *messageHandler) OnEdgeNodeDisconnect(info *model.HubInfo, _ conn.Connection) {
	err := mh.MessageDispatcher.Publish(common.ConstructConnectMessage(info, false))
	if err != nil {
		klog.Errorf("fail to publish node disconnect event for node %s, reason %s", info.NodeID, err.Error())
	}
}

func (mh *messageHandler) OnReadTransportErr(nodeID, projectID string) {
	klog.Errorf("projectID %s node %s read message err", projectID, nodeID)

	nodeSession, exist := mh.SessionManager.GetSession(nodeID)
	if !exist {
		klog.Errorf("session not found for node %s", nodeID)
		return
	}

	nodeSession.Terminating()
}

func (c *Components) Hostname() string {
	return c.hostname
}

func (c *Components) SetHostname(hostname string) {
	c.hostname = hostname
}

func (c *Components) RemoveHostname() {
	c.hostname = ""
}

func (c *Components) Repository() string {
	return c.repository
}

func (c *Components) SetRepository(repository string) {
	c.repository = repository
}

func (c *Components) RemoveRepository() {
	c.repository = ""
}

func (c *Components) FullRepository() string {
	if c.hostname == "" {
		return c.repository
	}

	return c.hostname + "/" + c.repository
}

func (c Components) String() string {
	if c.tag != "" {
		return c.FullRepository() + ":" + c.tag
	} else if c.digest != "" {
		return c.FullRepository() + "@" + c.digest
	}

	return c.FullRepository()
}

func (c *Components) Tag() string {
	return c.tag
}

func (c *Components) SetTag(tag string) {
	c.tag = tag
}

func (c *Components) RemoveTag() {
	c.tag = ""
}

func (c *Components) Digest() string {
	return c.digest
}

func (c *Components) SetDigest(digest string) {
	c.digest = digest
}

func (c *Components) RemoveDigest() {
	c.digest = ""
}

func (c *Components) TagOrDigest() string {
	if c.tag != "" {
		return c.tag
	}

	return c.digest
}

func (c *Components) SetTagOrDigest(input string) {
	if anchoredTagRegexp.MatchString(input) {
		c.SetTag(input)
		c.RemoveDigest()
		return
	}

	if anchoredDigestRegexp.MatchString(input) {
		c.SetDigest(input)
		c.RemoveTag()
	}
}

func (c *Components) RemoveTagOrDigest() {
	if c.tag != "" {
		c.tag = ""
	} else if c.digest != "" {
		c.digest = ""
	}
}

func Parse(image string) (*Components, error) {
	ref, err := reference.Parse(image)
	if err != nil {
		return nil, err
	}

	comp := &Components{}
	if named, ok := ref.(reference.Named); ok {
		comp.hostname, comp.repository = SplitHostname(named.Name())
	}

	switch taggedOrDigested := ref.(type) {
	case reference.Tagged:
		comp.tag = taggedOrDigested.Tag()
	case reference.Digested:
		comp.digest = taggedOrDigested.Digest().String()
	}

	return comp, nil
}

func SplitHostname(name string) (hostname, remoteName string) {
	i := strings.IndexRune(name, '/')
	if i == -1 || (!strings.ContainsAny(name[:i], ".:") && name[:i] != "localhost") {
		hostname, remoteName = "", name
	} else {
		hostname, remoteName = name[:i], name[i+1:]
	}
	return
}

func anchored(res ...*regexp.Regexp) *regexp.Regexp {
	return match(`^` + expression(res...).String() + `$`)
}

func expression(res ...*regexp.Regexp) *regexp.Regexp {
	var s string
	for _, re := range res {
		s += re.String()
	}

	return match(s)
}

func (c *Controller) Reconcile(ctx context.Context, req controllerruntime.Request) (controllerruntime.Result, error) {
	klog.Infof("Reconciling nodeGroup %s", req.NamespacedName.Name)

	nodeGroup := &appsv1alpha1.NodeGroup{}
	if err := c.Client.Get(ctx, req.NamespacedName, nodeGroup); err != nil {
		// The resource may no longer exist, in which case we stop processing.
		if apierrors.IsNotFound(err) {
			return controllerruntime.Result{}, nil
		}

		return controllerruntime.Result{Requeue: true}, err
	}

	if !nodeGroup.DeletionTimestamp.IsZero() {
		// remove labels it added to nodes before deleting this NodeGroup
		klog.Infof("begin to remove node group label on nodes selected by nodegroup %s", nodeGroup.Name)
		if err := c.evictNodesInNodegroup(ctx, nodeGroup.Name); err != nil {
			return controllerruntime.Result{Requeue: true}, err
		}
		// this NodeGroup can be deleted now
		if err := c.removeFinalizer(ctx, nodeGroup); err != nil {
			return controllerruntime.Result{Requeue: true}, err
		}
		return controllerruntime.Result{}, nil
	}

	if !controllerutil.ContainsFinalizer(nodeGroup, NodeGroupControllerFinalizer) {
		controllerutil.AddFinalizer(nodeGroup, NodeGroupControllerFinalizer)
		if err := c.Client.Update(ctx, nodeGroup); err != nil {
			klog.Errorf("failed to add finalizer for nodegroup %s, %s", nodeGroup.Name, err)
			return controllerruntime.Result{Requeue: true}, err
		}
	}

	return c.syncNodeGroup(ctx, nodeGroup)
}

func (c *Controller) syncNodeGroup(ctx context.Context, nodeGroup *appsv1alpha1.NodeGroup) (controllerruntime.Result, error) {
	debugLogNodes := func(msg string, nodes []corev1.Node) {
		if klog.V(4).Enabled() {
			if len(nodes) == 0 {
				klog.Infof("%s: get no nodes when syncing nodegroup %s", msg, nodeGroup.Name)
				return
			}
			nodeNames := []string{}
			for i := range nodes {
				nodeNames = append(nodeNames, nodes[i].Name)
			}
			klog.Infof("%s: get %d nodes %v when syncing nodegroup %s", msg, len(nodes), nodeNames, nodeGroup.Name)
		}
	}

	newNodes, err := c.getNodesSelectedBy(ctx, nodeGroup)
	if err != nil {
		klog.Errorf("failed to get all new nodes, %s, continue with what have found.", err)
	}
	debugLogNodes("get new nodes", newNodes)

	oldNodes, err := c.getNodesByLabels(ctx, map[string]string{LabelBelongingTo: nodeGroup.Name})
	if err != nil {
		klog.Errorf("failed to get old nodes for nodegroup %s, %s.", nodeGroup.Name, err)
		return controllerruntime.Result{Requeue: true}, err
	}
	debugLogNodes("get current nodes", oldNodes)

	// delete belonging label on nodes that do not belong to this node group
	nodesDeleted, _ := nodesDiff(oldNodes, newNodes)
	debugLogNodes("get nodes to delete label", nodesDeleted)

	if err := c.evictNodes(ctx, nodesDeleted); err != nil {
		klog.Errorf("failed to evict nodes that do not belong to this nodegroup anymore, %s", err)
		return controllerruntime.Result{Requeue: true}, err
	}

	// This loop will
	// 1. add or update belonging label for nodes
	// 2. prepare NodeStatus for NodeGroup
	nodeStatusList := []appsv1alpha1.NodeStatus{}
	existingNodes := sets.NewString()
	for _, node := range newNodes {
		existingNodes = existingNodes.Insert(node.Name)
		nodeStatus := appsv1alpha1.NodeStatus{
			NodeName: node.Name,
		}
		// update ReadyStatus
		nodeReadyConditionStatus, _ := getNodeReadyConditionFromNode(&node)
		nodeStatus.ReadyStatus = conditionStatusReadyStatusMap[nodeReadyConditionStatus]
		klog.V(4).Infof("get status %s for node %s, when reconciling nodegroup %s", nodeStatus.ReadyStatus, node.Name, nodeGroup.Name)

		// try to add node group label to this node
		if err := c.addOrUpdateNodeLabel(ctx, &node, nodeGroup.Name); err != nil {
			klog.Errorf("failed to update belonging label for node %s in nodegroup %s, %s, continue to reconcile other nodes", node.Name, nodeGroup.Name, err)
			nodeStatus.SelectionStatus = appsv1alpha1.FailedSelection
			nodeStatus.SelectionStatusReason = err.Error()
		} else {
			nodeStatus.SelectionStatus = appsv1alpha1.SucceededSelection
		}
		nodeStatusList = append(nodeStatusList, nodeStatus)
	}
	// update status for nodes that do not exist but specified by node name.
	nonExistingNodes := sets.NewString(nodeGroup.Spec.Nodes...).Difference(existingNodes)
	for node := range nonExistingNodes {
		nodeStatusList = append(nodeStatusList, appsv1alpha1.NodeStatus{
			NodeName:              node,
			SelectionStatus:       appsv1alpha1.FailedSelection,
			SelectionStatusReason: "node does not exist",
			ReadyStatus:           appsv1alpha1.Unknown,
		})
	}
	sort.Slice(nodeStatusList, func(i, j int) bool {
		return nodeStatusList[i].NodeName < nodeStatusList[j].NodeName
	})
	if equality.Semantic.DeepEqual(nodeGroup.Status.NodeStatuses, nodeStatusList) {
		klog.V(4).Infof("status of nodegroup is unchanged, skip update")
		return controllerruntime.Result{}, nil
	}
	klog.V(4).Infof("status of nodegroup has changed, old: %v, new: %v", nodeGroup.Status.NodeStatuses, nodeStatusList)
	nodeGroup.Status.NodeStatuses = nodeStatusList
	if err := c.Status().Update(ctx, nodeGroup); err != nil {
		klog.Errorf("failed to update status for nodegroup %s, %s", nodeGroup.Name, err)
		return controllerruntime.Result{Requeue: true}, nil
	}
	return controllerruntime.Result{}, nil
}

func (c *Controller) SetupWithManager(ctx context.Context, mgr controllerruntime.Manager) error {
	if err := mgr.GetFieldIndexer().IndexField(ctx, &corev1.Pod{}, "spec.nodeName", func(o client.Object) []string {
		pod := o.(*corev1.Pod)
		return []string{pod.Spec.NodeName}
	}); err != nil {
		return fmt.Errorf("failed to set nodeName field selector for manager, %v", err)
	}
	return controllerruntime.NewControllerManagedBy(mgr).
		For(&appsv1alpha1.NodeGroup{}).
		Watches(&corev1.Node{}, handler.EnqueueRequestsFromMapFunc(c.nodeMapFunc)).
		Complete(c)
}

func (c *Controller) evictNodes(ctx context.Context, nodes []corev1.Node) error {
	errs := []error{}
	for _, node := range nodes {
		n := node.DeepCopy()
		ng := n.Labels[LabelBelongingTo]
		delete(n.Labels, LabelBelongingTo)
		if err := c.Client.Patch(ctx, n, client.MergeFrom(&node)); err != nil {
			klog.Errorf("failed to remove belonging label of nodegroup %s on node %s, %v", ng, node.Name, err)
			errs = append(errs, err)
		}

		if err := c.evictPodsShouldNotRunOnNode(ctx, n, ng); err != nil {
			klog.Errorf("failed to evict pods running on node %s in nodegroup %s, %v", node.Name, ng, err)
			errs = append(errs, err)
		}
	}
	return utilerrors.NewAggregate(errs)
}

func (c *Controller) evictPodsShouldNotRunOnNode(ctx context.Context, node *corev1.Node, nodegroup string) error {
	// find all pods running on this node
	runningPods := &corev1.PodList{}
	nodeNameSelector := fields.OneTermEqualSelector("spec.nodeName", node.Name)
	if err := c.Client.List(ctx, runningPods, client.MatchingFieldsSelector{Selector: nodeNameSelector}); err != nil {
		return fmt.Errorf("failed to get pods running on node %s, %v", node.Name, err)
	}

	// evict pods
	errs := []error{}
	for i := range runningPods.Items {
		pod := &runningPods.Items[i]
		nodeSelector := pod.Spec.NodeSelector
		if v, ok := nodeSelector[LabelBelongingTo]; ok && v == nodegroup {
			// TODO: in an async way?
			// Delete pod seems to block until the pod has actually stopped
			klog.V(4).Infof("try to evict pod %s/%s running on node %s", pod.Namespace, pod.Name, node.Name)
			if err := c.Client.Delete(ctx, pod); err != nil {
				errs = append(errs, fmt.Errorf("failed to delete pod %s/%s, %v", pod.Namespace, pod.Name, err))
			}
		}
	}
	return utilerrors.NewAggregate(errs)
}

func (c *Controller) removeFinalizer(ctx context.Context, nodeGroup *appsv1alpha1.NodeGroup) error {
	if !controllerutil.ContainsFinalizer(nodeGroup, NodeGroupControllerFinalizer) {
		return nil
	}
	controllerutil.RemoveFinalizer(nodeGroup, NodeGroupControllerFinalizer)
	if err := c.Client.Update(ctx, nodeGroup); err != nil {
		klog.Errorf("failed to remove finalizer on nodegroup %s, %s", nodeGroup.Name, err)
		return err
	}
	return nil
}

func (c *Controller) getNodesSelectedBy(ctx context.Context, nodeGroup *appsv1alpha1.NodeGroup) ([]corev1.Node, error) {
	errs := []error{}
	nodesByLabel, err := c.getNodesByLabels(ctx, nodeGroup.Spec.MatchLabels)
	if err != nil {
		klog.Errorf("failed to get nodes by MatchLabels %v, %s", nodeGroup.Spec.MatchLabels, err)
		errs = append(errs, err)
	}
	klog.V(4).Infof("get %d nodes that match labels in nodegroup %s", len(nodesByLabel), nodeGroup.Name)

	nodesByName, err := c.getNodesByNodeName(ctx, nodeGroup.Spec.Nodes)
	if err != nil {
		klog.Errorf("failed to get all nodes specified in the NodeGroup.Spec.Nodes, %s.", err)
		errs = append(errs, err)
	}
	klog.V(4).Infof("get %d nodes that specified by name in nodegroup %s", len(nodesByName), nodeGroup.Name)
	// remove duplicate nodes
	return nodesUnion(nodesByLabel, nodesByName), utilerrors.NewAggregate(errs)
}

func (c *Controller) nodeMapFunc(_ context.Context, obj client.Object) []controllerruntime.Request {
	node := obj.(*corev1.Node)
	if nodeGroupName, ok := node.Labels[LabelBelongingTo]; ok {
		return []controllerruntime.Request{
			{
				NamespacedName: types.NamespacedName{
					Name: nodeGroupName,
				},
			},
		}
	}
	// node do not have belonging label, either a new node will be added to a node group or an orphan node
	nodegroupList := &appsv1alpha1.NodeGroupList{}
	if err := c.Client.List(context.TODO(), nodegroupList); err != nil {
		klog.Errorf("failed to list all nodegroups, %s", err)
		return nil
	}

	for _, nodegroup := range nodegroupList.Items {
		if IfMatchNodeGroup(node, &nodegroup) {
			// this node will be added into a node group
			return []controllerruntime.Request{
				{
					NamespacedName: types.NamespacedName{
						Name: nodegroup.Name,
					},
				},
			}
		}
	}

	// an orphan node, do not reconcile
	return []controllerruntime.Request{}
}

func (c *Controller) evictNodesInNodegroup(ctx context.Context, nodeGroupName string) error {
	selector := labels.SelectorFromSet(map[string]string{LabelBelongingTo: nodeGroupName})
	nodeList := &corev1.NodeList{}
	err := c.Client.List(ctx, nodeList, &client.ListOptions{LabelSelector: selector})
	if err != nil {
		return err
	}
	return c.evictNodes(ctx, nodeList.Items)
}

func (c *Controller) getNodesByLabels(ctx context.Context, matchLabels map[string]string) ([]corev1.Node, error) {
	if matchLabels == nil {
		// Return empty when matchLabels is nil
		// Otherwise, it will select all nodes, it's not what we want
		return []corev1.Node{}, nil
	}
	selector := labels.SelectorFromSet(matchLabels)
	nodeList := &corev1.NodeList{}
	err := c.Client.List(ctx, nodeList, &client.ListOptions{LabelSelector: selector})
	if err != nil {
		return nil, err
	}
	return nodeList.Items, nil
}

func (c *Controller) getNodesByNodeName(ctx context.Context, nodeNames []string) ([]corev1.Node, error) {
	errs := []error{}
	nodes := []corev1.Node{}
	for _, name := range nodeNames {
		node := &corev1.Node{}
		if err := c.Client.Get(ctx, types.NamespacedName{Name: name}, node); err != nil {
			klog.Errorf("failed to get node %s, %s", name, err)
			errs = append(errs, err)
			continue
		}
		nodes = append(nodes, *node)
	}

	return nodes, utilerrors.NewAggregate(errs)
}

func (c *Controller) addOrUpdateNodeLabel(ctx context.Context, node *corev1.Node, nodeGroupName string) error {
	nodeLabels := node.Labels
	v, ok := nodeLabels[LabelBelongingTo]
	if ok && v == nodeGroupName {
		// nothing to do
		return nil
	}
	if ok && v != nodeGroupName {
		return fmt.Errorf("node %s has already belonged to NodeGroup %s", node.Name, v)
	}

	// !ok
	// add new label to this node
	newnode := node.DeepCopy()
	if newnode.Labels == nil {
		newnode.Labels = map[string]string{}
	}
	newnode.Labels[LabelBelongingTo] = nodeGroupName
	if err := c.Client.Patch(ctx, newnode, client.MergeFrom(node)); err != nil {
		klog.Errorf("failed to add label %s=%s to node %s, %s", LabelBelongingTo, nodeGroupName, node.Name, err)
		return err
	}
	return nil
}

func IfMatchNodeGroup(node *corev1.Node, nodegroup *appsv1alpha1.NodeGroup) bool {
	// check if nodename is in the nodegroup.Spec.Nodes
	for _, nodeName := range nodegroup.Spec.Nodes {
		if nodeName == node.Name {
			return true
		}
	}
	// check if labels of this node selected by nodegroup.Spec.MatchLabels
	selector := labels.SelectorFromSet(nodegroup.Spec.MatchLabels)
	return selector.Matches(labels.Set(node.Labels))
}

func getNodeReadyConditionFromNode(node *corev1.Node) (corev1.ConditionStatus, bool) {
	for _, condition := range node.Status.Conditions {
		if condition.Type == corev1.NodeReady {
			return condition.Status, true
		}
	}
	return "", false
}

func nodesDiff(oldNodes []corev1.Node, newNodes []corev1.Node) ([]corev1.Node, []corev1.Node) {
	nodesDeleted, nodesAdded := []corev1.Node{}, []corev1.Node{}
	m := map[string]corev1.Node{}
	for _, n := range oldNodes {
		m[n.Name] = n
	}
	for _, n := range newNodes {
		_, exist := m[n.Name]
		if exist {
			delete(m, n.Name)
		} else {
			nodesAdded = append(nodesAdded, n)
		}
	}
	for _, n := range m {
		nodesDeleted = append(nodesDeleted, n)
	}
	return nodesDeleted, nodesAdded
}

func nodesUnion(a []corev1.Node, b []corev1.Node) []corev1.Node {
	nodesMap := map[string]*corev1.Node{}
	for i := range a {
		nodesMap[a[i].Name] = &a[i]
	}
	for i := range b {
		nodesMap[b[i].Name] = &b[i]
	}

	nodes := []corev1.Node{}
	for _, node := range nodesMap {
		nodes = append(nodes, *node)
	}
	return nodes
}

func TestNodesUnion(t *testing.T) {
	cases := map[string]struct {
		list1 []corev1.Node
		list2 []corev1.Node
		want  []corev1.Node
	}{
		"nil-nil": {
			list1: nil,
			list2: nil,
			want:  []corev1.Node{},
		},
		"nil-empty": {
			list1: nil,
			list2: []corev1.Node{},
			want:  []corev1.Node{},
		},
		"nil-normal": {
			list1: nil,
			list2: []corev1.Node{
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node1",
					},
				},
			},
			want: []corev1.Node{
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node1",
					},
				},
			},
		},
		"normal-normal-different": {
			list1: []corev1.Node{
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node1",
					},
				},
			},
			list2: []corev1.Node{
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node2",
					},
				},
			},
			want: []corev1.Node{
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node1",
					},
				},
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node2",
					},
				},
			},
		},
		"normal-normal-intersection": {
			list1: []corev1.Node{
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node1",
					},
				},
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node2",
					},
				},
			},
			list2: []corev1.Node{
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node2",
					},
				},
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node3",
					},
				},
			},
			want: []corev1.Node{
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node1",
					},
				},
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node2",
					},
				},
				{
					ObjectMeta: v1.ObjectMeta{
						Name: "node3",
					},
				},
			},
		},
	}
	for n, c := range cases {
		results := nodesUnion(c.list1, c.list2)
		sort.Slice(results, func(i, j int) bool {
			return results[i].Name < results[j].Name
		})
		if !equality.Semantic.DeepEqual(results, c.want) {
			t.Errorf("failed at case: %s, want: %v, got: %v", n, c.want, results)
		}
	}
}

func IsBelongToSameGroup(targetNodeName string, epNodeName string) bool {
	if strings.Compare(targetNodeName, epNodeName) == 0 {
		return true
	}
	targetNode, err := GetDynamicResourceInformer(v1.SchemeGroupVersion.WithResource("nodes")).Lister().Get(targetNodeName)
	if err != nil {
		klog.Errorf("node informer get node %s error: %v", targetNodeName, err)
		return false
	}
	targetAccessor, err := meta.Accessor(targetNode)
	if err != nil {
		klog.Error(err)
		return false
	}

	epNode, err := GetDynamicResourceInformer(v1.SchemeGroupVersion.WithResource("nodes")).Lister().Get(epNodeName)
	if err != nil {
		klog.Errorf("node informer get endpoint slice belonging node %s error: %v", epNodeName, err)
		return false
	}
	epNodeAccessor, err := meta.Accessor(epNode)
	if err != nil {
		klog.Error(err)
		return false
	}

	return targetAccessor.GetLabels()[nodegroup.LabelBelongingTo] == epNodeAccessor.GetLabels()[nodegroup.LabelBelongingTo]
}

func GetDynamicResourceInformer(gvr schema.GroupVersionResource) informers.GenericInformer {
	return commoninformers.GetInformersManager().GetDynamicInformerFactory().ForResource(gvr)
}

func (filter *MessageFilter) AddFilterFunc(filterFunc Func) {
	filter.Filters = append(filter.Filters, filterFunc)
}

func (filter *MessageFilter) ProcessFilter(msg *model.Message) error {
	for _, filterFunc := range filter.Filters {
		err := filterFunc(msg)
		if err != nil {
			klog.Warningf("the message(%s) have been filtered", msg.GetID())
			return err
		}
	}
	return nil
}

func init() {
	filters = make(map[string]Filter)
}

func Register(f Filter) {
	filters[f.Name()] = f
	klog.Infof("Filter %s registered successfully", f.Name())
}

func GetFilters() map[string]Filter {
	return filters
}

func MessageFilter(content interface{}, targetNode string) {
	for _, f := range GetFilters() {
		if !f.NeedFilter(content) {
			continue
		}
		if objList, ok := content.(*unstructured.UnstructuredList); ok {
			for i := range objList.Items {
				f.FilterResource(targetNode, &objList.Items[i])
			}
			continue
		}
		if obj, ok := content.(*unstructured.Unstructured); ok {
			f.FilterResource(targetNode, obj)
		}
	}
}

func currentUpgradeNodeState(id, nodeName string) (v1alpha12.State, error) {
	v, ok := cache.CacheMap.Load(id)
	if !ok {
		return "", fmt.Errorf("can not find task %s", id)
	}
	task := v.(*v1alpha1.NodeUpgradeJob)
	var state v1alpha12.State
	for _, status := range task.Status.Status {
		if status.NodeName == nodeName {
			state = status.State
			break
		}
	}
	if state == "" {
		state = v1alpha12.TaskInit
	}
	return state, nil
}

func updateUpgradeNodeState(id, nodeName string, state v1alpha12.State, event fsm.Event) error {
	v, ok := cache.CacheMap.Load(id)
	if !ok {
		return fmt.Errorf("can not find task %s", id)
	}
	task := v.(*v1alpha1.NodeUpgradeJob)
	newTask := task.DeepCopy()
	status := newTask.Status.DeepCopy()
	for i, nodeStatus := range status.Status {
		if nodeStatus.NodeName == nodeName {
			status.Status[i] = v1alpha1.TaskStatus{
				NodeName: nodeName,
				State:    state,
				Event:    event.Type,
				Action:   event.Action,
				Time:     time.Now().UTC().Format(time.RFC3339),
				Reason:   event.Msg,
			}
			break
		}
	}
	err := patchStatus(newTask, *status, client.GetCRDClient())
	if err != nil {
		return err
	}
	return nil
}

func NewUpgradeNodeFSM(taskName, nodeName string) *fsm.FSM {
	fsm := &fsm.FSM{}
	return fsm.NodeName(nodeName).ID(taskName).Guard(fsmapi.UpgradeRule).StageSequence(fsmapi.UpdateStageSequence).CurrentFunc(currentUpgradeNodeState).UpdateFunc(updateUpgradeNodeState)
}

func NewUpgradeTaskFSM(taskName string) *fsm.FSM {
	fsm := &fsm.FSM{}
	return fsm.ID(taskName).Guard(fsmapi.UpgradeRule).StageSequence(fsmapi.UpdateStageSequence).CurrentFunc(currentUpgradeTaskState).UpdateFunc(updateUpgradeTaskState)
}

func currentUpgradeTaskState(id, _ string) (v1alpha12.State, error) {
	v, ok := cache.CacheMap.Load(id)
	if !ok {
		return "", fmt.Errorf("can not find task %s", id)
	}
	task := v.(*v1alpha1.NodeUpgradeJob)
	state := task.Status.State
	if state == "" {
		state = v1alpha12.TaskInit
	}
	return state, nil
}

func updateUpgradeTaskState(id, _ string, state v1alpha12.State, event fsm.Event) error {
	v, ok := cache.CacheMap.Load(id)
	if !ok {
		return fmt.Errorf("can not find task %s", id)
	}
	task := v.(*v1alpha1.NodeUpgradeJob)
	newTask := task.DeepCopy()
	status := newTask.Status.DeepCopy()

	status.Event = event.Type
	status.Action = event.Action
	status.Reason = event.Msg
	status.State = state
	status.Time = time.Now().UTC().Format(time.RFC3339)

	err := patchStatus(newTask, *status, client.GetCRDClient())

	if err != nil {
		return err
	}
	return nil
}

